deletionOutcome.src:
func deletionOutcome(state string, err error) contracts.DeletionOutcome {
	switch state {
	case deletionNoIntent:
		return contracts.DeletionNoIntent
	case config.CardDeleted:
		return contracts.DeletionCompleted
	case config.CardDeleting:
		return contracts.DeletionPendingOutcome
	}
	if err != nil {
		return contracts.DeletionUncertain
	}
	return contracts.DeletionNoIntent
}

diagnosticCode.src:
func diagnosticCode(err error) contracts.DiagnosticCode {
	switch {
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		return contracts.DiagnosticCancelled
	case errors.Is(err, session.ErrPersistFailed):
		return contracts.DiagnosticPersistence
	default:
		return contracts.DiagnosticFailure
	}
}

directoryEntry.src:
func directoryEntry(dir, name string) (contracts.DirectoryEntry, error) {
	path := filepath.Join(dir, name)
	info, err := os.Lstat(path)
	if err != nil {
		return contracts.DirectoryEntry{}, err
	}
	e := contracts.DirectoryEntry{Name: name, Mode: uint32(info.Mode()), Size: info.Size(), ModifiedAt: info.ModTime()}
	setDirectoryMetadata(&e, info)
	if info.Mode()&os.ModeSymlink != 0 {
		target, linkErr := os.Readlink(path)
		if linkErr != nil {
			return e, linkErr
		}
		e.SymlinkTarget = &target
	}
	return e, nil
}

