dueNotifications.src:
func dueNotifications(
	items []session.PendingNotification,
	schedule map[string]notificationSchedule,
	now time.Time,
) []session.PendingNotification {
	due := make([]session.PendingNotification, 0, len(items))
	blockedRecipients := make(map[string]bool)
	for _, item := range items {
		recipient := item.Message.SenderSessionID + "\x00" + item.Message.SenderActivationID
		if blockedRecipients[recipient] {
			continue
		}
		blockedRecipients[recipient] = true
		if !now.Before(schedule[item.Reply.ID].due) {
			due = append(due, item)
		}
	}
	return due
}

encodeRevision.src:
//nolint:gocognit // One exhaustive reflection boundary rejects unsupported persisted types.
func encodeRevision(b *bytes.Buffer, v reflect.Value) error {
	revisionFrame(b, v.Type().String())
	if v.Type() == reflect.TypeFor[time.Time]() {
		timestamp, ok := reflect.TypeAssert[time.Time](v)
		if !ok {
			return errors.New("invalid timestamp revision value")
		}
		revisionFrame(b, timestamp.UTC().Format(time.RFC3339Nano))
		return nil
	}
	//nolint:exhaustive // The default deliberately rejects unsupported kinds.
	switch v.Kind() {
	case reflect.Struct:
		for i := range v.NumField() {
			field := v.Type().Field(i)
			if field.Tag.Get("yaml") == "-" {
				continue
			}
			if !field.IsExported() {
				return fmt.Errorf("unsupported revision field %s", field.Name)
			}
			revisionFrame(b, field.Name)
			if err := encodeRevision(b, v.Field(i)); err != nil {
				return err
			}
		}
	case reflect.String:
		revisionFrame(b, v.String())
	case reflect.Bool:
		if v.Bool() {
			b.WriteByte(1)
		} else {
			b.WriteByte(0)
		}
	case reflect.Slice:
		if v.IsNil() {
			b.WriteByte(0)
			return nil
		}
		b.WriteByte(1)
		revisionFrame(b, strconv.Itoa(v.Len()))
		for i := range v.Len() {
			if err := encodeRevision(b, v.Index(i)); err != nil {
				return err
			}
		}
	case reflect.Map:
		if v.Type().Key().Kind() != reflect.String {
			return fmt.Errorf("unsupported revision map %s", v.Type())
		}
		if v.IsNil() {
			b.WriteByte(0)
			return nil
		}
		b.WriteByte(1)
		keys := v.MapKeys()
		sort.Slice(keys, func(i, j int) bool { return keys[i].String() < keys[j].String() })
		revisionFrame(b, strconv.Itoa(len(keys)))
		for _, key := range keys {
			if err := encodeRevision(b, key); err != nil {
				return err
			}
			if err := encodeRevision(b, v.MapIndex(key)); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("unsupported revision type %s", v.Type())
	}
	return nil
}

findGitMetadata.src:
func findGitMetadata(dir string) (bool, error) {
	for {
		_, err := os.Lstat(filepath.Join(dir, ".git"))
		if err == nil {
			return true, nil
		}
		if !errors.Is(err, os.ErrNotExist) {
			return false, fmt.Errorf("inspect Git metadata: %w", err)
		}
		// A bare repository is an unsupported context, not a normal directory.
		if _, err = os.Stat(filepath.Join(dir, "HEAD")); err == nil {
			if st, e := os.Stat(filepath.Join(dir, "objects")); e == nil && st.IsDir() {
				return true, nil
			}
		} else if !errors.Is(err, os.ErrNotExist) {
			return false, fmt.Errorf("inspect repository metadata: %w", err)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return false, nil
		}
		dir = parent
	}
}

gitStatusSettings.src:
// Read effective settings once. Status runs with only the allowlisted values;
// it never rereads the original repository, system or user configuration.
func gitStatusSettings(ctx context.Context, root string) ([]string, error) {
	data, err := runGit(ctx, root, "config", "--null", "--list", "--includes")
	if err != nil {
		return nil, fmt.Errorf("inspect Git configuration: %w", err)
	}
	var settings []string
	for record := range strings.SplitSeq(strings.TrimSuffix(string(data), "\x00"), "\x00") {
		key, value, hasValue := strings.Cut(record, "\n")
		if strings.HasPrefix(key, "filter.") && (strings.HasSuffix(key, ".clean") || strings.HasSuffix(key, ".process")) {
			return nil, errors.New("background Git inspection skips repositories with configured clean filters")
		}
		switch key {
		case "core.repositoryformatversion", "extensions.objectformat", "core.filemode", "core.ignorecase",
			"core.symlinks", "core.autocrlf", "core.eol", "core.excludesfile", "core.attributesfile",
			"core.checkstat", "core.trustctime", "status.renames", "status.renamelimit", "diff.renamelimit":
			if !hasValue {
				value = "true"
			}
			settings = append(settings, "-c", key+"="+value)
		case "core.sparsecheckout", "extensions.refstorage", "extensions.partialclone":
			return nil, fmt.Errorf("background Git inspection does not support %s", key)
		}
	}
	return settings, nil
}

hasForeignCardReferences.src:
func hasForeignCardReferences(impact session.CardReferenceImpact, ownerID string) bool {
	for _, reference := range impact.Sessions {
		if reference.DashboardID != ownerID {
			return true
		}
	}
	for dashboardID := range impact.PendingByDashboard {
		if dashboardID != ownerID {
			return true
		}
	}
	return false
}

