func isOperationTerminal(state OperationState) bool {
	switch state {
	case OperationSucceeded, OperationSucceededWithWarning, OperationFailed, OperationCancelled, OperationInterrupted:
		return true
	case OperationPending, OperationRunning:
		return false
	default:
