killGitProcess.src:
func killGitProcess(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return os.ErrProcessDone
	}
	err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	if errors.Is(err, syscall.ESRCH) {
		return os.ErrProcessDone
	}
	return err
}

lifecycleResult.src:
func lifecycleResult(evidence session.ActivationResult, err error) contracts.LifecycleResult {
	result := contracts.LifecycleResult{}
	if err != nil {
		result.Diagnostic = err.Error()
		result.DiagnosticCode = diagnosticCode(err)
	}
	switch evidence.Effect {
	case session.ActivationPublished:
		result.Effect = contracts.UsableActivation
		result.SessionID = evidence.SessionID
		result.ProcessActivationID = evidence.ProcessActivationID
		result.PID = evidence.PID
	case session.ActivationUncertain:
		result.Effect = contracts.UncertainEffect
		if err != nil {
			result.DiagnosticCode = contracts.DiagnosticUncertain
		}
		result.SessionID = evidence.SessionID
		result.PID = evidence.PID
	case session.ActivationNotPublished:
		result.Effect = contracts.NoEffect
	default:
		return contracts.LifecycleResult{
			Effect:     contracts.UncertainEffect,
			SessionID:  evidence.SessionID,
			PID:        evidence.PID,
			Diagnostic: "unknown activation evidence", DiagnosticCode: contracts.DiagnosticInvalid,
		}
	}
	if err == nil && result.Effect != contracts.UsableActivation {
		result.Diagnostic = "activation did not produce a usable process"
		result.DiagnosticCode = contracts.DiagnosticFailure
	}
	if validationErr := result.Validate(); validationErr != nil {
		return contracts.LifecycleResult{
			Effect:     contracts.UncertainEffect,
			SessionID:  evidence.SessionID,
			PID:        evidence.PID,
			Diagnostic: validationErr.Error(), DiagnosticCode: contracts.DiagnosticInvalid,
		}
	}
	return result
}

linkGitStatusMetadata.src:
// Link individual data paths into a private Git directory. In particular, no
// config, config.worktree, commondir, hooks or submodule metadata is linked.
func linkGitStatusMetadata(private, gitDir, commonDir, sharedIndex string) error {
	headPath := filepath.Join(gitDir, "HEAD")
	info, err := os.Lstat(headPath)
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() || info.Size() > gitErrorLimit {
		return errors.New("unsupported Git HEAD file")
	}
	head, err := os.ReadFile(headPath)
	if err != nil {
		return err
	}
	privateRoot, err := os.OpenRoot(private)
	if err != nil {
		return err
	}
	defer privateRoot.Close()
	if writeErr := privateRoot.WriteFile("HEAD", head, privateGitFileMode); writeErr != nil {
		return writeErr
	}
	if mkdirErr := privateRoot.Mkdir("info", privateGitDirMode); mkdirErr != nil {
		return mkdirErr
	}
	for _, item := range []struct{ name, dir string }{
		{"index", gitDir}, {"objects", commonDir}, {"refs", commonDir},
		{"packed-refs", commonDir}, {"info/exclude", commonDir}, {"info/attributes", commonDir},
	} {
		source := filepath.Join(item.dir, item.name)
		if _, statErr := os.Stat(source); errors.Is(statErr, os.ErrNotExist) {
			continue
		} else if statErr != nil {
			return statErr
		}
		if linkErr := privateRoot.Symlink(source, item.name); linkErr != nil {
			return linkErr
		}
	}
	return linkSharedGitIndex(privateRoot, gitDir, sharedIndex)
}

linkSharedGitIndex.src:
func linkSharedGitIndex(private *os.Root, gitDir, path string) error {
	if path == "" {
		return nil
	}
	name := filepath.Base(path)
	hash, hasPrefix := strings.CutPrefix(name, "sharedindex.")
	if !hasPrefix || (len(hash) != gitSHA1HexLength && len(hash) != gitSHA256HexLength) || filepath.Join(gitDir, name) != path {
		return errors.New("git returned an invalid shared index path")
	}
	if _, err := hex.DecodeString(hash); err != nil {
		return errors.New("git returned an invalid shared index name")
	}
	info, err := os.Lstat(path)
	if err != nil {
		return fmt.Errorf("inspect Git shared index: %w", err)
	}
	if !info.Mode().IsRegular() {
		return errors.New("unsupported Git shared index file")
	}
	return private.Symlink(path, name)
}

listWorkspace.src:
func listWorkspace(ctx context.Context, dir string) ([]contracts.DirectoryEntry, bool, []string, error) {
	f, err := os.Open(dir)
	if err != nil {
		return nil, false, nil, fmt.Errorf("open workspace: %w", err)
	}
	defer f.Close()
	entries := make([]contracts.DirectoryEntry, 0, workspaceMaxEntries)
	var warnings []string
	add := func(name string) {
		entry, e := directoryEntry(dir, name)
		if e != nil {
			warnings = append(warnings, fmt.Sprintf("%s: %v", name, e))
			return
		}
		entries = append(entries, entry)
	}
	add(".")
	add("..")
	truncated := false
	// Bound enumeration even when individual metadata calls fail.
	remaining := workspaceMaxEntries - workspaceDotEntries
	for remaining > 0 {
		if contextErr := ctx.Err(); contextErr != nil {
			return nil, false, nil, contextErr
		}
		batch, readErr := f.ReadDir(min(remaining, workspaceBatchSize))
		for _, entry := range batch {
			add(entry.Name())
			remaining--
		}
		if readErr == io.EOF {
			break
		}
		if readErr != nil {
			return entries, false, warnings, fmt.Errorf("read workspace directory: %w", readErr)
		}
	}
	if remaining == 0 {
		more, readErr := f.ReadDir(1)
		if len(more) > 0 {
			truncated = true
		}
		if readErr != nil && readErr != io.EOF {
			return entries, truncated, warnings, fmt.Errorf("read workspace directory: %w", readErr)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
	return entries, truncated, warnings, nil
}

