		ID: item.ID, DashboardID: item.DashboardID, CardID: item.CardID, Name: item.Name,
		Status: string(item.Status), StartedAt: item.StartedAt, PID: item.PID, WorkingDir: item.WorkingDir,
		OriginalDir: item.OriginalDir, TemporaryWorkspace: item.UseTmpWorkspace, CardDeleted: item.CardDeleted,
		Registration: string(item.Registration), RegistrationPersistence: string(item.RegistrationPersistence),
		RegistrationError: item.RegistrationErr, ActiveConversationID: item.ActiveConversationID,
	}
	card, ok := cards[item.CardID]
	if ok {
		row.FaceStyle, row.Puppet = card.FaceStyle, card.Puppet
	} else {
		row.CardUnavailable = true
	}
	for _, binding := range item.Conversations[item.CardID] {
		if binding.ID == item.ActiveConversationID && item.ActiveConversationID != "" {
			row.ActiveConversationName = binding.Name
			break
		}
	}
	unknown := disabled("session state is unknown")
	switch item.Status {
	case session.StatusRunning, session.StatusWaiting:
		row.Attach, row.Stop, row.Rename, row.OpenIDE, row.OpenTerminal = enabled(), enabled(), enabled(), enabled(), enabled()
		row.Remove, row.Relaunch = disabled("stop the session before removing it"), disabled("session is already active")
	case session.StatusTerminated:
		row.Remove, row.Relaunch, row.Switch, row.Rename = enabled(), enabled(), enabled(), enabled()
		row.Attach, row.Stop = disabled("session is stopped"), disabled("session is stopped")
		row.OpenIDE, row.OpenTerminal = enabled(), enabled()
	default:
		row.Attach, row.Relaunch, row.Stop, row.Remove, row.Switch, row.Rename = unknown, unknown, unknown, unknown, unknown, unknown
	}
	if item.CardDeleted || row.CardUnavailable {
		row.Relaunch = disabled("card is unavailable")
	}
	return row
}

updatePathSource.src:
func updatePathSource(ctx context.Context, repo sourceRepository, input contracts.SourceMutation) error {
	mutate := func(paths []string) ([]string, error) {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if input.Identity == "" {
			return append(paths, input.Path), nil
		}
		for i := range paths {
			if pathIdentity(input.Kind, paths, i) != input.Identity {
				continue
			}
			if input.Delete {
				return append(paths[:i], paths[i+1:]...), nil
			}
			paths[i] = input.Path
			return paths, nil
		}
		return nil, errSourceConflict
	}
	switch input.Kind { //nolint:exhaustive // Workspaces use their stable IDs above.
	case contracts.SourceSkills:
		return repo.UpdateSkillSources(mutate)
	case contracts.SourcePersonas:
		return repo.UpdatePersonaSources(mutate)
	case contracts.SourcePuppets:
		return repo.UpdatePuppetSources(mutate)
	default:
		return fmt.Errorf("unknown source kind %q", input.Kind)
	}
}

updateWorkspaceSource.src:
func updateWorkspaceSource(ctx context.Context, repo sourceRepository, input contracts.SourceMutation) error {
	return repo.UpdateWorkspaceSources(func(sources []config.WorkspaceSource) ([]config.WorkspaceSource, error) {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if input.Identity == "" {
			return append(sources, config.WorkspaceSource{Path: input.Path, IsRoot: input.IsRoot}), nil
		}
		for i, source := range sources {
			if workspaceIdentity(source) != input.Identity {
				continue
			}
			if input.Delete {
				return append(sources[:i], sources[i+1:]...), nil
			}
			sources[i].Path, sources[i].IsRoot = input.Path, input.IsRoot
			return sources, nil
		}
		return nil, errSourceConflict
	})
}

watchReportChanges.src:
// watchReportChanges rearms before notifying consumers so a change during
// rearming remains observable even when notices coalesce.
func watchReportChanges(
	ctx context.Context,
	cancel context.CancelFunc,
	shutdown <-chan struct{},
	signal, scope <-chan struct{},
	changed, scopeChanged func() <-chan struct{},
	check func() error,
	sub *reportSubscription,
) {
	defer cancel()
	for {
		select {
		case <-shutdown:
			sub.finish(errors.New("session manager shut down"))
			return
		case <-ctx.Done():
			sub.finish(ctx.Err())
			return
		case <-scope:
			scope = scopeChanged()
			if err := check(); err != nil {
				sub.finish(err)
				return
			}
		case <-signal:
			signal = changed()
			if err := check(); err != nil {
				sub.finish(err)
				return
			}
			select {
			case sub.changes <- struct{}{}:
			default:
			}
		}
	}
}

workspaceIdentity.src:
func workspaceIdentity(source config.WorkspaceSource) string {
	return source.ID + ":" + sourceToken(source)
}

OperationRunner.Cancel.src:
// Cancel requests cancellation after revalidating the caller activation.
func (r *OperationRunner) Cancel(token, operationID string) (Operation, error) {
	_, err := r.Get(token, operationID)
	if err != nil {
		return Operation{}, err
	}
	r.mu.Lock()
	key := r.byID[operationID]
	op := r.records[key]
	if !isOperationTerminal(op.State) {
		op.CancellationRequested = true
		op.UpdatedAt = time.Now().UTC()
		if cancel := r.running[operationID]; cancel != nil {
			cancel()
		}
		if saveErr := r.saveLocked(op); saveErr != nil {
			op.Warning = "cancellation requested but journal update failed"
		}
	}
	cloned := cloneOperation(op)
	r.mu.Unlock()
	return cloned, nil
}

OperationRunner.Get.src:
// Get returns a copied operation outcome to its originating session only.
func (r *OperationRunner) Get(token, operationID string) (Operation, error) {
	caller, err := r.service.ResolveCaller(token)
	if err != nil {
		return Operation{}, err
	}
	return r.getForCaller(caller, operationID)
}

OperationRunner.Replay.src:
// Replay checks durable idempotency before rejecting an absent target.
func (r *OperationRunner) Replay(ctx context.Context, token, requestID, kind, target string, arguments any) (Operation, bool, error) {
	if _, err := uuid.Parse(requestID); err != nil {
		return Operation{}, false, reject("invalid_request", "request_id must be a UUID")
	}
	caller, err := r.service.ResolveCaller(token)
	if err != nil {
		return Operation{}, false, err
	}
	encoded, err := json.Marshal(arguments)
	if err != nil {
		return Operation{}, false, fmt.Errorf("encode operation arguments: %w", err)
	}
	fingerprint := operationFingerprint(kind, target, encoded)
	key := operationKey{caller: caller.SessionID, request: requestID}
	r.mu.Lock()
	if r.loadErr != nil {
		r.mu.Unlock()
		return Operation{}, false, reject("journal_unavailable", "lifecycle operations are temporarily unavailable")
	}
	previous := r.records[key]
	if previous == nil {
		r.mu.Unlock()
		return Operation{}, false, nil
	}
	if previous.DashboardID != caller.DashboardID || previous.Fingerprint != fingerprint {
		r.mu.Unlock()
		return Operation{}, false, reject("request_id_conflict", "request_id was already used with different arguments")
	}
	cloned := cloneOperation(previous)
	r.mu.Unlock()
	if authErr := r.service.authorizeExistingOperation(caller, cloned); authErr != nil {
		return Operation{}, false, authErr
	}
	if !isOperationTerminal(cloned.State) {
		cloned, err = r.wait(ctx, cloned.ID)
		if err != nil {
			return Operation{}, false, err
		}
		if authErr := r.service.authorizeExistingOperation(caller, cloned); authErr != nil {
			return Operation{}, false, authErr
		}
		return cloned, true, nil
	}
	return cloned, true, nil
}

OperationRunner.Shutdown.src:
// Shutdown stops admission, cancels queued/preparing work, and joins workers.
func (r *OperationRunner) Shutdown() {
	r.mu.Lock()
	if r.dispatchCancel != nil {
		r.dispatchCancel()
	}
	r.mu.Unlock()
	r.dispatcher.Wait()
	r.mu.Lock()
	if !r.closed {
		r.closed = true
		for _, cancel := range r.running {
			cancel()
		}
		close(r.queue)
	}
	r.mu.Unlock()
	r.workers.Wait()
}

