OperationRunner.accept.src:
func (r *OperationRunner) accept(
	callerID, dashboardID string, key operationKey, requestID, kind, target string, encoded []byte,
	fingerprint string, authority taskAuthority,
	apply func(context.Context, Operation) (json.RawMessage, error),
	onCancel func(Operation),
	beforeAccept func(func() error) error,
) (Operation, bool, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return Operation{}, false, reject("shutting_down", "Kankuro is shutting down")
	}
	if r.loadErr != nil {
		return Operation{}, false, reject("journal_unavailable", "lifecycle operations are temporarily unavailable")
	}
	if previous := r.records[key]; previous != nil {
		if previous.DashboardID != dashboardID || previous.Fingerprint != fingerprint {
			return Operation{}, false, reject("request_id_conflict", "request_id was already used with different arguments")
		}
		return cloneOperation(previous), false, nil
	}
	if len(r.queue) == cap(r.queue) {
		return Operation{}, false, reject("capacity_exhausted", "lifecycle operation capacity is full; retry later")
	}
	if kind == createSessionOperation && target == "" {
		target = uuid.NewString()
	}
	now := time.Now().UTC()
	op := &Operation{ID: uuid.NewString(), CallerSession: callerID, DashboardID: dashboardID, RequestID: requestID,
		Kind: kind, State: OperationPending, TargetSession: target, Fingerprint: fingerprint,
		Arguments: encoded, CreatedAt: now, UpdatedAt: now}
	persistAcceptance := func() error { return r.saveLocked(op) }
	if beforeAccept != nil {
		if admitErr := beforeAccept(persistAcceptance); admitErr != nil {
			return Operation{}, false, admitErr
		}
	} else if saveErr := persistAcceptance(); saveErr != nil {
		return Operation{}, false, reject("journal_unavailable", "lifecycle operations are temporarily unavailable")
	}
	r.records[key], r.byID[op.ID] = op, key
	opCtx, cancel := context.WithTimeout(context.Background(), operationTimeout)
	r.running[op.ID] = cancel
	r.queue <- operationTask{operationID: op.ID, authority: authority, ctx: opCtx, cancel: cancel, apply: apply, onCancel: onCancel}
	return cloneOperation(op), true, nil
}

OperationRunner.completeLocked.src:
func (r *OperationRunner) completeLocked(op *Operation, task operationTask, result json.RawMessage, err error) {
	op.Result = append(json.RawMessage(nil), result...)
	r.setOperationOutcome(op, task, err)
	r.finishLocked(op)
}

OperationRunner.dispatchNotification.src:
//nolint:funlen // The admission transaction must keep identity, reservation, and journal acceptance together.
func (r *OperationRunner) dispatchNotification(item session.PendingNotification) {
	store := r.service.sessions.Messages()
	n := item.Reply.Notification
	if n.State == session.NotificationAccepted {
		r.reconcileNotification(item)
		return
	}
	requestID := n.RequestID
	if requestID == "" {
		requestID = uuid.NewSHA1(uuid.NameSpaceURL, []byte(fmt.Sprintf("kankuro-report-notification:%s:%d", item.Reply.ID, n.Attempt))).
			String()
		if err := store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationPending,
			func(v *session.ReplyNotification) { v.RequestID = requestID },
		); err != nil {
			return
		}
	}
	target, found := r.service.sessions.GetSession(item.Message.SenderSessionID)
	inventory, inventoryErr := r.service.scope.inventory()
	if inventoryErr != nil {
		return
	}
	if !found || target.ActivationID != item.Message.SenderActivationID || target.Status == session.StatusTerminated ||
		!target.KankuroMCPEnabled ||
		!inventory.allowsSession(item.Message.DashboardID, item.Message.SenderSessionID) {
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationPending,
			func(v *session.ReplyNotification) {
				v.State = session.NotificationUnavailable
				v.FailureCode = notificationStaleActivation
				v.FailureMessage = "original sender activation is unavailable"
			},
		)
		return
	}
	admission, err := r.service.sessions.ReserveReportNotification(item.Message.ID, item.Reply.ID)
	if err != nil {
		var rejected *session.MessagingError
		if errors.As(err, &rejected) && rejected.Code == notificationStaleActivation {
			_ = store.UpdateNotification(
				item.Message.ID,
				item.Reply.ID,
				n.Attempt,
				session.NotificationPending,
				func(v *session.ReplyNotification) {
					v.State = session.NotificationUnavailable
					v.FailureCode = notificationStaleActivation
					v.FailureMessage = "original sender activation is unavailable"
				},
			)
		}
		return
	}
	messageID := uuid.NewSHA1(uuid.NameSpaceURL, []byte("kankuro-report-message:"+requestID)).String()
	intent := session.MessageRecord{
		ID:                    messageID,
		Kind:                  driver.PromptReportNotification,
		OriginalMessageID:     item.Message.ID,
		ReplyID:               item.Reply.ID,
		ReportKind:            item.Reply.Kind,
		DashboardID:           item.Message.DashboardID,
		SenderSessionID:       item.Reply.SenderSessionID,
		SenderActivationID:    item.Reply.SenderActivationID,
		RecipientSessionID:    item.Message.SenderSessionID,
		RecipientActivationID: item.Message.SenderActivationID,
		Text:                  "report notification",
	}
	delivery := &preparedDelivery{service: r.service, store: store, admission: admission, intent: intent, requestID: requestID}
	defer delivery.releaseUnpublished()
	fingerprintData, err := json.Marshal(intent)
	if err != nil {
		return
	}
	delivery.fingerprint = session.SendFingerprint(intent.RecipientSessionID, intent.RecipientActivationID, string(fingerprintData))
	args, err := json.Marshal(delivery.arguments())
	if err != nil {
		return
	}
	authority := notificationAuthority{service: r.service, messageID: item.Message.ID, replyID: item.Reply.ID}
	operation, _, err := r.accept(
		intent.SenderSessionID,
		intent.DashboardID,
		operationKey{caller: intent.SenderSessionID, request: requestID},
		requestID,
		messageOperation,
		intent.RecipientSessionID,
		args,
		operationFingerprint(messageOperation, intent.RecipientSessionID, args),
		authority,
		delivery.submission(),
		delivery.cancel,
		delivery.publish,
	)
	if err == nil && operation.ID != "" {
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationAccepted,
			func(v *session.ReplyNotification) { v.OperationID = operation.ID },
		)
	}
}

OperationRunner.dispatchNotifications.src:
func (r *OperationRunner) dispatchNotifications(ctx context.Context) {
	defer r.dispatcher.Done()
	store := r.service.sessions.Messages()
	schedule := make(map[string]notificationSchedule)
	for {
		changed := store.Changed()
		now := time.Now()
		items := store.Notifications()
		retained := make(map[string]bool, len(items))
		for _, item := range items {
			retained[item.Reply.ID] = true
		}
		for _, item := range dueNotifications(items, schedule, now) {
			entry := schedule[item.Reply.ID]
			r.dispatchNotification(item)
			entry.delay = nextNotificationDelay(entry.delay)
			entry.due = now.Add(entry.delay)
			schedule[item.Reply.ID] = entry
		}
		for id := range schedule {
			if !retained[id] {
				delete(schedule, id)
			}
		}
		timer := time.NewTimer(notificationRetryInitial)
		select {
		case <-ctx.Done():
			timer.Stop()
			return
		case <-changed:
			timer.Stop()
		case <-timer.C:
		}
	}
}

OperationRunner.finishLocked.src:
func (r *OperationRunner) finishLocked(op *Operation) {
	op.UpdatedAt = time.Now().UTC()
	delete(r.running, op.ID)
	if err := r.saveLocked(op); err != nil {
		op.Warning = "outcome observed but operation journal update failed"
		if op.State == OperationSucceeded {
			op.State = OperationSucceededWithWarning
		}
	}
}

OperationRunner.getForCaller.src:
func (r *OperationRunner) getForCaller(caller CallerContext, operationID string) (Operation, error) {
	r.mu.Lock()
	key, ok := r.byID[operationID]
	if !ok || key.caller != caller.SessionID || r.records[key].DashboardID != caller.DashboardID {
		r.mu.Unlock()
		return Operation{}, reject("not_found", "operation was not found")
	}
	operation := cloneOperation(r.records[key])
	r.mu.Unlock()
	if err := r.service.authorizeExistingOperation(caller, operation); err != nil {
		return Operation{}, err
	}
	return operation, nil
}

OperationRunner.load.src:
func (r *OperationRunner) load() error {
	entries, err := os.ReadDir(r.dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		if loadErr := r.loadRecord(entry.Name()); loadErr != nil {
			return loadErr
		}
	}
	return nil
}

OperationRunner.loadRecord.src:
func (r *OperationRunner) loadRecord(name string) error {
	path := filepath.Join(r.dir, name)
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	var op Operation
	if decodeErr := json.Unmarshal(data, &op); decodeErr != nil {
		return fmt.Errorf("corrupt operation record %s: %w", name, decodeErr)
	}
	key := operationKey{caller: op.CallerSession, request: op.RequestID}
	if key.caller == "" || key.request == "" || op.ID == "" {
		return fmt.Errorf("incomplete operation identity in journal record %s", name)
	}
	if r.records[key] != nil || r.byID[op.ID].request != "" {
		return fmt.Errorf("duplicate operation identity in journal: %s", name)
	}
	if !isOperationTerminal(op.State) {
		op.State = OperationInterrupted
		op.Warning = "effect may have occurred; inspect current sessions before retrying"
		op.UpdatedAt = time.Now().UTC()
		if saveErr := r.saveLocked(&op); saveErr != nil {
			return saveErr
		}
	}
	r.records[key], r.byID[op.ID] = &op, key
	return nil
}

OperationRunner.monitorCaller.src:
func (r *OperationRunner) monitorCaller(task operationTask, operation Operation) {
	ticker := time.NewTicker(operationCallerPoll)
	defer ticker.Stop()
	for {
		select {
		case <-task.ctx.Done():
			return
		case <-ticker.C:
			if err := task.authority.monitor(operation); err != nil {
				task.cancel()
				return
			}
		}
	}
}

OperationRunner.reconcileNotification.src:
func (r *OperationRunner) reconcileNotification(item session.PendingNotification) {
	store := r.service.sessions.Messages()
	n := item.Reply.Notification
	if n.OperationID == "" && n.RequestID != "" {
		r.mu.Lock()
		operation := r.records[operationKey{caller: item.Reply.SenderSessionID, request: n.RequestID}]
		operationID := ""
		if operation != nil {
			operationID = operation.ID
		}
		r.mu.Unlock()
		if operationID != "" {
			_ = store.UpdateNotification(
				item.Message.ID,
				item.Reply.ID,
				n.Attempt,
				session.NotificationAccepted,
				func(v *session.ReplyNotification) { v.OperationID = operationID },
			)
		}
	}
	message, err := store.GetMessage(n.MessageID)
	if err != nil {
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationAccepted,
			func(v *session.ReplyNotification) {
				v.State = session.NotificationUncertain
				v.FailureCode = "history_unavailable"
				v.FailureMessage = "delivery evidence is unavailable"
			},
		)
		return
	}
	switch message.Delivery {
	case session.MessageAccepted, session.MessageSubmitting:
		return
	case session.MessageSubmitted:
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationAccepted,
			func(v *session.ReplyNotification) { v.State = session.NotificationSubmitted },
		)
	case session.MessageUncertain:
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationAccepted,
			func(v *session.ReplyNotification) {
				v.State = session.NotificationUncertain
				v.FailureCode = "delivery_uncertain"
				v.FailureMessage = "prompt delivery could not be established safely"
			},
		)
	case session.MessageNotSubmitted:
		_ = store.UpdateNotification(
			item.Message.ID,
			item.Reply.ID,
			n.Attempt,
			session.NotificationAccepted,
			func(v *session.ReplyNotification) {
				v.State = session.NotificationPending
				v.Attempt++
				v.RequestID = ""
				v.MessageID = ""
				v.OperationID = ""
			},
		)
	}
}

OperationRunner.saveLocked.src:
func (r *OperationRunner) saveLocked(op *Operation) error {
	if err := os.MkdirAll(r.dir, 0o700); err != nil {
		return err
	}
	data, err := json.MarshalIndent(op, "", "  ")
	if err != nil {
		return err
	}
	path := filepath.Join(r.dir, op.CallerSession+"-"+op.RequestID+".json")
	if r.writeFileAtomic != nil {
		return r.writeFileAtomic(path, data)
	}
	return fsutil.WriteFileAtomic(path, data, operationFileMode)
}

OperationRunner.snapshot.src:
func (r *OperationRunner) snapshot(operationID string) Operation {
	r.mu.Lock()
	defer r.mu.Unlock()
	key, ok := r.byID[operationID]
	if !ok {
		return Operation{}
	}
	return cloneOperation(r.records[key])
}

OperationRunner.startDispatcher.src:
func (r *OperationRunner) startDispatcher() {
	if r.service == nil || r.service.sessions.Messages() == nil || r.loadErr != nil {
		return
	}
	r.mu.Lock()
	if r.closed || r.dispatchCancel != nil {
		r.mu.Unlock()
		return
	}
	ctx, cancel := context.WithCancel(context.Background())
	r.dispatchCancel = cancel
	r.dispatcher.Add(1)
	r.mu.Unlock()
	go r.dispatchNotifications(ctx)
}

OperationRunner.submit.sig:
func (r *OperationRunner) submit(
	ctx context.Context, token, requestID, kind, target string, arguments any,
	beforeAccept func(func() error) error,
	apply func(context.Context, Operation) (json.RawMessage, error), onCancel func(Operation),
) (Operation, error)

OperationRunner.submit.src:
func (r *OperationRunner) submit(
	ctx context.Context, token, requestID, kind, target string, arguments any,
	beforeAccept func(func() error) error,
	apply func(context.Context, Operation) (json.RawMessage, error), onCancel func(Operation),
) (Operation, error) {
	if _, err := uuid.Parse(requestID); err != nil {
		return Operation{}, reject("invalid_request", "request_id must be a UUID")
	}
	caller, err := r.service.ResolveCaller(token)
	if err != nil {
		return Operation{}, err
	}
	encoded, err := json.Marshal(arguments)
	if err != nil {
		return Operation{}, fmt.Errorf("encode operation arguments: %w", err)
	}
	fingerprint := operationFingerprint(kind, target, encoded)
	key := operationKey{caller: caller.SessionID, request: requestID}
	op, accepted, err := r.accept(
		caller.SessionID,
		caller.DashboardID,
		key,
		requestID,
		kind,
		target,
		encoded,
		fingerprint,
		controllerAuthority{service: r.service, token: token},
		apply,
		onCancel,
		beforeAccept,
	)
	if err != nil {
		return op, err
	}
	if !accepted {
		if authErr := r.service.authorizeExistingOperation(caller, op); authErr != nil {
			return Operation{}, authErr
		}
		if isOperationTerminal(op.State) {
			return op, nil
		}
		op, err = r.wait(ctx, op.ID)
		if err != nil {
			return Operation{}, err
		}
		return op, r.service.authorizeExistingOperation(caller, op)
	}
	return r.wait(ctx, op.ID)
}

OperationRunner.submitWithRecovery.sig:
func (r *OperationRunner) submitWithRecovery(
	ctx context.Context, token, requestID, kind, target string, arguments any,
	beforeAccept func(func() error) error,
	apply func(context.Context, Operation) (json.RawMessage, error), onCancel func(Operation),
) (Operation, error)

OperationRunner.submitWithRecovery.src:
func (r *OperationRunner) submitWithRecovery(
	ctx context.Context, token, requestID, kind, target string, arguments any,
	beforeAccept func(func() error) error,
	apply func(context.Context, Operation) (json.RawMessage, error), onCancel func(Operation),
) (Operation, error) {
	operation, err := r.submit(ctx, token, requestID, kind, target, arguments, beforeAccept, apply, onCancel)
	if operation.ID != "" || err == nil {
		return operation, err
	}
	caller, authErr := r.service.ResolveCaller(token)
	if authErr != nil {
		return operation, err
	}
	parsed, parseErr := uuid.Parse(requestID)
	if parseErr != nil {
		return operation, err
	}
	key := operationKey{caller: caller.SessionID, request: parsed.String()}
	r.mu.Lock()
	if accepted := r.records[key]; accepted != nil {
		operation = cloneOperation(accepted)
	}
	r.mu.Unlock()
	return operation, err
}

OperationRunner.wait.src:
func (r *OperationRunner) wait(ctx context.Context, operationID string) (Operation, error) {
	deadline := time.NewTimer(operationWait)
	defer deadline.Stop()
	for {
		current := r.snapshot(operationID)
		if isOperationTerminal(current.State) {
			return current, nil
		}
		select {
		case <-ctx.Done():
			return current, nil
		case <-deadline.C:
			return current, nil
		case <-time.After(operationPollInterval):
		}
	}
}

OperationRunner.worker.src:
func (r *OperationRunner) worker() {
	defer r.workers.Done()
	for task := range r.queue {
		r.execute(task)
	}
}

