Service.ConfirmCardDeletion.sig:
func (s *Service) ConfirmCardDeletion(
	ctx context.Context,
	ownerID, cardID, token string,
	foreignConfirmed bool,
) (CardDeletionResult, error)

Service.ConfirmCardDeletion.src:
// ConfirmCardDeletion persists a deletion intent after rechecking the token,
// then cancels and drains pending activations before removing configuration.
// A non-nil error after intent persistence leaves a retryable deleting state.
func (s *Service) ConfirmCardDeletion(
	ctx context.Context,
	ownerID, cardID, token string,
	foreignConfirmed bool,
) (CardDeletionResult, error) {
	if err := ctx.Err(); err != nil {
		return CardDeletionResult{State: deletionNoIntent}, err
	}
	writer, ok := s.repo.(tombstoneWriter)
	if !ok {
		return CardDeletionResult{State: deletionNoIntent}, errors.New("card deletion storage unavailable")
	}
	intentAttempted := false
	err := s.sessions.WithCardReferencesAndSnapshot(cardID, func(impact session.CardReferenceImpact, sessions []session.Snapshot) error {
		card, err := s.cardOwnedBy(ownerID, cardID, impact, sessions)
		if err != nil {
			return err
		}
		if errAt107 := s.validateCardConfirmationLocked(token, ownerID, card, impact); errAt107 != nil {
			return errAt107
		}
		if hasForeignCardReferences(impact, ownerID) && !foreignConfirmed {
			return errors.New("foreign card references require explicit confirmation")
		}
		if errAt113 := ctx.Err(); errAt113 != nil {
			return errAt113
		}
		pending, err := cardPendingCleanup(impact, sessions)
		if err != nil {
			return err
		}
		intentAttempted = true
		return writer.BeginCardDeletionWithPending(card, pending)
	})
	if err != nil {
		if !intentAttempted {
			return CardDeletionResult{State: deletionNoIntent}, err
		}
		return CardDeletionResult{}, err
	}
	result, err := s.RetryCardDeletion(ctx, ownerID, cardID)
	if result.State == "" {
		// Intent is already durable, even if admission for the cleanup failed.
		result.State = config.CardDeleting
	}
	return result, err
}

Service.ConfirmDashboardDeletion.sig:
func (s *Service) ConfirmDashboardDeletion(
	ctx context.Context,
	dashboardID, token string,
	foreignConfirmed bool,
) (DashboardDeletionResult, error)

Service.ConfirmDashboardDeletion.src:
// ConfirmDashboardDeletion writes the complete manifest under admission before
// any teardown, after rechecking the token and explicit foreign-impact consent.
func (s *Service) ConfirmDashboardDeletion(
	ctx context.Context,
	dashboardID, token string,
	foreignConfirmed bool,
) (DashboardDeletionResult, error) {
	if err := ctx.Err(); err != nil {
		return DashboardDeletionResult{State: deletionNoIntent}, err
	}
	writer, ok := s.repo.(dashboardDeletionWriter)
	if !ok {
		return DashboardDeletionResult{State: deletionNoIntent}, errors.New("dashboard deletion storage unavailable")
	}
	var manifest config.DashboardDeletion
	intentAttempted := false
	err := s.sessions.WithAdmissionSnapshot(func(snapshot session.AdmissionSnapshot) error {
		current, foreign, errAt55 := s.prepareDashboardDeletion(dashboardID, snapshot)
		if errAt55 != nil {
			return errAt55
		}
		digest, errAt55 := dashboardImpactDigest(current, snapshot.Revision)
		if errAt55 != nil {
			return errAt55
		}
		s.confirmationMu.Lock()
		confirmation, exists := s.dashboardConfirmations[token]
		s.confirmationMu.Unlock()
		if !exists || confirmation.dashboardID != dashboardID || !time.Now().Before(confirmation.expires) || confirmation.digest != digest {
			return errors.New("dashboard deletion impact changed or confirmation expired; review it again")
		}
		if foreign && !foreignConfirmed {
			return errors.New("foreign card references require explicit confirmation")
		}
		if errAt72 := ctx.Err(); errAt72 != nil {
			return errAt72
		}
		intentAttempted = true
		if errAt75 := writer.BeginDashboardDeletion(current); errAt75 != nil {
			return errAt75
		}
		manifest = current
		return nil
	})
	if err != nil {
		if !intentAttempted {
			return DashboardDeletionResult{State: deletionNoIntent}, err
		}
		return DashboardDeletionResult{}, err
	}
	result, err := s.RetryDashboardDeletion(ctx, dashboardID)
	if result.State == "" {
		result = DashboardDeletionResult{State: config.CardDeleting, Manifest: manifest}
	}
	return result, err
}

