Service.ListDashboards.src:
func (s *Service) ListDashboards() ([]config.Dashboard, error) {
	dashboards, err := s.repo.ListDashboards()
	if err != nil {
		return nil, err
	}
	manifests, err := s.repo.ListDashboardDeletions()
	if err != nil {
		return nil, err
	}
	for _, manifest := range manifests {
		found := false
		for index := range dashboards {
			if dashboards[index].ID == manifest.DashboardID {
				dashboards[index].State = config.DashboardDeleting
				found = true
				break
			}
		}
		if !found {
			dashboards = append(
				dashboards,
				config.Dashboard{
					ID:          manifest.DashboardID,
					Name:        manifest.Name,
					Description: manifest.Description,
					State:       config.DashboardDeleting,
				},
			)
		}
	}
	deletedDashboards, err := s.repo.ListDashboardTombstones()
	if err != nil {
		return nil, err
	}
	for _, tombstone := range deletedDashboards {
		for _, dashboard := range dashboards {
			if dashboard.ID == tombstone.ID && dashboard.State != config.DashboardDeleting {
				return nil, errors.New("active dashboard conflicts with deleted identity")
			}
		}
	}
	sort.Slice(dashboards, func(i, j int) bool {
		if dashboards[i].Name == dashboards[j].Name {
			return dashboards[i].ID < dashboards[j].ID
		}
		return dashboards[i].Name < dashboards[j].Name
	})
	return dashboards, nil
}

Service.ListSessions.src:
// ListSessions returns summaries in the current dashboard, excluding the caller.
// ListSessions authenticates the caller before returning dashboard summaries.
func (s *Service) ListSessions(token string) ([]SessionDiscovery, error) {
	caller, err := s.ResolveCaller(token)
	if err != nil {
		return nil, err
	}
	out := make([]SessionDiscovery, 0)
	deleted, err := s.deletedCardIDs()
	if err != nil {
		return nil, err
	}
	for _, item := range s.sessions.List() {
		if item.ID == caller.SessionID || !s.scope.AllowsSession(caller.SessionID, item.ID) {
			continue
		}
		out = append(out, SessionDiscovery{
			ID: item.ID, DashboardID: item.DashboardID, CardDeleted: deleted[item.CardID], Name: item.Name, CardID: item.CardID,
			Status: item.Status, Activity: item.LifecycleActivity,
		})
	}
	return out, nil
}

Service.LoadCardEditor.src:
// LoadCardEditor returns only editable values, with an opaque concurrency identity.
func (s *Service) LoadCardEditor(dashboardID, cardID string) (contracts.CardEditorData, error) {
	data, err := s.readDashboardData(dashboardID)
	if err != nil {
		return contracts.CardEditorData{}, err
	}
	var card config.IDCard
	found := false
	for _, candidate := range data.Cards {
		if candidate.ID == cardID && candidate.DeletionState == "" {
			card, found = candidate, true
			break
		}
	}
	if !found {
		return contracts.CardEditorData{}, errors.New("card unavailable")
	}
	revision, err := cardRevision(card)
	if err != nil {
		return contracts.CardEditorData{}, err
	}
	result := contracts.CardEditorData{
		DashboardID:      dashboardID,
		OwnerDashboardID: card.DashboardID,
		CardID:           card.ID,
		Revision:         revision,
		CanEdit:          card.DashboardID == dashboardID,
		Values:           cardValues(card),
	}
	if !result.CanEdit {
		result.Reason = "Only the owning dashboard can edit this card"
	}
	return result, nil
}

