Service.ReadRegistryChangeToken.src:
// ReadRegistryChangeToken maps the application's existing metadata fingerprint
// to an opaque frontend-comparable value.
func (s *Service) ReadRegistryChangeToken() (contracts.RegistryChangeToken, error) {
	fingerprinter, ok := s.repo.(registryFingerprinter)
	if !ok {
		return "", errors.New("registry fingerprint unavailable")
	}
	stamps, err := fingerprinter.Fingerprint()
	if err != nil {
		return "", err
	}
	keys := make([]string, 0, len(stamps))
	for key := range stamps {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	var serialized strings.Builder
	for _, key := range keys {
		stamp := stamps[key]
		fmt.Fprintf(&serialized, "%s\x00%d\x00%d\n", key, stamp.ModTime.UnixNano(), stamp.Size)
	}
	digest := sha256.Sum256([]byte(serialized.String()))
	return contracts.RegistryChangeToken(hex.EncodeToString(digest[:])), nil
}

Service.ReadSessionReports.src:
// ReadSessionReports returns retained reports authored by a dashboard session.
func (s *Service) ReadSessionReports(ctx context.Context, req contracts.SessionReportsRequest) (contracts.SessionReportsResult, error) {
	if err := ctx.Err(); err != nil {
		return contracts.SessionReportsResult{}, err
	}
	if err := s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return contracts.SessionReportsResult{}, err
	}
	store := s.sessions.Messages()
	if store == nil {
		return contracts.SessionReportsResult{}, errMessagingUnavailable
	}
	page, err := store.RecentAuthoredReports(ctx, req.DashboardID, req.SessionID, req.Limit)
	if err != nil {
		return contracts.SessionReportsResult{}, err
	}
	if err = s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return contracts.SessionReportsResult{}, err
	}
	limit := min(req.Limit, session.MaxAuthoredReports)
	out := contracts.SessionReportsResult{
		Limit:   limit,
		Maximum: session.MaxAuthoredReports,
		Omitted: page.Omitted,
		Reports: make([]contracts.SessionReport, 0, len(page.Items)),
	}
	for _, item := range page.Items {
		out.Reports = append(
			out.Reports,
			contracts.SessionReport{
				ID:                 item.ID,
				MessageID:          item.MessageID,
				AuthorSessionID:    item.SenderSessionID,
				AuthorActivationID: item.SenderActivationID,
				Kind:               item.Kind,
				Text:               item.Text,
				CreatedAt:          item.CreatedAt,
				Sequence:           item.Sequence,
			},
		)
	}
	return out, nil
}

Service.ReadSessionWorkspace.src:
// ReadSessionWorkspace inspects the saved actual workspace, revalidating scope
// after external I/O. Git paths are relative to the repository root.
func (s *Service) ReadSessionWorkspace(ctx context.Context, req contracts.ScopedSessionRequest) (contracts.SessionWorkspaceResult, error) {
	if err := s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return contracts.SessionWorkspaceResult{}, err
	}
	snap, ok := s.sessions.GetSession(req.SessionID)
	if !ok || snap.DashboardID != req.DashboardID || snap.WorkingDir == "" || !filepath.IsAbs(snap.WorkingDir) {
		return contracts.SessionWorkspaceResult{}, errors.New("saved session workspace unavailable")
	}
	result, inspectErr := inspectWorkspace(ctx, snap.WorkingDir)
	if err := s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return contracts.SessionWorkspaceResult{}, err
	}
	current, ok := s.sessions.GetSession(req.SessionID)
	if !ok || current.DashboardID != req.DashboardID || current.WorkingDir != snap.WorkingDir {
		return contracts.SessionWorkspaceResult{}, errors.New("session workspace changed during inspection")
	}
	return result, inspectErr
}

