Service.RelaunchSession.src:
func (s *Service) RelaunchSession(
	ctx context.Context,
	token, requestID, sessionID string,
	conversation *ConversationRequest,
) (OperationResult, error) {
	caller, err := s.ResolveCaller(token)
	if err != nil {
		return OperationResult{}, err
	}
	if _, errAt265 := conversationChoice(conversation); errAt265 != nil {
		return OperationResult{}, reject("invalid_request", "conversation choice is invalid")
	}
	args := conversationArguments{Conversation: conversation}
	apply := func(operationCtx context.Context) (lifecycleEffects, error) {
		choice, parseErr := conversationChoice(conversation)
		if parseErr != nil {
			return lifecycleEffects{}, parseErr
		}
		activationErr := s.RelaunchInDashboard(operationCtx, caller.DashboardID, sessionID, choice)
		if activationErr != nil && !errors.Is(activationErr, session.ErrPersistFailed) {
			return lifecycleEffects{}, activationErr
		}
		inspection, inspectErr := s.inspectSession(sessionID)
		if inspectErr != nil {
			return lifecycleEffects{}, errors.Join(activationErr, inspectErr)
		}
		out := lifecycleEffects{SessionID: sessionID, Inspection: &inspection}
		if errors.Is(activationErr, session.ErrPersistFailed) {
			return out, fmt.Errorf("activation started but session record could not be saved: %w", activationErr)
		}
		return out, nil
	}
	operation, err := s.submitSession(ctx, token, requestID, "relaunch_session", sessionID, args, apply)
	return operationResult(operation), err
}

Service.RemoveDashboardSession.src:
func (s *Service) RemoveDashboardSession(ctx context.Context, request contracts.ScopedSessionRequest) contracts.RemoveSessionResult {
	if err := ctx.Err(); err != nil {
		return contracts.RemoveSessionResult{Diagnostic: err.Error(), DiagnosticCode: diagnosticCode(err)}
	}
	result, err := s.sessions.RemoveDetailedChecked(
		request.SessionID,
		s.sessionScopeCheckContext(ctx, request.DashboardID, request.SessionID),
	)
	output := contracts.RemoveSessionResult{
		InMemoryRemoved:  result.InMemoryRemoved,
		RecordDeleted:    result.SessionRecordDeleted,
		WorkspaceRemoved: result.TemporaryWorkspaceRemoved,
	}
	if err != nil {
		output.Diagnostic = err.Error()
		output.DiagnosticCode = diagnosticCode(err)
		if result.InMemoryRemoved || result.SessionRecordDeleted || result.TemporaryWorkspaceRemoved {
			output.DiagnosticCode = contracts.DiagnosticPartial
		}
	}
	return output
}

Service.RenameDashboardSession.src:
func (s *Service) RenameDashboardSession(ctx context.Context, request contracts.RenameSessionRequest) contracts.RenameSessionResult {
	if err := ctx.Err(); err != nil {
		return contracts.RenameSessionResult{Diagnostic: err.Error(), DiagnosticCode: diagnosticCode(err)}
	}
	var result session.RenameResult
	var err error
	if request.ExpectedProcessID != "" {
		result, err = s.sessions.SetNameExpectedProcessChecked(
			request.SessionID,
			request.Name,
			request.ExpectedProcessID,
			s.sessionScopeCheckContext(ctx, request.DashboardID, request.SessionID),
		)
	} else {
		result, err = s.sessions.SetNameDetailedChecked(
			request.SessionID,
			request.Name,
			s.sessionScopeCheckContext(ctx, request.DashboardID, request.SessionID),
		)
	}
	output := contracts.RenameSessionResult{Applied: result.Applied, Persisted: result.Persisted}
	if err != nil {
		output.Diagnostic = err.Error()
		output.DiagnosticCode = diagnosticCode(err)
		if result.Applied {
			output.DiagnosticCode = contracts.DiagnosticPersistence
		}
	}
	return output
}

