	parsed, err := uuid.Parse(requestID)
	if err != nil {
		return session.MessageReply{}, reject("invalid_request", "request_id must be a UUID")
	}
	if messageID == "" {
		return session.MessageReply{}, reject("invalid_request", "message_id is required")
