	return reply, messagingRejection(err)
}

Service.ResolveCaller.src:
// ResolveCaller derives lifecycle authority solely from the activation credential.
func (s *Service) ResolveCaller(token string) (CallerContext, error) {
	identity, err := s.sessions.ResolveDashboardCaller(token)
	if err != nil {
		return CallerContext{}, reject("forbidden", "caller activation is not authorized for dashboard control")
	}
	dashboardID := s.scope.DashboardForSession(identity.SessionID)
	if dashboardID == "" {
		return CallerContext{}, reject("forbidden", "caller dashboard is unavailable")
	}
	return CallerContext{
		SessionID: identity.SessionID, ActivationID: identity.ActivationID, DashboardID: dashboardID,
		DashboardControl: true,
	}, nil
}

Service.RetryCardDeletion.src:
// RetryCardDeletion resumes an existing durable intent; it never creates one.
func (s *Service) RetryCardDeletion(ctx context.Context, ownerID, cardID string) (CardDeletionResult, error) {
	writer, ok := s.repo.(tombstoneWriter)
	if !ok {
		return CardDeletionResult{}, errors.New("card deletion storage unavailable")
	}
	release, err := s.sessions.ReserveCardDeletion(cardID)
	if err != nil {
		return CardDeletionResult{}, err
	}
	defer release()
	workerCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	go func() {
		select {
		case <-s.sessions.ShutdownStarted():
			cancel()
		case <-workerCtx.Done():
		}
	}()
	result := CardDeletionResult{State: config.CardDeleting}
	if errAt155 := s.validateDeletionOwner(ownerID, cardID); errAt155 != nil {
		return CardDeletionResult{}, errAt155
	}
	s.sessions.CancelPendingCardReferences(cardID)
	if errAt159 := s.sessions.WaitCardReferences(workerCtx, cardID); errAt159 != nil {
		return result, fmt.Errorf("card deletion is pending: %w", errAt159)
	}
	if errAt162 := s.cleanupCardPending(workerCtx, writer, ownerID, cardID); errAt162 != nil {
		return result, errAt162
	}
	err = s.sessions.WithCardReferencesAndSnapshot(cardID, func(impact session.CardReferenceImpact, sessions []session.Snapshot) error {
		if len(impact.PendingByDashboard) != 0 {
			return errors.New("card activations are still pending")
		}
		if errAt169 := s.validateDeletionInventory(ownerID, cardID, sessions); errAt169 != nil {
			return errAt169
		}
		return writer.FinishCardDeletion(cardID)
	})
	if err != nil {
		return result, err
	}
	result.State = config.CardDeleted
	return result, nil
}

Service.RetryDashboardDeletion.src:
// RetryDashboardDeletion resumes a persisted cascade without replaying launches.
func (s *Service) RetryDashboardDeletion(ctx context.Context, dashboardID string) (DashboardDeletionResult, error) {
	writer, ok := s.repo.(dashboardDeletionWriter)
	if !ok {
		return DashboardDeletionResult{}, errors.New("dashboard deletion storage unavailable")
	}
	release, err := s.sessions.ReserveDashboardDeletion(dashboardID)
	if err != nil {
		return DashboardDeletionResult{}, err
	}
	defer release()
	workerCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	go func() {
		select {
		case <-s.sessions.ShutdownStarted():
			cancel()
		case <-workerCtx.Done():
		}
	}()
	manifest, err := s.dashboardDeletion(dashboardID)
	if err != nil {
		if !errors.Is(err, errDashboardDeletionNotFound) {
			return DashboardDeletionResult{}, err
		}
		deleted, checkErr := s.dashboardAlreadyDeleted(dashboardID)
		if checkErr != nil {
			return DashboardDeletionResult{}, checkErr
		}
		if deleted {
			return DashboardDeletionResult{State: config.CardDeleted}, nil
		}
		return DashboardDeletionResult{}, err
	}
	result := DashboardDeletionResult{State: config.CardDeleting, Manifest: manifest}
	err = s.runDashboardDeletion(workerCtx, writer, &result.Manifest)
	if err != nil {
		return result, err
	}
	result.State = config.CardDeleted
	return result, nil
}

