Service.StopDashboardSession.src:
func (s *Service) StopDashboardSession(ctx context.Context, request contracts.ScopedSessionRequest) contracts.StopSessionResult {
	if err := ctx.Err(); err != nil {
		return contracts.StopSessionResult{Diagnostic: err.Error(), DiagnosticCode: diagnosticCode(err)}
	}
	result, err := s.sessions.KillDetailedChecked(
		request.SessionID,
		s.sessionScopeCheckContext(ctx, request.DashboardID, request.SessionID),
	)
	output := contracts.StopSessionResult{ProcessTerminated: result.ProcessTerminated, RecordPersisted: result.SessionRecordPersisted}
	if err != nil {
		output.Diagnostic = err.Error()
		output.DiagnosticCode = diagnosticCode(err)
		if result.ProcessTerminated {
			output.DiagnosticCode = contracts.DiagnosticPartial
		}
	}
	return output
}

Service.StopSession.src:
func (s *Service) StopSession(ctx context.Context, token, requestID, sessionID string) (OperationResult, error) {
	apply := func(context.Context) (lifecycleEffects, error) {
		result, err := s.sessions.KillDetailed(sessionID)
		effects := lifecycleEffects{
			SessionID: sessionID, ProcessTerminated: result.ProcessTerminated,
			SessionRecordPersisted: result.SessionRecordPersisted,
		}
		if err != nil && result.ProcessTerminated {
			return effects, operationWarningError{"process stopped, but teardown or metadata persistence reported a warning"}
		}
		return effects, err
	}
	operation, err := s.submitSession(ctx, token, requestID, "stop_session", sessionID, struct{}{}, apply)
	return operationResult(operation), err
}

Service.SubscribeSessionReports.src:
// SubscribeSessionReports captures the store signal before returning, so callers
// can safely perform their initial read after setup completes.
func (s *Service) SubscribeSessionReports(ctx context.Context, req contracts.ScopedSessionRequest) (contracts.ReportSubscription, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return nil, err
	}
	store := s.sessions.Messages()
	if store == nil {
		return nil, errMessagingUnavailable
	}
	signal := store.ReportsChanged()
	scope := store.ReportScopeChanged()
	shutdown := s.sessions.ShutdownStarted()
	select {
	case <-shutdown:
		return nil, errors.New("session manager shut down")
	default:
	}
	if err := s.CheckSessionInDashboard(req.DashboardID, req.SessionID); err != nil {
		return nil, err
	}
	subctx, cancel := context.WithCancel(ctx)
	sub := &reportSubscription{changes: make(chan struct{}, 1), cancel: cancel}
	go watchReportChanges(subctx, cancel, shutdown, signal, scope, store.ReportsChanged, store.ReportScopeChanged, func() error {
		return s.CheckSessionInDashboard(req.DashboardID, req.SessionID)
	}, sub)
	return sub, nil
}

