func (s *Service) launchDashboardWithIDEvidence(
	ctx context.Context,
	dashboardID, cardID, sessionID string,
	name *string,
	evidence *session.ActivationResult,
) (string, error) {
	launchCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	release, err := s.sessions.ReserveCardReferenceForDashboardWithCancel(
		cardID,
		dashboardID,
		sessionID,
		cancel,
		func(sessions []session.Snapshot) (bool, error) {
			_, available, checkErr := s.availableDashboardCard(dashboardID, cardID, sessions)
			return available, checkErr
		},
	)
	if err != nil {
		return "", err
	}
	defer release()
	bundle, err := s.resolveCard(cardID)
	if err != nil {
		return "", err
	}
	publicationCheck := func(sessions []session.Snapshot) error {
		current, available, checkErr := s.availableDashboardCard(dashboardID, cardID, sessions)
		if checkErr != nil {
			return checkErr
		}
		if !available || !reflect.DeepEqual(current, bundle.Card) {
			return errors.New("card or dashboard changed before activation publication")
		}
		return nil
	}
	result := s.sessions.LaunchInDashboardWithIDResult(launchCtx, sessionID, dashboardID, bundle.Card,
		bundle.Skills, bundle.Personas, bundle.MCPs, publicationCheck, name)
	if evidence != nil {
		*evidence = result
	}
	return sessionID, result.Err
}

Service.listCardsForCaller.src:
func (s *Service) listCardsForCaller(caller CallerContext) ([]CardDiscovery, error) {
	cards, err := s.repo.ListIDCards()
	if err != nil {
		return nil, fmt.Errorf("list cards: %w", err)
	}
	workspaces, ok := s.repo.(workspaceLister)
	if !ok {
		return nil, errors.New("workspace discovery is unavailable")
	}
	items, err := workspaces.ListWorkspaces()
	if err != nil {
		return nil, fmt.Errorf("list workspaces: %w", err)
	}
	byID := make(map[string]string, len(items))
	for _, item := range items {
		byID[item.ID] = item.Path
	}
	out := make([]CardDiscovery, 0, len(cards))
	for _, card := range cards {
		if caller.SessionID != "" && !s.scope.AllowsCard(caller.SessionID, card.ID) {
			continue
		}
		entry := CardDiscovery{
			ID:               card.ID,
			OwnerDashboardID: card.DashboardID,
			Shared:           card.Shared,
			Name:             card.Name,
			Driver:           card.Driver,
			Model:            card.Model,
			WorkspaceID:      card.WorkspaceID,
			WorkspacePath:    byID[card.WorkspaceID],
			SubWorkspaceIDs:  append([]string(nil), card.SubWorkspaceIDs...),
			UseTmpWorkspace:  card.UseTmpWorkspace,
		}
		for _, id := range card.SubWorkspaceIDs {
			entry.SubWorkspacePaths = append(entry.SubWorkspacePaths, byID[id])
		}
		out = append(out, entry)
	}
	return out, nil
}

