Service.relaunchInDashboardEvidence.src:
func (s *Service) relaunchInDashboardEvidence(
	ctx context.Context,
	dashboardID, sessionID, expectedCardID string,
	choice session.ConversationChoice,
	evidence *session.ActivationResult,
) error {
	snapshot, exists := s.sessions.GetSession(sessionID)
	if !exists || snapshot.DashboardID != dashboardID {
		return errors.New("session is outside dashboard scope")
	}
	cardID := snapshot.CardID
	if expectedCardID != "" && expectedCardID != cardID {
		return errors.New("session card changed before activation")
	}
	activationCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	release, err := s.sessions.ReserveCardReferenceForDashboardWithCancel(
		cardID,
		dashboardID,
		sessionID,
		cancel,
		func(sessions []session.Snapshot) (bool, error) {
			_, available, checkErr := s.availableDashboardCard(dashboardID, cardID, sessions)
			return available && sessionUsesCard(sessions, dashboardID, sessionID, cardID), checkErr
		},
	)
	if err != nil {
		return fmt.Errorf("card unavailable; choose another available card: %w", err)
	}
	defer release()
	card, err := s.loadCard(cardID)
	if err != nil {
		return err
	}
	publicationCheck := func(sessions []session.Snapshot) error {
		current, available, checkErr := s.availableDashboardCard(dashboardID, cardID, sessions)
		if checkErr != nil {
			return checkErr
		}
		if !available || !sessionUsesCard(sessions, dashboardID, sessionID, cardID) || !reflect.DeepEqual(current, card) {
			return errors.New("session, card or dashboard changed before activation publication")
		}
		return nil
	}
	result := s.sessions.RelaunchWithChoiceCheckedResult(activationCtx, sessionID, card, choice, publicationCheck)
	if evidence != nil {
		*evidence = result
	}
	return result.Err
}

Service.removeDashboardSession.src:
//nolint:gocognit // Each cleanup effect is checked and checkpointed.
func (s *Service) removeDashboardSession(
	ctx context.Context,
	dashboardID string,
	item *config.DashboardDeletionSession,
	writer dashboardDeletionWriter,
	manifest *config.DashboardDeletion,
) error {
	snapshot, exists := s.sessions.GetSession(item.ID)
	//nolint:nestif // Check and persist each cleanup effect before proceeding.
	if exists {
		working := snapshot.WorkingDir
		if snapshot.UseTmpWorkspace {
			var err error
			working, err = filepath.Abs(working)
			if err != nil {
				return err
			}
		}
		if snapshot.DashboardID != dashboardID || snapshot.UseTmpWorkspace != item.UseTmpWorkspace || working != item.WorkingDir {
			return errors.New("session identity or workspace changed after confirmation")
		}
		if snapshot.Status != session.StatusTerminated {
			stopped, err := s.sessions.KillDetailed(item.ID)
			item.Stopped = stopped.ProcessTerminated
			if err != nil {
				item.Error = err.Error()
				return errors.Join(err, writer.SaveDashboardDeletion(*manifest))
			}
			if !stopped.ProcessTerminated {
				return errors.New("session process remains active")
			}
		} else {
			item.Stopped = true
		}
		item.Error = ""
		if err := writer.SaveDashboardDeletion(*manifest); err != nil {
			return err
		}
		removed, err := s.sessions.RemoveDetailed(item.ID)
		item.RecordDeleted = removed.SessionRecordDeleted
		item.TemporaryRemoved = !item.UseTmpWorkspace || removed.TemporaryWorkspaceRemoved
		if err != nil {
			item.Error = err.Error()
			return errors.Join(err, writer.SaveDashboardDeletion(*manifest))
		}
	} else {
		item.Stopped = true
		removed, err := s.sessions.RemoveResidual(ctx, item.ID, item.WorkingDir, item.TemporaryRoot, item.UseTmpWorkspace)
		item.RecordDeleted = removed.SessionRecordDeleted
		item.TemporaryRemoved = !item.UseTmpWorkspace || removed.TemporaryWorkspaceRemoved
		if err != nil {
			item.Error = err.Error()
			return errors.Join(err, writer.SaveDashboardDeletion(*manifest))
		}
	}
	if !item.RecordDeleted || !item.TemporaryRemoved {
		return errors.New("session cleanup effects are incomplete")
	}
	item.Removed, item.Error = true, ""
	return writer.SaveDashboardDeletion(*manifest)
}

