	}
	_, ownerExists := inventory.dashboards[ownerID]
	tombstone, exists := inventory.tombstones[cardID]
	if !ownerExists || !exists || tombstone.DashboardID != ownerID {
		return errors.New("card deletion is not owned by this dashboard")
	}
	return nil
}

