attachment.Next.src:
func (a *attachment) Next(ctx context.Context) ([]byte, error) {
	select {
	case <-a.closed:
		return nil, io.EOF
	default:
	}
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-a.closed:
		return nil, io.EOF
	case chunk, ok := <-a.handle.Output:
		if !ok {
			return nil, io.EOF
		}
		return chunk, nil
	}
}

