func (b *limitedBuffer) Write(p []byte) (int, error) {
	if len(p) > b.limit-b.buffer.Len() {
		b.exceeded = true
		if b.kill != nil {
			b.kill()
		}
		return 0, errors.New("output limit exceeded")
	}
	return b.buffer.Write(p)
}

