	return []BuiltinPuppetDef{
		{Name: "default", Lines: []string{"  ___  ", " (o o) ", "/|_=_|\\", " /   \\ "}},
		{Name: "kankuro", Lines: []string{" /\\_/\\ ", "( -.- )  ", " >(T)<   ", "/|||||\\ ", " || ||   "}},
		{Name: "cat", Lines: []string{"  /\\___/\\ ", " (  o o  )", "  |  ^  | ", "  | \\_/ | ", "   -----  "}},
		{Name: "strawhat", Lines: []string{"  _...._  ", " /  __  \\", "(  (oo)  )", " \\__--__/ ", "   /||\\  "}},
		{Name: "darth", Lines: []string{"  .---.  ", " /_|_|_\\", " / \\_/ \\", "| >[#]< |", " \\_____/ "}},
