NewFace.src:
func NewFace(opts ...ascii.Option) ascii.Shape {
	config := ascii.NewConfig()
	for _, opt := range opts {
		opt(config)
	}

	shape := &Face{
		style: config.GetString("style", "neutral"),
	}
	shape.BaseShape.Width = defaultFaceWidth
	shape.BaseShape.Height = 1
	return shape
}

NewPuppet.src:
func NewPuppet(opts ...ascii.Option) ascii.Shape {
	config := ascii.NewConfig()
	for _, opt := range opts {
		opt(config)
	}

	style := config.GetString("style", "default")
	for _, def := range BuiltinPuppetLines() {
		if def.Name == style {
			return NewTextPuppet(def.Lines)
		}
	}
	return NewTextPuppet(BuiltinPuppetLines()[0].Lines)
}

NewTextPuppet.src:
// NewTextPuppet creates a TextPuppet sized to its first line and line count.
func NewTextPuppet(lines []string) ascii.Shape {
	p := &TextPuppet{lines: lines}

	if len(lines) > 0 {
		p.BaseShape.Width = len(lines[0])
	}
	p.BaseShape.Height = len(lines)

	return p
}

Face.Render.src:
func (f *Face) Render(canvas *ascii.Canvas, x, y int) {
	switch f.style {
	case "happy":
		canvas.DrawText(x, y, "(^-^)")
	case "focused":
		canvas.DrawText(x, y, "[-.-]")
	case "thinking":
		canvas.DrawText(x, y, "(?_?)")
	default:
		canvas.DrawText(x, y, "(o.o)")
	}
}

TextPuppet.Render.src:
func (p *TextPuppet) Render(canvas *ascii.Canvas, x, y int) {
	for i, line := range p.lines {
		canvas.DrawText(x, y+i, line)
	}
}

