TruncateHead.src:
// TruncateHead trims s to at most w display columns, keeping the start and
// ending in "..." when something was cut. Measured by display width, never
// by byte, so wide runes (CJK, emoji) are not split. When w is too small for
// the ellipsis the text is cut without one.
func TruncateHead(s string, w int) string {
	if w <= 0 {
		return ""
	}
	if ansi.StringWidth(s) <= w {
		return s
	}
	tail := ellipsis
	if w <= len(ellipsis) {
		tail = ""
	}
	out := ansi.Truncate(s, w, tail)
	// A wide rune at the cut can make the grapheme-aware measure disagree with
	// the cell count Truncate worked to; never hand back something too wide.
	for ansi.StringWidth(out) > w && w > 0 {
		w--
		out = ansi.Truncate(s, w, tail)
	}
	return out
}

TruncateTail.src:
// TruncateTail trims s to at most w display columns, keeping the end and
// starting with "..." when something was cut. It is the right choice for
// paths (the last segments matter most) and for text being typed. See
// TruncateHead for the width rules.
func TruncateTail(s string, w int) string {
	if w <= 0 {
		return ""
	}
	total := ansi.StringWidth(s)
	if total <= w {
		return s
	}
	prefix := ellipsis
	if w <= len(ellipsis) {
		prefix = ""
	}
	keep := w - len(prefix)
	out := ansi.TruncateLeft(s, total-keep, prefix)
	for ansi.StringWidth(out) > w && keep > 0 {
		keep--
		out = ansi.TruncateLeft(s, total-keep, prefix)
	}
	return out
}

centerMode.src:
// centerMode formats the stable mode bits supplied by the workspace contract.
func centerMode(mode uint32) string {
	const (
		directory            = uint32(1 << 31)
		symlink              = uint32(1 << 27)
		device               = uint32(1 << 26)
		namedPipe            = uint32(1 << 25)
		socket               = uint32(1 << 24)
		setUID               = uint32(1 << 23)
		setGID               = uint32(1 << 22)
		charDevice           = uint32(1 << 21)
		sticky               = uint32(1 << 20)
		highestPermissionBit = 8
	)
	kind := byte('-')
	switch {
	case mode&directory != 0:
		kind = 'd'
	case mode&symlink != 0:
		kind = 'l'
	case mode&namedPipe != 0:
		kind = 'p'
	case mode&socket != 0:
		kind = 's'
	case mode&charDevice != 0:
		kind = 'c'
	case mode&device != 0:
		kind = 'b'
	}
	bits := []byte("---------")
	for i := range 9 {
		if mode&(1<<(highestPermissionBit-i)) != 0 {
			bits[i] = "rwx"[i%3]
		}
	}
	for _, item := range []struct {
		mask         uint32
		index        int
		lower, upper byte
	}{{setUID, 2, 's', 'S'}, {setGID, 5, 's', 'S'}, {sticky, 8, 't', 'T'}} {
		if mode&item.mask != 0 {
			if bits[item.index] == 'x' {
				bits[item.index] = item.lower
			} else {
				bits[item.index] = item.upper
			}
		}
	}
	return string(kind) + string(bits)
}

