func centerReportHeader(report contracts.SessionReport, width int) string {
	at := report.CreatedAt.Local()
	kind := " [" + DisplayText(report.Kind) + "]"
	header := at.Format("2006-01-02 15:04") + kind
	if ansi.StringWidth(header) > width {
