centerSafePath.src:
// centerSafePath keeps each filesystem name within its own rendered row.
func centerSafePath(text string) string {
	text = ansi.Strip(text)
	return strings.Map(func(r rune) rune {
		if unicode.IsControl(r) || unicode.IsSpace(r) {
			return ' '
		}
		return r
	}, text)
}

centerSafeText.src:
func centerSafeText(text string) string {
	text = ansi.Strip(text)
	return strings.Map(func(r rune) rune {
		if r == '\n' {
			return r
		}
		if r == '\t' || r == '\r' {
			return ' '
		}
		if unicode.IsControl(r) {
			return -1
		}
		return r
	}, text)
}

clampToSize.src:
func clampToSize(s string, maxWidth, maxHeight int) string {
	if maxWidth <= 0 || maxHeight <= 0 {
		return ""
	}
	lines := strings.Split(s, "\n")
	if len(lines) > maxHeight {
		lines = lines[:maxHeight]
	}
	for i, line := range lines {
		if ansi.StringWidth(line) <= maxWidth {
			continue
		}
		clamped := ansi.Truncate(line, maxWidth, "")
		if ansi.StringWidth(clamped) > maxWidth {
			// Defensive fallback: strip ANSI and hard-truncate by visual width.
			clamped = TruncateTail(ansi.Strip(line), maxWidth)
		}
		lines[i] = clamped
	}
	return strings.Join(lines, "\n")
}

maxLineWidth.src:
func maxLineWidth(lines []string) int {
	w := 0
	for _, l := range lines {
		if len(l) > w {
			w = len(l)
		}
	}
	return w
}

overflowPill.src:
// overflowPill summarises capabilities that did not fit on the card row.
func overflowPill(hidden int) string {
	return pillStyle(styles.Gray, styles.White).Render(fmt.Sprintf("+%d", hidden))
}

renderPills.src:
// renderPills renders the capability pills for one card row, fitted to
// maxWidth by measured display width.
//
// The row must never be wrapped by lipgloss: every pill ends in two columns
// of whitespace (padding + margin), and a word-wrap leaves whitespace hanging
// past the box edge instead of moving it to the next line. When the edge
// lands inside those two columns the row comes out 1-2 columns too wide,
// which is what shattered the card for particular skill sets at particular
// terminal widths. So pills are added only while they fit, and whatever does
// not fit - including anything past MaxPillsShown - is summarised in a
// trailing "+N" pill.
func renderPills(skillNames, personaNames []string, maxWidth int) []string {
	if len(skillNames) == 0 && len(personaNames) == 0 {
		return []string{lipgloss.NewStyle().Foreground(styles.Gray).Render("(no capabilities)")}
	}

	type pillSpec struct {
		name string
		bg   color.Color
	}
	specs := make([]pillSpec, 0, len(skillNames)+len(personaNames))
	for _, n := range skillNames {
		specs = append(specs, pillSpec{name: n, bg: styles.HighlightColor})
	}
	for _, n := range personaNames {
		specs = append(specs, pillSpec{name: n, bg: styles.SecondaryColor})
	}

	var pills []string
	var widths []int
	used := 0
	for _, sp := range specs {
		if len(pills) >= MaxPillsShown {
			break
		}
		p := pillStyle(sp.bg, styles.White).Render(truncatePill(DisplayText(sp.name)))
		w := lipgloss.Width(p)
		if used+w > maxWidth {
			break
		}
		pills = append(pills, p)
		widths = append(widths, w)
		used += w
	}

	// Make room for the "+N" summary, dropping pills from the end if needed.
	// Dropping one raises N, which can widen the summary by a digit, so this
	// re-measures on every iteration rather than reserving space up front.
	for hidden := len(specs) - len(pills); hidden > 0; hidden = len(specs) - len(pills) {
		more := overflowPill(hidden)
		if used+lipgloss.Width(more) <= maxWidth {
			pills = append(pills, more)
			break
		}
		if len(pills) == 0 {
			break // not even the summary fits; the info box MaxWidth clips
		}
		used -= widths[len(widths)-1]
		pills, widths = pills[:len(pills)-1], widths[:len(widths)-1]
	}
	return pills
}

sessionHeaderField.src:
func sessionHeaderField(label, value string, width int, keepTail bool) string {
	valueWidth := max(0, width-ansi.StringWidth(label))
	value = DisplayText(value)
	if keepTail {
		value = TruncateTail(value, valueWidth)
	} else {
		value = TruncateHead(value, valueWidth)
	}
	return centerSessionField.Render(TruncateHead(label+value, width))
}

sessionHeaderFields.src:
func sessionHeaderFields(row models.SessionRow, width int) []string {
	name := row.Name
	if name == "" {
		name = row.ID
	}
	started := "N/A"
	if !row.StartedAt.IsZero() {
		started = row.StartedAt.Format("15:04:05")
	}
	lines := []string{
		centerSessionTitle.Render(TruncateHead(DisplayText(name), width)),
		ClampToSize(sessionStatusBadge(row.Status), width, 1),
		sessionHeaderField("ID: ", row.ID, width, false),
		sessionHeaderField("WS: ", row.WorkingDir, width, true),
		sessionHeaderField("Started: ", started, width, false),
	}
	if row.CardName != "" {
		lines = append(lines, sessionHeaderField("Card: ", row.CardName, width, false))
	}
	return lines
}

sessionStatusBadge.src:
func sessionStatusBadge(status string) string {
	switch status {
	case "running":
		return centerStatusStyle.Background(styles.HighlightColor).Render("Running")
	case waitingStatus:
		return centerStatusStyle.Background(styles.HotPink).Render("Waiting")
	case "terminated":
		return centerStatusStyle.Background(styles.Gray).Render("Terminated")
	default:
		return centerStatusStyle.Background(styles.Gray).Render("Unknown")
	}
}

