SessionCenter.bodyRows.src:
//nolint:gocognit,mnd // Rendering preserves bounded, warning-aware panel layout.
func (p *SessionCenter) bodyRows(height int) []string {
	var lines []string
	add := func(s string) {
		if len(lines) >= height {
			return
		}
		wrapped := ansi.Hardwrap(centerSafeText(s), p.Width, true)
		lines = append(lines, strings.Split(wrapped, "\n")...)
	}
	if p.data.Stale {
		add("[stale]")
	}
	for _, warning := range p.data.Warnings {
		add("Warning: " + centerSafePath(warning))
	}
	// Keep at least one row for the newest report when warnings are long.
	if len(p.data.Reports) > 0 && len(lines) >= height {
		lines = lines[:height-1]
	} else if p.data.Workspace != nil && len(lines) > max(0, height-2) {
		lines = lines[:max(0, height-2)]
	}
	switch {
	case len(p.data.Reports) > 0:
		for index, report := range p.data.Reports {
			remaining := height - len(lines)
			if remaining < centerMinBodyRows {
				if index == 0 && remaining == 1 {
					stamp := report.CreatedAt.Local().Format("15:04")
					add(TruncateHead(stamp+" "+DisplayText(report.Text), p.Width))
				}
				break
			}
			add(centerReportHeader(report, p.Width))
			add(report.Text)
		}
		if p.data.Omitted > 0 && len(lines) < height {
			add(fmt.Sprintf("… %d older reports omitted", p.data.Omitted))
		}
	case p.data.Workspace != nil:
		p.renderWorkspace(p.data.Workspace, add)
	case p.data.Loading:
		add("Loading…")
	default:
		add("No workspace information")
	}
	return lines
}

SessionCenter.headerRows.src:
func (p *SessionCenter) headerRows() []string {
	maxHeight := p.Height - centerMinBodyRows
	if p.session.ID == "" || maxHeight <= 0 {
		return nil
	}

	art := RenderPuppetArtwork(p.session.PuppetName, p.session.PuppetBuiltin, p.session.PuppetLines)
	artRows := strings.Split(art, "\n")
	for i, line := range artRows {
		artRows[i] = DisplayText(line)
	}
	art = strings.Join(artRows, "\n")
	artWidth := lipgloss.Width(art)
	showArt := artWidth > 0 && p.Width >= artWidth+centerPuppetGap+centerMinTextWidth

	fields := sessionHeaderFields(p.session, p.Width)
	// Keep the original blank row and divider when the full header fits.
	if len(fields)+2 > maxHeight || (showArt && lipgloss.Height(art)+1 > maxHeight) {
		return fields[:min(len(fields), maxHeight)]
	}
	if showArt {
		textWidth := p.Width - artWidth - centerPuppetGap
		artFields := append(sessionHeaderFields(p.session, textWidth), "")
		text := lipgloss.NewStyle().Width(textWidth).Render(strings.Join(artFields, "\n"))
		top := lipgloss.JoinHorizontal(lipgloss.Top, text, strings.Repeat(" ", centerPuppetGap), art)
		fields = strings.Split(top, "\n")
	} else {
		fields = append(fields, "")
	}
	return append(fields, centerSessionField.Render(strings.Repeat(lipgloss.NormalBorder().Top, p.Width)))
}

SessionCenter.renderWorkspace.src:
//nolint:gocognit,nestif // Workspace rows preserve detailed metadata at small widths.
func (p *SessionCenter) renderWorkspace(w *contracts.SessionWorkspaceResult, add func(string)) {
	if w.Kind == contracts.WorkspaceGit {
		add(TruncateHead("Git: "+centerSafePath(w.RepositoryRoot), p.Width))
		if w.Truncated {
			add("… Git status truncated")
		}
		if len(w.GitEntries) == 0 {
			add("Working tree clean")
		}
		for _, e := range w.GitEntries {
			s := fmt.Sprintf("%c%c %s", e.IndexStatus, e.WorktreeStatus, centerSafePath(e.Path))
			if e.OriginalPath != "" {
				s += " ← " + centerSafePath(e.OriginalPath)
			}
			add(s)
		}
	} else {
		add(TruncateHead("Directory: "+centerSafePath(w.WorkingDir), p.Width))
		if w.Truncated {
			add("… directory sample truncated")
		}
		for _, e := range w.Entries {
			owner, group, links := "-", "-", "-"
			if e.Owner != nil {
				owner = strconv.FormatUint(uint64(*e.Owner), 10)
			}
			if e.Group != nil {
				group = strconv.FormatUint(uint64(*e.Group), 10)
			}
			if e.LinkCount != nil {
				links = strconv.FormatUint(*e.LinkCount, 10)
			}
			s := fmt.Sprintf(
				"%s  %s %s %s %s %d %s",
				centerSafePath(e.Name),
				centerMode(e.Mode),
				links,
				owner,
				group,
				e.Size,
				e.ModifiedAt.Local().Format("2006-01-02 15:04"),
			)
			if e.SymlinkTarget != nil {
				s += " -> " + centerSafePath(*e.SymlinkTarget)
			}
			add(s)
		}
	}
}

