SourceList.renderForm.src:
// renderForm renders the input form.
func (s *SourceList) renderForm() string {
	title := "New Source"
	if s.EditingIndex >= 0 {
		title = "Edit Source"
	}

	var lines []string

	lines = append(lines, lipgloss.NewStyle().
		Bold(true).
		Foreground(s.PrimaryColor).
		Render(title))
	lines = append(lines, "")

	// First input
	prompt := s.Config.FormPrompt
	if prompt == "" {
		prompt = "Path"
	}
	lines = append(lines, fmt.Sprintf("%s: %s", prompt, s.Inputs[0].View()))

	// Second input (if configured)
	if len(s.Inputs) > 1 && s.Config.Field2Label != "" {
		lines = append(lines, fmt.Sprintf("%s: %s", s.Config.Field2Label, s.Inputs[1].View()))
	}

	// Help text
	lines = append(lines, "")
	if len(s.Inputs) > 1 {
		lines = append(lines, "Enter=save Tab=next Esc=cancel")
	} else {
		lines = append(lines, "Enter=save Esc=cancel")
	}

	return strings.Join(lines, "\n")
}

SourceList.renderList.src:
// renderList renders the source list.
//
//nolint:gocognit,nestif // List rendering keeps the shared layout in one place.
func (s *SourceList) renderList() string {
	var lines []string

	lines = append(lines, lipgloss.NewStyle().
		Bold(true).
		Foreground(s.PrimaryColor).
		Render(s.Config.Title))
	lines = append(lines, "")
	label := s.Config.ListLabel
	if label == "" {
		label = "Defined sources:"
	}
	lines = append(lines, label)

	if len(s.Items) == 0 {
		lines = append(lines, lipgloss.NewStyle().
			Foreground(s.Gray).
			Render("  (no sources defined)"))
	} else {
		start, end := 0, len(s.Items)+1
		if s.Config.NewLabel != "" && s.Height > 0 {
			visible := max(1, s.Height-sourceListReservedRows)
			start = max(0, s.Cursor-visible+1)
			end = min(end, start+visible)
		}
		for i, item := range s.Items {
			if i < start || i >= end {
				continue
			}
			prefix := "  "
			if i == s.Cursor {
				prefix = "> "
			}

			line := fmt.Sprintf("%s%s", prefix, item.Display())
			if s.Config.NewLabel != "" && s.Width > 0 {
				line = TruncateHead(DisplayText(line), s.Width)
			}

			if i == s.Cursor {
				line = lipgloss.NewStyle().
					Foreground(s.HighlightColor).
					Render(line)
			}
			lines = append(lines, line)
		}
	}

	// "New" option
	prefix := "  "
	if s.Cursor == len(s.Items) {
		prefix = "> "
	}
	newLabel := s.Config.NewLabel
	if newLabel == "" {
		newLabel = "[ New Source ]"
	}
	newLine := fmt.Sprintf("%s%s", prefix, newLabel)
	if s.Cursor == len(s.Items) {
		newLine = lipgloss.NewStyle().
			Foreground(s.HighlightColor).
			Render(newLine)
	}
	if s.Config.NewLabel == "" || s.Height <= 0 || len(s.Items) < max(1, s.Height-sourceListReservedRows) ||
		s.Cursor >= len(s.Items)-max(1, s.Height-sourceListReservedRows)+1 {
		lines = append(lines, newLine)
	}

	// Legend
	if s.Config.Legend != "" {
		lines = append(lines, "")
		lines = append(lines, lipgloss.NewStyle().
			Foreground(s.Gray).
			Render(s.Config.Legend))
	}

	// Help text
	lines = append(lines, "")
	help := s.Config.Help
	if help == "" {
		help = "Enter/Space=edit n=new d=delete r=refresh Esc=back"
	}
	lines = append(lines, help)

	return strings.Join(lines, "\n")
}

SourceList.updateForm.src:
// updateForm handles form mode input.
func (s *SourceList) updateForm(msg tea.Msg) (component.Model, tea.Cmd) {
	// Update all inputs
	var cmd tea.Cmd
	cmds := make([]tea.Cmd, len(s.Inputs))
	for i := range s.Inputs {
		s.Inputs[i], cmds[i] = s.Inputs[i].Update(msg)
	}
	cmd = tea.Batch(cmds...)

	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return s, cmd
	}

	switch keyMsg.Code {
	case tea.KeyEnter:
		saveCmd := s.HandleSave()
		return s, tea.Batch(cmd, saveCmd)
	case tea.KeyTab:
		s.cycleInputFocus()
		return s, cmd
	case tea.KeyEsc:
		s.Mode = SourceListModeList
	}

	return s, cmd
}

SourceList.updateList.src:
// updateList handles list mode input.
func (s *SourceList) updateList(msg tea.Msg) (component.Model, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return s, nil
	}

	switch keyMsg.Code {
	case tea.KeyUp:
		s.moveUp()
	case tea.KeyDown:
		s.moveDown()
	case tea.KeyEnter, tea.KeySpace:
		if s.Callbacks.OnActivate != nil {
			return s, s.Callbacks.OnActivate(s.Cursor)
		}
		s.OpenForm(s.Cursor)
	case tea.KeyBackspace:
		return s, s.HandleDelete()
	case tea.KeyEsc:
		if s.Callbacks.OnClose != nil {
			s.Callbacks.OnClose()
		}
	default:
		return s, s.handleListRune(keyMsg.Text)
	}

	return s, nil
}

