UpsertInSlice.src:
// UpsertInSlice adds or updates an item in a slice.
// getID and setID functions provide ID access.
func UpsertInSlice[T any](
	items []T,
	item T,
	getID func(T) string,
	setID func(*T, string),
) ([]T, T) {
	if getID(item) == "" {
		setID(&item, uuid.NewString())
	}
	for i := range items {
		if getID(items[i]) == getID(item) {
			items[i] = item
			return items, item
		}
	}
	return append(items, item), item
}

