// BeginDashboardDeletion persists a new intent. The caller must coordinate
// authorization and admission with the manager before writing it.
func (r *FileRepository) BeginDashboardDeletion(manifest DashboardDeletion) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := validateDashboardDeletion(manifest); err != nil {
		return err
	}
	manifests, err := r.listDashboardDeletionsLocked()
	if err != nil {
		return err
	}
	for _, existing := range manifests {
		if existing.DashboardID == manifest.DashboardID {
			return errors.New("dashboard deletion already exists")
		}
	}
	return r.writeDashboardDeletionLocked(manifest)
}

FileRepository.CreateDashboard.src:
// CreateDashboard adds an active dashboard to an already initialized inventory.
func (r *FileRepository) CreateDashboard(d Dashboard) (Dashboard, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	f, err := r.loadDashboardsLocked()
	if err != nil {
		return Dashboard{}, err
	}
	if d.ID == "" {
		d.ID = uuid.NewString()
	}
	tombstones, err := r.loadDashboardTombstonesLocked()
	if err != nil {
		return Dashboard{}, err
	}
	for _, item := range tombstones.Tombstones {
		if item.ID == d.ID {
			return Dashboard{}, errors.New("dashboard ID is deleted and cannot be reused")
		}
	}
	d.State = DashboardActive
	if errAt63 := validateDashboard(d); errAt63 != nil {
		return Dashboard{}, errAt63
	}
	for _, existing := range f.Dashboards {
		if existing.ID == d.ID {
			return Dashboard{}, fmt.Errorf("dashboard id already exists: %s", d.ID)
		}
	}
	f.Dashboards = append(f.Dashboards, d)
	if errAt72 := r.WriteAtomic(filepath.Join(r.dir, DashboardsFilename), f); errAt72 != nil {
		return Dashboard{}, errAt72
	}
	return d, nil
}

FileRepository.CreateIDCard.src:
// CreateIDCard validates and persists a new ID card.
func (r *FileRepository) CreateIDCard(card IDCard) (IDCard, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if card.ID == "" {
		card.ID = uuid.NewString()
	}
	if err := r.checkCardNotTombstonedLocked(card.ID); err != nil {
		return IDCard{}, err
	}
	now := time.Now().UTC()
	card.CreatedAt = now
	card.UpdatedAt = now

	f, err := r.LoadIDCardsFile()
	if err != nil {
		return IDCard{}, err
	}
	if err = r.ValidateCard(card); err != nil {
		return IDCard{}, err
	}
	for _, existing := range f.IDCards {
		if existing.ID == card.ID {
			return IDCard{}, fmt.Errorf("id card id already exists: %s", card.ID)
		}
	}
	f.IDCards = append(f.IDCards, card)
	persisted, err := r.writeIDCardsFile(f)
	if err != nil {
		return IDCard{}, err
	}
	for _, item := range persisted.IDCards {
		if item.ID == card.ID {
			return item, nil
		}
	}
	return IDCard{}, errors.New("saved card absent from encoded inventory")
}

