FileRepository.FinalizeDashboardDeletion.src:
// FinalizeDashboardDeletion removes the dashboard record only after every
// recorded cascade effect is durable, then removes its recovery manifest.
//
//nolint:gocognit // Validate each durable cleanup checkpoint before finalization.
func (r *FileRepository) FinalizeDashboardDeletion(id string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	manifests, err := r.listDashboardDeletionsLocked()
	if err != nil {
		return err
	}
	var selected *DashboardDeletion
	for index := range manifests {
		if manifests[index].DashboardID == id {
			selected = &manifests[index]
			break
		}
	}
	if selected == nil {
		return errors.New("dashboard deletion manifest not found")
	}
	if !selected.AdmissionsDrained || !selected.HistoryRemoved {
		return errors.New("dashboard deletion is incomplete")
	}
	for _, item := range selected.Sessions {
		if !item.Removed || !item.Stopped || !item.RecordDeleted || !item.TemporaryRemoved {
			return errors.New("dashboard session cleanup is incomplete")
		}
	}
	for _, item := range selected.Cards {
		if !item.Deleted {
			return errors.New("dashboard card cleanup is incomplete")
		}
	}
	for _, item := range selected.Pending {
		if !item.Cleaned {
			return errors.New("pending activation cleanup is incomplete")
		}
	}
	if errAt211 := r.retainDashboardTombstoneLocked(id); errAt211 != nil {
		return errAt211
	}
	dashboards, err := r.loadDashboardsLocked()
	if err != nil {
		return err
	}
	dashboards.Dashboards = slices.DeleteFunc(dashboards.Dashboards, func(item Dashboard) bool { return item.ID == id })
	if errAt219 := r.WriteAtomic(filepath.Join(r.dir, DashboardsFilename), dashboards); errAt219 != nil {
		return errAt219
	}
	dir := filepath.Join(r.dir, dashboardDeletionsDir)
	if errAt223 := os.Remove(filepath.Join(dir, dashboardDeletionFilename(id))); errAt223 != nil {
		return errAt223
	}
	directory, err := os.Open(dir)
	syncErr := err
	if err == nil {
		syncErr = errors.Join(directory.Sync(), directory.Close())
	}
	if syncErr == nil {
		return nil
	}
	raw, marshalErr := json.MarshalIndent(selected, "", "  ")
	if marshalErr != nil {
		return errors.Join(syncErr, marshalErr)
	}
	restoreErr := fsutil.WriteFileAtomic(filepath.Join(dir, dashboardDeletionFilename(id)), raw, configFileMode)
	return errors.Join(syncErr, restoreErr)
}

FileRepository.Fingerprint.src:
// Fingerprint stats every registry file refreshConfig reads and returns a
// mtime+size marker for each, keyed by filename. It never opens or parses a
// file - just one [os.Stat] per registry, so a caller can decide whether a
// refresh is worth doing without paying for the read+unmarshal+sort it might
// skip.
//
// Two Fingerprints comparing equal (see FileStamp) is a "probably unchanged"
// signal, not a guarantee: mtime granularity is 1s on some filesystems, so a
// write landing in the same second as the previous stat can be missed. That
// residual is accepted - every in-app mutation already calls Fingerprint
// itself and sets the resulting baseline directly (see
// coordinator.refreshDataSeeded), so a same-second write there is reflected
// immediately regardless of the stat; only out-of-band hand-edits actually
// depend on a later tick's stat noticing the change, and picking those up a
// tick late is fine.
//
// A missing registry file (EnsureFiles only runs at startup, so a user can
// hand-delete one while the app is running) records a stable zero FileStamp
// rather than failing the whole call: an error here used to return a nil
// stamps map, which never compares equal to anything, silently disabling
// this optimization - every registry got re-read on every tick, for the rest
// of the session, with no signal that it had happened. A zero stamp compares
// equal to itself tick to tick and differs from a real stat the moment the
// file reappears. Any other stat failure (e.g. a permissions error) is still
// returned as a real error.
func (r *FileRepository) Fingerprint() (map[string]FileStamp, error) {
	files := registryFiles()
	stamps := make(map[string]FileStamp, len(files))
	for _, name := range files {
		info, err := os.Stat(filepath.Join(r.dir, name))
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				stamps[name] = FileStamp{}
				continue
			}
			return nil, fmt.Errorf("stat %s: %w", name, err)
		}
		stamps[name] = FileStamp{ModTime: info.ModTime(), Size: info.Size()}
	}
	return stamps, nil
}

FileRepository.FinishCardDeletion.src:
// FinishCardDeletion removes configuration and marks a durable intent complete.
// Repeating it is safe after either write or a process interruption.
func (r *FileRepository) FinishCardDeletion(id string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	tombstones, err := r.loadCardTombstonesLocked()
	if err != nil {
		return err
	}
	index := slices.IndexFunc(tombstones.Tombstones, func(item CardTombstone) bool { return item.ID == id })
	if index < 0 {
		return errors.New("card deletion intent not found")
	}
	item := tombstones.Tombstones[index]
	if item.State == CardDeleted {
		return nil
	}
	for _, pending := range item.Pending {
		if !pending.Cleaned {
			return errors.New("card activation cleanup is incomplete")
		}
	}
	cards, err := r.LoadIDCardsFile()
	if err != nil {
		return err
	}
	for _, card := range cards.IDCards {
		if card.ID == id && card.DashboardID != item.DashboardID {
			return errors.New("card deletion owner mismatch")
		}
	}
	originalCount := len(cards.IDCards)
	cards.IDCards = slices.DeleteFunc(cards.IDCards, func(card IDCard) bool { return card.ID == id })
	if len(cards.IDCards) != originalCount {
		if errAt116 := r.WriteIDCardsFile(cards); errAt116 != nil {
			return errAt116
		}
	}
	tombstones.Tombstones[index].State = CardDeleted
	return r.WriteAtomic(filepath.Join(r.dir, CardTombstonesFilename), tombstones)
}

FileRepository.GetAppSettings.src:
// GetAppSettings loads app settings from disk. Fields absent from the file
// keep DefaultAppSettings' value (so a field added after the file was first
// written defaults sanely instead of zeroing); fields present are decoded
// straight from the real AppSettings struct via reflection, so a field added
// to AppSettings is picked up automatically without hand-editing a second,
// divergent schema here (see TestGetAppSettingsCoversEveryField for the
// regression guard).
func (r *FileRepository) GetAppSettings() (AppSettings, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	path := filepath.Join(r.dir, AppSettingsFilename)
	var raw struct {
		SchemaVersion int                  `yaml:"schema_version"`
		AppSettings   map[string]yaml.Node `yaml:"app_settings"`
	}
	if err := ReadYAML(path, &raw); err != nil {
		return AppSettings{}, err
	}
	settings := DefaultAppSettings()
	if err := overlayYAMLFields(&settings, raw.AppSettings); err != nil {
		return AppSettings{}, fmt.Errorf("decode app_settings: %w", err)
	}
	return settings, nil
}

