	f := MCPsFile{}
	if err := ReadYAML(path, &f); err != nil {
		return MCPsFile{}, err
	}
	if f.SchemaVersion == 0 {
		f.SchemaVersion = SchemaVersion
	}
	if f.MCPs == nil {
		f.MCPs = []MCPServer{}
	}
	return f, nil
}

