FileRepository.UpdateDashboardDetails.src:
// UpdateDashboardDetails changes human-readable fields without changing identity
// or lifecycle state. Deletion must be handled by the cascade protocol.
func (r *FileRepository) UpdateDashboardDetails(id, name, description string) (Dashboard, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	f, err := r.loadDashboardsLocked()
	if err != nil {
		return Dashboard{}, err
	}
	for i, d := range f.Dashboards {
		if d.ID != id {
			continue
		}
		if d.State != DashboardActive {
			return Dashboard{}, fmt.Errorf("dashboard %s is deleting", id)
		}
		d.Name, d.Description = name, description
		if errAt95 := validateDashboard(d); errAt95 != nil {
			return Dashboard{}, errAt95
		}
		f.Dashboards[i] = d
		if errAt99 := r.WriteAtomic(filepath.Join(r.dir, DashboardsFilename), f); errAt99 != nil {
			return Dashboard{}, errAt99
		}
		return d, nil
	}
	return Dashboard{}, fmt.Errorf("dashboard not found: %s", id)
}

FileRepository.UpdateIDCard.src:
// UpdateIDCard validates and updates an existing ID card.
func (r *FileRepository) UpdateIDCard(card IDCard) (IDCard, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if card.ID == "" {
		return IDCard{}, errors.New("id is required")
	}
	if err := r.checkCardNotTombstonedLocked(card.ID); err != nil {
		return IDCard{}, err
	}
	f, err := r.LoadIDCardsFile()
	if err != nil {
		return IDCard{}, err
	}
	if err = r.ValidateCard(card); err != nil {
		return IDCard{}, err
	}
	found := false
	for _, existing := range f.IDCards {
		if existing.ID == card.ID {
			if existing.DashboardID != card.DashboardID {
				return IDCard{}, errors.New("card dashboard ownership cannot be changed")
			}
			card.CreatedAt = existing.CreatedAt
			found = true
			break
		}
	}
	if !found {
		return IDCard{}, fmt.Errorf("id card not found: %s", card.ID)
	}
	card.UpdatedAt = time.Now().UTC()

	f.IDCards, card = UpsertInSlice(
		f.IDCards,
		card,
		func(c IDCard) string { return c.ID },
		func(c *IDCard, id string) { c.ID = id },
	)

	persisted, err := r.writeIDCardsFile(f)
	if err != nil {
		return IDCard{}, err
	}
	for _, item := range persisted.IDCards {
		if item.ID == card.ID {
			return item, nil
		}
	}
	return IDCard{}, errors.New("saved card absent from encoded inventory")
}

FileRepository.UpdatePersonaSources.src:
// UpdatePersonaSources reads the current persona sources, applies fn,
// persists the result, and re-syncs the persona registry - all under one
// lock acquisition. See UpdateSkillSources for why this exists and what a
// *SyncFailedError return means.
func (r *FileRepository) UpdatePersonaSources(fn func([]string) ([]string, error)) error {
