	}
	if err = r.WritePersonaSourcesFile(PersonaSourcesFile{SchemaVersion: SchemaVersion, Paths: updated}); err != nil {
		return err
	}
	if err = r.syncPersonasFromSourcesLocked(); err != nil {
		return &SyncFailedError{Err: err}
	}
	return nil
}

