FileRepository.listDashboardDeletionsLoc.src:
func (r *FileRepository) listDashboardDeletionsLocked() ([]DashboardDeletion, error) {
	dir := filepath.Join(r.dir, dashboardDeletionsDir)
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return []DashboardDeletion{}, nil
	}
	if err != nil {
		return nil, err
	}
	var manifests []DashboardDeletion
	seen := make(map[string]bool)
	for _, entry := range entries {
		if filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		if !entry.Type().IsRegular() {
			return nil, fmt.Errorf("dashboard deletion %s is not a regular file", entry.Name())
		}
		raw, readErr := os.ReadFile(filepath.Join(dir, entry.Name()))
		if readErr != nil {
			return nil, readErr
		}
		var manifest DashboardDeletion
		if decodeErr := json.Unmarshal(raw, &manifest); decodeErr != nil {
			return nil, fmt.Errorf("invalid dashboard deletion %s: %w", entry.Name(), decodeErr)
		}
		if validationErr := validateDashboardDeletion(manifest); validationErr != nil {
			return nil, validationErr
		}
		if seen[manifest.DashboardID] || entry.Name() != dashboardDeletionFilename(manifest.DashboardID) {
			return nil, errors.New("duplicate or mismatched dashboard deletion")
		}
		seen[manifest.DashboardID] = true
		manifests = append(manifests, manifest)
	}
	return manifests, nil
}

FileRepository.listIDCardsLocked.src:
// listIDCardsLocked is ListIDCards without acquiring r.mu, for use by callers
// that already hold it.
func (r *FileRepository) listIDCardsLocked() ([]IDCard, error) {
	f, err := r.LoadIDCardsFile()
	if err != nil {
		return nil, err
	}
	sort.Slice(f.IDCards, func(i, j int) bool { return f.IDCards[i].Name < f.IDCards[j].Name })
	return f.IDCards, nil
}

FileRepository.listMCPsLocked.src:
func (r *FileRepository) listMCPsLocked() ([]MCPServer, error) {
	f, err := r.LoadMCPsFile()
	if err != nil {
		return nil, err
	}
	for _, mcp := range f.MCPs {
		if mcp.ID == BuiltinMCPKankuro || strings.EqualFold(mcp.Name, "kankuro") {
			return nil, fmt.Errorf("MCP registry collides with built-in kankuro server: %s", mcp.ID)
		}
	}
	merged := MergeBuiltinMCPs(f.MCPs)
	sort.Slice(merged, func(i, j int) bool { return merged[i].Name < merged[j].Name })
	return merged, nil
}

