ConversationPreparation.Validate.src:
// Validate rejects contradictory or incomplete preparation data.
func (p ConversationPreparation) Validate() error {
	if (p.Diagnostic == "") != (p.DiagnosticCode == "") {
		return errors.New("invalid conversation diagnostic")
	}
	if p.Diagnostic != "" {
		if p.DiagnosticCode != DiagnosticFailure && p.DiagnosticCode != DiagnosticCancelled {
			return errors.New("invalid conversation diagnostic code")
		}
		return nil
	}
	if p.DashboardID == "" || p.SessionID == "" || p.CardID == "" || p.HasSaved != (len(p.Options) > 0) ||
		(!p.Availability.Enabled && p.Availability.Reason == "") {
		return errors.New("invalid conversation preparation")
	}
	seen := make(map[string]bool, len(p.Options))
	for _, option := range p.Options {
		if option.SelectionID == "" || seen[option.SelectionID] || (!option.Compatible && option.Reason == "") {
			return errors.New("invalid conversation option")
		}
		seen[option.SelectionID] = true
	}
	return nil
}

LifecycleResult.Validate.src:
func (r LifecycleResult) Validate() error {
	if (r.Diagnostic == "") != (r.DiagnosticCode == "") {
		return errors.New("invalid lifecycle diagnostic")
	}
	switch r.Effect {
	case NoEffect:
		if (r.DiagnosticCode == DiagnosticFailure || r.DiagnosticCode == DiagnosticCancelled) && r.Diagnostic != "" && r.SessionID == "" &&
			r.ProcessActivationID == "" &&
			r.PID == 0 {
			return nil
		}
	case UsableActivation:
		if r.SessionID != "" && r.ProcessActivationID != "" &&
			(r.DiagnosticCode == "" || r.DiagnosticCode == DiagnosticPersistence || r.DiagnosticCode == DiagnosticFailure || r.DiagnosticCode == DiagnosticCancelled || r.DiagnosticCode == DiagnosticPartial) {
			return nil
		}
	case UncertainEffect:
		if (r.DiagnosticCode == DiagnosticUncertain || r.DiagnosticCode == DiagnosticInvalid) && r.Diagnostic != "" &&
			r.ProcessActivationID == "" {
			return nil
		}
	}
	return errors.New("invalid lifecycle result")
}

