atomicTrustWrite.src:
func atomicTrustWrite(path string, data []byte) (err error) {
	if err = os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	mode := os.FileMode(0o600) //nolint:mnd // Private configuration for a newly created file.
	if info, statErr := os.Stat(path); statErr == nil {
		mode = info.Mode().Perm()
	} else if !errors.Is(statErr, os.ErrNotExist) {
		return statErr
	}
	f, err := os.CreateTemp(filepath.Dir(path), ".kankuro-trust-*")
	if err != nil {
		return err
	}
	tempName := f.Name()
	defer os.Remove(tempName)
	defer func() {
		if f != nil {
			err = errors.Join(err, f.Close())
		}
	}()
	if err = f.Chmod(mode); err != nil {
		return err
	}
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		f = nil
		return err
	}
	f = nil
	return os.Rename(tempName, path)
}

classifySubmission.src:
func classifySubmission(written, promptLength int, enterPause time.Duration, writeErr error) SubmissionEvidence {
	wantWritten := promptLength
	if enterPause > 0 {
		wantWritten++
	}
	evidence := SubmissionEvidence{State: SubmissionComplete, BytesWritten: written}
	if written == 0 {
		evidence.State = SubmissionNoBytes
	} else if written != wantWritten || writeErr != nil {
		evidence.State = SubmissionUncertain
	}
	return evidence
}

