func resolveWorkspaceRoot(workspaceRoot []string) (string, error) {
	if len(workspaceRoot) == 0 {
		return "", errors.New("workspace root is required for skill sync")
	}
	root := strings.TrimSpace(workspaceRoot[0])
	if root == "" {
		return "", errors.New("workspace root is required for skill sync")
