writeInstructionFile.src:
func writeInstructionFile(dir, filename, content string, appendIfExist bool) error {
	path := filepath.Join(dir, filename)
	if !appendIfExist {
		// G703: Path traversal via taint analysis.
		return os.WriteFile(path, []byte(content), 0o600)
	}

	// Append mode is used when a temporary copy started from a workspace with
	// its own instruction file. Preserve its content when adding card instructions.
	existing, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("read %s: %w", filename, err)
	}
	if len(existing) > 0 {
		content = strings.TrimRight(string(existing), "\n") + "\n\n" + strings.TrimLeft(content, "\n")
	}
	// G703: Path traversal via taint analysis.
	//nolint:gosec // Target is the workspace's managed instruction file, selected by the configured driver.
	if writeErr := os.WriteFile(path, []byte(content), 0o600); writeErr != nil {
		return fmt.Errorf("write %s: %w", filename, writeErr)
	}
	return nil
}

writePromptEnter.src:
func writePromptEnter(ctx context.Context, writer io.Writer) (int, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	return writeAll(writer, []byte{'\r'})
}

writePromptPhases.src:
func writePromptPhases(ctx context.Context, writer io.Writer, prompt []byte, enterPause time.Duration) (int, error) {
	written, err := writeAll(writer, prompt)
	if err != nil || enterPause == 0 || written != len(prompt) {
		return written, err
	}
	if err = waitForPromptEnter(ctx, enterPause); err != nil {
		return written, err
	}
	enterWritten, err := writePromptEnter(ctx, writer)
	return written + enterWritten, err
}

writeWorkspaceMCPConfig.src:
func writeWorkspaceMCPConfig(mcps []config.MCPServer, workspaceRoot string) error {
	if strings.TrimSpace(workspaceRoot) == "" {
		return errors.New("workspace root is required for MCP sync")
	}
	kankuroDir := filepath.Join(workspaceRoot, ".kankuro")
	if err := os.MkdirAll(kankuroDir, kankuroDirMode); err != nil {
		return fmt.Errorf("create .kankuro dir: %w", err)
	}
	entries := make(map[string]mcpConfigEntry, len(mcps))
	for _, server := range mcps {
		if server.ID == config.BuiltinMCPKankuro &&
			(strings.TrimSpace(server.URL) == "" || strings.TrimSpace(server.Headers[authorizationHeader]) == "") {
			return errors.New("built-in kankuro MCP requires a runtime URL and authorization header")
		}
		entries[server.Name] = mcpConfigEntry{
			Command: server.Command,
			Args:    server.Args,
			Env:     server.Env,
			CWD:     server.CWD,
			URL:     server.URL,
			Headers: server.Headers,
		}
	}
	data, err := json.MarshalIndent(mcpConfigFile{MCPServers: entries}, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal MCP config: %w", err)
	}
	if writeErr := fsutil.WriteFileAtomic(MCPConfigPath(workspaceRoot), data, mcpConfigFileMode); writeErr != nil {
		return fmt.Errorf("write mcp-servers.json: %w", writeErr)
	}
	return nil
}

