GenericCLIDriver.acquireInput.src:
func (d *GenericCLIDriver) acquireInput(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	d.gateOnce.Do(func() {
		if d.inputGate == nil {
			d.inputGate = make(chan struct{}, 1)
		}
	})
	select {
	case d.inputGate <- struct{}{}:
		if err := ctx.Err(); err != nil {
			<-d.inputGate
			return err
		}
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

GenericCLIDriver.closeDone.src:
func (d *GenericCLIDriver) closeDone() {
	if d.done == nil {
		return
	}
	d.once.Do(func() {
		close(d.done)
	})
}

GenericCLIDriver.streamOutput.src:
func (d *GenericCLIDriver) streamOutput(f *os.File, out chan []byte) {
	buf := make([]byte, readBufferSize)
	for {
		n, err := f.Read(buf)
		if n > 0 {
			chunk := make([]byte, n)
			copy(chunk, buf[:n])
			out <- chunk
		}
		if err != nil {
			break
		}
	}
	close(out)
}

GenericCLIDriver.submitPrompt.sig:
func (d *GenericCLIDriver) submitPrompt(
	ctx context.Context,
	envelope PromptEnvelope,
	enterPause time.Duration,
) (SubmissionEvidence, error)

GenericCLIDriver.submitPrompt.src:
func (d *GenericCLIDriver) submitPrompt(
	ctx context.Context,
	envelope PromptEnvelope,
	enterPause time.Duration,
) (SubmissionEvidence, error) {
	if err := ctx.Err(); err != nil {
		return SubmissionEvidence{State: SubmissionNoBytes}, err
	}
	text, err := formatPrompt(envelope)
	if err != nil {
		return SubmissionEvidence{State: SubmissionNoBytes}, err
	}
	if acquireErr := d.acquireInput(ctx); acquireErr != nil {
		return SubmissionEvidence{State: SubmissionNoBytes}, acquireErr
	}
	defer d.releaseInput()
	if envelope.BeforeWrite != nil {
		if validationErr := envelope.BeforeWrite(); validationErr != nil {
			return SubmissionEvidence{State: SubmissionNoBytes}, validationErr
		}
	}
	prompt := []byte(text)
	if enterPause == 0 {
		prompt = append(prompt, '\r')
	}
	written, writeErr := d.submitPromptBytes(ctx, prompt, enterPause)
	evidence := classifySubmission(written, len(prompt), enterPause, writeErr)
	if writeErr != nil {
		return evidence, fmt.Errorf("submit prompt after %d bytes: %w", written, writeErr)
	}
	if evidence.State == SubmissionUncertain {
		return evidence, io.ErrShortWrite
	}
	return evidence, nil
}

GenericCLIDriver.submitPromptBytes.sig:
func (d *GenericCLIDriver) submitPromptBytes(
	ctx context.Context,
