main.src:
// main wires repository, session manager, MCP endpoint, and TUI program startup.
func main() {
	config.SetBuiltinMCPCLISkillContent(embeddedMCPCLISkill)
	config.SetBuiltinKankuroPuppetSkillContent(embeddedKankuroPuppetSkill)
	// Create and configure driver registry
	registry := driver.NewBuiltinRegistry()

	if err := run(registry); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}

run.src:
//nolint:funlen,gocognit // Keep startup and shutdown ordering visible in the composition root.
func run(registry driver.Registry) (returnErr error) {
	var cfgDir string
	var debug bool
	flag.StringVar(&cfgDir, "config-dir", os.Getenv("KANKURO_CONFIG_DIR"), "override config directory")
	flag.BoolVar(&debug, "debug", false, "write debug logs")
	flag.Parse()

	configRoot, err := config.ResolveDirectory(cfgDir)
	if err != nil {
		return err
	}
	configLock, err := configstartup.AcquireLock(configRoot)
	if err != nil {
		return err
	}
	defer func() { returnErr = errors.Join(returnErr, configLock.Close()) }()
	if startupErr := configstartup.PrepareStartup(configRoot); startupErr != nil {
		return startupErr
	}

	// internal/session logs background-only failures (no caller to report
	// them to, e.g. a persist failure from the watch ticker) via an injected
	// *slog.Logger (session.WithLogger) rather than a global one, so it never
	// risks writing to stderr and corrupting the rendered TUI frame. Without
	// --debug that logger stays a no-op (its default); with --debug, point it
	// at the same debug log file used for bubbletea's own logging.
	var sessionLogger *slog.Logger
	if debug {
		if mkdirErr := os.MkdirAll(logDir(), 0o700); mkdirErr == nil {
			logFile, logErr := tea.LogToFile(filepath.Join(logDir(), "kankuro.log"), "debug")
			if logErr == nil {
				defer logFile.Close()
				sessionLogger = slog.New(slog.NewTextHandler(logFile, nil))
			}
		}
	}

	repo, err := config.NewFileRepository(configRoot)
	if err != nil {
		return fmt.Errorf("config init error: %w", err)
	}

	if err = repo.SyncSkillsFromSources(); err != nil {
		return fmt.Errorf("skill sync error: %w", err)
	}
	// Finish writing the puppet registry before the UI starts reading it.
	var puppetSyncWarning error
	if syncErr := repo.SyncPuppetsFromSources(); syncErr != nil {
		puppetSyncWarning = fmt.Errorf("sync puppet sources: %w", syncErr)
	}

	sm := session.NewManager(
		repo.Dir(),
		repo,
		session.WithDriverRegistry(registry),
		session.WithLogger(sessionLogger),
	)
	sharedAPI := api.New(repo, sm)
	operationRunner := api.NewOperationRunner(repo.Dir(), sharedAPI)
	sharedAPI.SetOperationRunner(operationRunner)
	application, err := ui.New(ui.Capabilities{
		Configuration: sharedAPI, Center: sharedAPI, Reads: sharedAPI, Editor: sharedAPI,
		Actions: sharedAPI, Attachment: sharedAPI, Deletion: sharedAPI,
	}, errors.Join(sm.LoadErrors(), puppetSyncWarning))
	if err != nil {
		operationRunner.Shutdown()
		sm.Shutdown()
		return fmt.Errorf("ui init error: %w", err)
	}
	if journalErr := operationRunner.LoadError(); journalErr != nil {
		fmt.Fprintf(os.Stderr, "kankuro: lifecycle MCP tools disabled because the operation journal could not be loaded: %v\n", journalErr)
	}
	mcpRuntime, err := mcp.Start(sharedAPI)
	if err != nil {
		operationRunner.Shutdown()
		sm.Shutdown()
		return fmt.Errorf("start MCP endpoint: %w", err)
	}
	sm.SetMCPEndpoint(mcpRuntime.Endpoint())
	p := tea.NewProgram(application)
	failureCtx, stopFailureWatch := context.WithCancel(context.Background())
	serverFailures := make(chan error, 1)
	failureWatcherDone := make(chan struct{})
	go func() {
		defer close(failureWatcherDone)
		select {
		case serverErr := <-mcpRuntime.Failures():
			serverFailures <- serverErr
			p.Send(ui.RuntimeError(fmt.Errorf("MCP server stopped: %w", serverErr)))
		case <-failureCtx.Done():
		}
	}()

	// Bubble Tea catches SIGINT (Run returns ErrInterrupted) and SIGTERM (it
	// becomes a QuitMsg) but not SIGHUP, which is what closing the terminal
	// window sends. Go's default action for SIGHUP would end kankuro on the
	// spot, before any cleanup, so turn it into a normal quit. If the terminal
	// is really gone, Run may return a write error instead of nil; the
	// shutdown below runs either way.
	hup := make(chan os.Signal, 1)
	signal.Notify(hup, syscall.SIGHUP)
	defer signal.Stop(hup)
	go func() {
		<-hup // blocks until SIGHUP; the process exits long before it matters otherwise
		p.Quit()
	}()

	_, runErr := p.Run()
	application.Close()
	stopFailureWatch()
	<-failureWatcherDone
	select {
	case serverErr := <-serverFailures:
		if runErr == nil {
			runErr = fmt.Errorf("MCP server stopped: %w", serverErr)
		}
	default:
	}

	// Every exit path - q, ctrl+c, SIGINT, SIGTERM, SIGHUP, a runtime error -
	// ends up here, and running agents must not outlive kankuro. Plain
	// sequential code, not a defer, so the order is visible: the TUI is gone,
	// then the agents are stopped, then the error (if any) is returned.
	//
	// Bubble Tea has released the terminal by now, so one line to stderr is
	// safe here and only here; the "never write to stdout/stderr" rule is
	// about the TUI being live. Do not copy this into app code. While this
	// waits, Bubble Tea no longer handles signals, so a second ctrl+c or
	// SIGTERM gets Go's default action and exits at once - an acceptable
	// "force quit".
	operationRunner.Shutdown()
	stopSessions(sm)
	mcpShutdownErr := shutdownMCP(mcpRuntime)

	if runErr != nil {
		return errors.Join(fmt.Errorf("runtime error: %w", runErr), mcpShutdownErr)
	}
	return mcpShutdownErr
}

shutdownMCP.src:
func shutdownMCP(runtime *mcp.Runtime) error {
	ctx, cancel := context.WithTimeout(context.Background(), mcpShutdownTimeout)
	defer cancel()
	return runtime.Shutdown(ctx)
}

