LaunchWorkspaceCommand.src:
// LaunchWorkspaceCommand starts a configured command in a workspace directory.
func LaunchWorkspaceCommand(command, workspacePath string) error {
	if command == "" {
		return ErrCommandNotConfigured
	}
	if workspacePath == "" {
		return ErrWorkspacePathEmpty
	}
	absPath, err := filepath.Abs(workspacePath)
	if err != nil {
		return err
	}
	if _, err = os.Stat(absPath); err != nil {
		return err
	}
	parts := SplitCommand(strings.ReplaceAll(command, PathPlaceholder, absPath))
	if len(parts) == 0 {
		return ErrInvalidCommand
	}
	child := exec.CommandContext(context.Background(), parts[0], parts[1:]...) //nolint:gosec // configured command
	child.Dir = absPath
	child.Stdin, child.Stdout, child.Stderr = nil, nil, nil
	if startErr := child.Start(); startErr != nil {
		return startErr
	}
	go func() { _ = child.Wait() }()
	return nil
}

NewManager.src:
// NewManager creates a session registry and loads persisted sessions.
func NewManager(configDir string, repo WorkspaceReader, opts ...Option) *Manager {
	m := &Manager{
		sessions:                   make(map[string]*Session),
		pendingCardRefs:            make(map[string]int),
		pendingCardRefsByDashboard: make(map[string]map[string]int),
		pendingCardCancels:         make(map[string]map[*cardReservation]context.CancelFunc),
		pendingCardDetails:         make(map[string]map[*cardReservation]CardPendingReference),
		cardRefsChanged:            make(chan struct{}),
		dashboardDeletionWorkers:   make(map[string]bool),
		subWorkspaceGate:           make(chan struct{}, 1),
		launching:                  make(map[string]struct{}),
		configDir:                  configDir,
		repo:                       repo,
		drivers:                    driver.NewBuiltinRegistry(), // default builtin registry
		logger:                     slog.New(slog.DiscardHandler),
		stop:                       make(chan struct{}),
		shutdownStart:              make(chan struct{}),
		startupDelay:               startupDelay,
		startupClock:               realStartupClock{},
		authorities:                make(map[string]*activationAuthority),
		messageAdmissions:          make(map[*MessageAdmission]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}

	sessionsDir := filepath.Join(configDir, "sessions")
	loaded, loadErr := loadSessions(sessionsDir)
	m.loadErr = loadErr

	for _, d := range loaded {
		m.sessions[d.ID] = d.restore()
	}
	messageStore, messageErr := NewMessageStore(configDir)
	if messageErr != nil {
		m.loadErr = errors.Join(m.loadErr, messageErr)
	} else {
		m.messages = messageStore
		if recoverErr := messageStore.Recover(m.sessions); recoverErr != nil {
			m.loadErr = errors.Join(m.loadErr, recoverErr)
		}
	}

	return m
}

NewMessageStore.src:
// NewMessageStore loads the durable message journal from a private directory.
func NewMessageStore(configDir string) (*MessageStore, error) {
	dir := filepath.Join(configDir, "messaging")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("create messaging directory: %w", err)
	}
	store := &MessageStore{
		path:               filepath.Join(dir, "history.json"),
		changed:            make(chan struct{}),
		reportsChanged:     make(chan struct{}),
		reportScopeChanged: make(chan struct{}),
		data:               messageStoreData{DashboardGenerations: make(map[string]uint64)},
		runtimeDelivery:    make(map[string]runtimeDeliveryOutcome),
	}
	bytes, err := os.ReadFile(store.path)
	if errors.Is(err, os.ErrNotExist) {
		return store, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read messaging history: %w", err)
	}
	if err = json.Unmarshal(bytes, &store.data); err != nil {
		return nil, fmt.Errorf("decode messaging history: %w", err)
	}
	if store.data.DashboardGenerations == nil {
		store.data.DashboardGenerations = make(map[string]uint64)
	}
	return store, nil
}

ReadSubWorkspaceDescriptors.src:
// ReadSubWorkspaceDescriptors reads the workspace manifest without preparing or
// recreating anything. The availability result distinguishes absent/invalid legacy metadata.
func ReadSubWorkspaceDescriptors(workingDir string) ([]SubWorkspaceDescriptor, bool) {
	if validateSessionWorkspace(workingDir) != nil {
		return nil, false
	}
	manifestPath := filepath.Join(workingDir, ".kankuro", "sub-workspaces.json")
	manifest, err := loadSubWorkspaceManifest(manifestPath)
	if err != nil {
		return nil, false
	}
	if _, statErr := os.Stat(manifestPath); statErr != nil {
		return nil, false
	}
	names := make([]string, 0, len(manifest.Copies))
	for name := range manifest.Copies {
		names = append(names, name)
	}
	sort.Strings(names)
	descriptors := make([]SubWorkspaceDescriptor, 0, len(names))
	for _, name := range names {
		entry := manifest.Copies[name]
		destination, absErr := filepath.Abs(filepath.Join(workingDir, "tmp", name))
		if absErr != nil {
			return nil, false
		}
		descriptors = append(descriptors, SubWorkspaceDescriptor{
			WorkspaceID: entry.WorkspaceID, SourcePath: entry.SourcePath, DestinationPath: destination,
		})
	}
	return descriptors, true
}

