func addConversationBinding(s *Session, cardID string, binding ConversationBinding) {
	if s.Conversations == nil {
		s.Conversations = make(map[string][]ConversationBinding)
	}
	bindings := s.Conversations[cardID]
	for i := range bindings {
		if bindings[i].Driver == binding.Driver && bindings[i].ID == binding.ID {
			bindings[i].Name = binding.Name
			s.Conversations[cardID] = bindings
			return
		}
	}
	s.Conversations[cardID] = append(bindings, binding)
}

appendScrollback.src:
func appendScrollback(existing, chunk []byte) []byte {
	if len(chunk) >= ScrollbackLimit {
		return bytes.Clone(chunk[len(chunk)-ScrollbackLimit:])
	}
	if len(existing)+len(chunk) <= ScrollbackLimit {
		return append(existing, chunk...)
	}
	trim := len(existing) + len(chunk) - ScrollbackLimit
	next := make([]byte, len(existing)-trim, ScrollbackLimit)
	copy(next, existing[trim:])
	return append(next, chunk...)
}

boundAuthoredReports.src:
// Include attribution bytes in the response budget, keeping complete records.
func boundAuthoredReports(candidates reportHeap, count int) (AuthoredReports, error) {
	total, kept := 0, 0
	for _, item := range candidates {
		size := len(item.ID) + len(item.MessageID) + len(item.SenderSessionID)
		size += len(item.SenderActivationID) + len(item.Kind) + len(item.Text)
		if len(item.Text) > messageReportLimitBytes {
			return AuthoredReports{}, errors.New("retained report exceeds size limit")
		}
		if size > authoredReportsMaxBytes-total {
			break
		}
		total += size
		kept++
	}
	if kept == 0 && count > 0 {
		return AuthoredReports{}, errors.New("retained report exceeds response budget")
	}
	return AuthoredReports{Items: []MessageReply(candidates[:kept]), Omitted: count - kept}, nil
}

broadcast.src:
func broadcast(chunk []byte, subscribers map[chan []byte]struct{}) {
	if len(subscribers) == 0 {
		return
	}
	for ch := range subscribers {
		data := bytes.Clone(chunk)
		select {
		case ch <- data:
		default:
		}
	}
}

