loadSessions.src:
// loadSessions reads every persisted session file in dir. Unreadable or
// unparseable files are skipped rather than aborting the whole load (one bad
// file must not block startup), but every skip is recorded and returned as a
// joined error so the caller can surface it once.
func loadSessions(dir string) ([]*Data, error) {
	matches, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil {
		return nil, err
	}
	var out []*Data
	var errs []error
	for _, path := range matches {
		fileData, errRead := os.ReadFile(path)
		if errRead != nil {
			errs = append(errs, fmt.Errorf("read session file %s: %w", path, errRead))
			continue
		}
		var s Data
		if errUnmarshal := json.Unmarshal(fileData, &s); errUnmarshal != nil {
			errs = append(errs, fmt.Errorf("parse session file %s: %w", path, errUnmarshal))
			continue
		}
		if s.SchemaVersion != sessionSchemaVersion {
			errs = append(errs, fmt.Errorf("session file %s has unsupported schema version %d", path, s.SchemaVersion))
			continue
		}
		if strings.TrimSpace(s.DashboardID) == "" {
			errs = append(errs, fmt.Errorf("session file %s has missing dashboard membership", path))
			continue
		}
		out = append(out, &s)
	}
	return out, errors.Join(errs...)
}

loadSubWorkspaceManifest.src:
func loadSubWorkspaceManifest(path string) (subWorkspaceManifest, error) {
	metadataDir := filepath.Dir(path)
	if err := rejectSymlink(metadataDir); err != nil {
		return subWorkspaceManifest{}, err
	}
	if err := rejectSymlink(path); err != nil {
		return subWorkspaceManifest{}, err
	}
	manifest := subWorkspaceManifest{
		SchemaVersion: subWorkspaceManifestVersion,
		Copies:        make(map[string]subWorkspaceCopy),
	}
	data, readErr := os.ReadFile(path)
	if errors.Is(readErr, os.ErrNotExist) {
		return manifest, nil
	}
	if readErr != nil {
		return subWorkspaceManifest{}, fmt.Errorf("read sub workspace manifest: %w", readErr)
	}
	if unmarshalErr := json.Unmarshal(data, &manifest); unmarshalErr != nil {
		return subWorkspaceManifest{}, fmt.Errorf("read sub workspace manifest: %w", unmarshalErr)
	}
	if manifest.SchemaVersion != subWorkspaceManifestVersion || manifest.Copies == nil {
		return subWorkspaceManifest{}, errors.New("unsupported sub workspace manifest")
	}
	for name := range manifest.Copies {
		if !safeSubWorkspaceName(name) {
			return subWorkspaceManifest{}, fmt.Errorf("unsafe sub workspace manifest destination: %s", name)
		}
	}
	return manifest, nil
}

