	}
	if err != nil {
		return instructionFileSnapshot{}, err
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return instructionFileSnapshot{}, err
	}
	return instructionFileSnapshot{content: content, mode: info.Mode().Perm(), exists: true}, nil
}

splitCommand.src:
// splitCommand parses a command string with quote support.
func splitCommand(cmd string) []string {
	var parts []string
	var current strings.Builder
	inQuote := false
	quoteChar := rune(0)

	for _, c := range cmd {
		if inQuote {
			if c == quoteChar {
				inQuote = false
				quoteChar = 0
			} else {
				current.WriteRune(c)
			}
			continue
		}

		if c == '"' || c == '\'' {
			inQuote = true
			quoteChar = c
			continue
		}

		if c == ' ' || c == '\t' {
			if current.Len() > 0 {
				parts = append(parts, current.String())
				current.Reset()
			}
			continue
		}

		current.WriteRune(c)
	}

	if current.Len() > 0 {
		parts = append(parts, current.String())
	}

	return parts
}

