// MessageRecipientLive reports whether a retained message still targets the
// same live recipient activation.
func (m *Manager) MessageRecipientLive(messageID string) (bool, error) {
	if m.messages == nil {
		return false, messagingError("history_unavailable", "messaging history is unavailable", nil)
	}
	recipientID, activationID, err := m.messages.MessageRecipient(messageID)
	if err != nil {
		return false, err
	}
	m.mu.RLock()
	defer m.mu.RUnlock()
	recipient := m.sessions[recipientID]
	if recipient == nil {
		return false, messagingError("history_unavailable", "message recipient session was deleted", nil)
	}
	return !m.closed && recipient.ActivationID == activationID &&
		recipient.Status != StatusTerminated && !recipient.stopping && !recipient.deleting && !recipient.activating, nil
}

Manager.OpenWorkspaceChecked.src:
// OpenWorkspaceChecked protects session identity and workspace cleanup until
// the configured child has started. The child outlives the manager lock and
// request. Cancellation is checked before start; it does not stop a started child.
// check runs under the manager lock and must not call the manager.
func (m *Manager) OpenWorkspaceChecked(ctx context.Context, id, command string, check func([]Snapshot) error) error {
	if check == nil {
		return errors.New("workspace scope check is required")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return ErrManagerClosed
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := check(m.listLocked()); err != nil {
		return err
	}
	s, ok := m.sessions[id]
	if !ok {
		return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	if s.deleting {
		return fmt.Errorf("%w: session is being removed", ErrLifecycleConflict)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return LaunchWorkspaceCommand(command, s.WorkingDir)
}

