Manager.PublishMessageAdmission.src:
// PublishMessageAdmission coordinates durable intent publication with lifecycle
// invalidation. A publisher already in progress holds its reservation until the
// publication transaction finishes; a lifecycle operation can invalidate it
// before publication starts.
func (m *Manager) PublishMessageAdmission(admission *MessageAdmission, publish func() error) error {
	if admission == nil || admission.manager != m || publish == nil {
		return messagingError("lifecycle_conflict", "message admission is no longer available", nil)
	}
	m.mu.Lock()
	invalidSender := admission.reportReplyID == "" && (m.sessions[admission.senderID] != admission.sender ||
		admission.sender.stopping || admission.sender.deleting || admission.sender.Status == StatusTerminated ||
		admission.sender.ActivationID != admission.senderActivationID)
	if admission.reportReplyID != "" {
		invalidSender = !m.reportAdmissionValidLocked(admission)
	}
	if admission.invalidated || admission.released || admission.published || admission.publishing || m.closed || invalidSender ||
		m.sessions[admission.recipientID] != admission.recipient || !m.deliveryAvailableLocked(admission.recipient) ||
		admission.recipient.ActivationID != admission.recipientActivationID {
		m.mu.Unlock()
		return messagingError("lifecycle_conflict", "message admission was canceled before intent publication", nil)
	}
	admission.publishing = true
	m.mu.Unlock()

	err := publish()

	m.mu.Lock()
	admission.publishing = false
	if err == nil {
		admission.published = true
	}
	senderUnavailable := admission.sender != nil &&
		(admission.sender.stopping || admission.sender.deleting || admission.sender.Status == StatusTerminated)
	if m.closed || senderUnavailable ||
		admission.recipient.stopping ||
		admission.recipient.deleting ||
		admission.recipient.Status == StatusTerminated {
		admission.invalidated = true
		m.releaseMessageAdmissionLocked(admission)
	}
	m.mu.Unlock()
	return err
}

Manager.RegisterConversation.src:
// RegisterConversation binds an authenticated activation's native conversation
// to its own session/card. The credential, not the tool arguments, establishes
// caller identity.
func (m *Manager) RegisterConversation(token, conversationID, name string) (RegistrationResult, error) {
	if err := validConversation(conversationID, name); err != nil {
		m.recordRegistrationFailure(token, "conversation registration input was invalid")
		return RegistrationResult{}, err
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	authority, err := m.activationAuthorityLocked(token)
	if err != nil {
		return RegistrationResult{}, err
	}
	if validateErr := m.validateReportedConversationLocked(authority, conversationID); validateErr != nil {
		return RegistrationResult{}, validateErr
	}
	binding := ConversationBinding{ID: conversationID, Name: name, Driver: authority.driver}
	return m.registerConversationLocked(authority, binding)
}

