Manager.RemoveResidual.src:
// RemoveResidual retries disk, workspace and history cleanup after a session row
// has already disappeared. The identity must come from a durable deletion manifest.
//
//nolint:gocognit // Report each independent residual cleanup effect.
func (m *Manager) RemoveResidual(ctx context.Context, id, workingDir, temporaryRoot string, useTmp bool) (RemovalResult, error) {
	if id == "" || id == "." || id == ".." || filepath.Base(id) != id {
		return RemovalResult{}, errors.New("invalid session identity")
	}
	if useTmp {
		root, err := savedTemporaryRoot(id, workingDir)
		if err != nil {
			return RemovalResult{}, err
		}
		if !filepath.IsAbs(temporaryRoot) || filepath.Clean(root) != filepath.Clean(temporaryRoot) {
			return RemovalResult{}, errors.New("temporary cleanup path does not match saved workspace")
		}
	}
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return RemovalResult{}, ErrManagerClosed
	}
	if _, exists := m.sessions[id]; exists {
		m.mu.Unlock()
		return RemovalResult{}, errors.New("session is still present")
	}
	if _, exists := m.launching[id]; exists {
		m.mu.Unlock()
		return RemovalResult{}, errors.New("session activation is in progress")
	}
	if m.launching == nil {
		m.launching = make(map[string]struct{})
	}
	m.launching[id] = struct{}{}
	m.activations.Add(1)
	m.mu.Unlock()
	defer func() { m.mu.Lock(); delete(m.launching, id); m.mu.Unlock(); m.activations.Done() }()
	if useTmp {
		if err := driver.RemoveWorkspaceTrust(ctx, workingDir); err != nil {
			return RemovalResult{}, fmt.Errorf("%w: %w", ErrTrustCleanup, err)
		}
	}
	deleteErr := deleteSession(filepath.Join(m.configDir, "sessions"), id)
	if errors.Is(deleteErr, os.ErrNotExist) {
		deleteErr = nil
	}
	var removeErr error
	if useTmp {
		removeErr = os.RemoveAll(temporaryRoot)
	}
	if deleteErr != nil || removeErr != nil {
		return RemovalResult{
			SessionRecordDeleted:      deleteErr == nil,
			TemporaryWorkspaceRemoved: useTmp && removeErr == nil,
		}, errors.Join(
			deleteErr,
			removeErr,
		)
	}
	if m.messages != nil {
		if err := m.messages.DeleteRecipient(id); err != nil {
			return RemovalResult{SessionRecordDeleted: true, TemporaryWorkspaceRemoved: useTmp}, err
		}
	}
	return RemovalResult{InMemoryRemoved: true, SessionRecordDeleted: true, TemporaryWorkspaceRemoved: useTmp}, nil
}

Manager.ReportMessage.src:
// ReportMessage accepts a report only from its authenticated recipient activation.
func (m *Manager) ReportMessage(token, requestID, messageID, kind, text string) (MessageReply, error) {
	if m.messages == nil {
		return MessageReply{}, messagingError("history_unavailable", "messaging history is unavailable", nil)
	}
	m.mu.RLock()
	if m.closed {
		m.mu.RUnlock()
		return MessageReply{}, ErrManagerClosed
	}
	authority := m.authorities[token]
	if authority == nil || authority.revoked || !authority.published {
		m.mu.RUnlock()
		return MessageReply{}, messagingError("forbidden", "activation credential is stale or unpublished", nil)
	}
	current := m.sessions[authority.sessionID]
	if current == nil || current.ActivationID != authority.activationID || current.Status == StatusTerminated {
		m.mu.RUnlock()
		return MessageReply{}, messagingError("forbidden", "activation is no longer live", nil)
	}
	sessionID, activationID := authority.sessionID, authority.activationID
	m.mu.RUnlock()
	return m.messages.RecordReply(sessionID, activationID, requestID, messageID, kind, text)
}

Manager.ReserveCardDeletion.src:
// ReserveCardDeletion serializes cleanup retries across service instances.
func (m *Manager) ReserveCardDeletion(id string) (func(), error) {
	if id == "" {
		return nil, errors.New("card ID is required")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return nil, ErrManagerClosed
	}
	if m.cardDeletionWorkers == nil {
		m.cardDeletionWorkers = make(map[string]bool)
	}
	if m.cardDeletionWorkers[id] {
		return nil, errors.New("card deletion is already running")
	}
	m.cardDeletionWorkers[id] = true
	m.activations.Add(1)
	var once sync.Once
	return func() {
		once.Do(func() { m.mu.Lock(); delete(m.cardDeletionWorkers, id); m.mu.Unlock(); m.activations.Done() })
	}, nil
}

