Manager.ReserveMessageAdmission.src:
// ReserveMessageAdmission validates and pins both activations before history
// admission, so deletion and replacement cannot race the durable intent.
func (m *Manager) ReserveMessageAdmission(token, recipientID, recipientActivationID string) (*MessageAdmission, error) {
	caller, err := m.ResolveDashboardCaller(token)
	if err != nil {
		return nil, messagingError("forbidden", "caller activation is no longer authorized", err)
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	authority := m.authorities[token]
	sender := m.sessions[caller.SessionID]
	recipient := m.sessions[recipientID]
	if m.closed || authority == nil || authority.revoked || !authority.published || sender == nil ||
		authority.sessionID != caller.SessionID || authority.activationID != caller.ActivationID ||
		sender.ActivationID != caller.ActivationID || !sender.DashboardControl || sender.Status == StatusTerminated ||
		sender.stopping || sender.activating || sender.deleting {
		return nil, messagingError("forbidden", "caller activation is no longer authorized", nil)
	}
	if recipient == nil || recipientID == caller.SessionID || recipient.Status == StatusTerminated || recipient.stopping ||
		recipient.activating || recipient.deleting {
		return nil, messagingError("lifecycle_conflict", "recipient session is not available for messages", nil)
	}
	if recipient.ActivationID != recipientActivationID || !recipient.KankuroMCPEnabled {
		return nil, messagingError("stale_activation", "recipient activation is stale or does not have Kankuro MCP selected", nil)
	}
	if recipient.starting {
		return nil, messagingError("starting", "recipient is starting; inspect the activation and retry with the same request ID", nil)
	}
	if !m.deliveryAvailableLocked(recipient) {
		return nil, messagingError("lifecycle_conflict", "recipient session is not available for messages", nil)
	}
	if recipient.Driver == nil {
		return nil, messagingError("lifecycle_conflict", "recipient driver is unavailable", nil)
	}
	admissionCtx, cancel := context.WithCancel(context.Background())
	for _, current := range []*Session{sender, recipient} {
		if current.activeSubmissions == 0 {
			current.submissionsDone = make(chan struct{})
		}
		current.activeSubmissions++
	}
	admission := &MessageAdmission{
		manager: m, sender: sender, recipient: recipient, authority: authority,
		senderID: caller.SessionID, senderActivationID: caller.ActivationID,
		recipientID: recipientID, recipientActivationID: recipientActivationID, token: token,
		ctx: admissionCtx, cancel: cancel,
	}
	if m.messageAdmissions == nil {
		m.messageAdmissions = make(map[*MessageAdmission]struct{})
	}
	m.messageAdmissions[admission] = struct{}{}
	return admission, nil
}

Manager.ReserveReportNotification.src:
// ReserveReportNotification reserves only the exact destination in a retained report.
func (m *Manager) ReserveReportNotification(messageID, replyID string) (*MessageAdmission, error) {
	if m.messages == nil {
		return nil, messagingError("history_unavailable", "messaging history is unavailable", nil)
	}
	notification, ok := m.messages.notification(messageID, replyID)
	if !ok {
		return nil, messagingError("history_unavailable", "report history is unavailable", nil)
	}
	original := notification.Message
	m.mu.Lock()
	defer m.mu.Unlock()
	target := m.sessions[original.SenderSessionID]
	dashboardAvailable, dashboardErr := m.reportDashboardAvailableLocked(original.DashboardID)
	if dashboardErr != nil {
		return nil, messagingError("storage_unavailable", "dashboard state is unavailable", dashboardErr)
	}
	if target == nil || target.DashboardID != original.DashboardID || m.dashboardDeletionWorkers[original.DashboardID] ||
		!dashboardAvailable ||
		target.ActivationID != original.SenderActivationID ||
		target.Status == StatusTerminated ||
		target.stopping ||
		target.deleting ||
		target.activating ||
		!target.KankuroMCPEnabled {
		return nil, messagingError("stale_activation", "original sender activation is unavailable", nil)
	}
	if target.starting {
		return nil, messagingError("starting", "original sender is starting", nil)
	}
	if !m.deliveryAvailableLocked(target) {
		return nil, messagingError("stale_activation", "original sender activation is unavailable", nil)
	}
	ctx, cancel := context.WithCancel(context.Background())
	if target.activeSubmissions == 0 {
		target.submissionsDone = make(chan struct{})
	}
	target.activeSubmissions++
	admission := &MessageAdmission{manager: m, recipient: target, senderID: notification.Reply.SenderSessionID,
		senderActivationID: notification.Reply.SenderActivationID, recipientID: target.ID,
		recipientActivationID: target.ActivationID, ctx: ctx, cancel: cancel,
		reportMessageID: messageID, reportReplyID: replyID}
	if m.messageAdmissions == nil {
		m.messageAdmissions = make(map[*MessageAdmission]struct{})
	}
	m.messageAdmissions[admission] = struct{}{}
	return admission, nil
}

Manager.ResolveDashboardCaller.src:
// ResolveDashboardCaller validates a current published activation and returns
// only its safe identity. Lifecycle discovery/control requires both an active
// Kankuro credential and the permission deployed by that activation.
func (m *Manager) ResolveDashboardCaller(token string) (CallerIdentity, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if m.closed {
		return CallerIdentity{}, ErrManagerClosed
	}
	authority := m.authorities[token]
	if authority == nil || authority.revoked || !authority.published {
		return CallerIdentity{}, errors.New("activation credential is stale or unpublished")
	}
	s := m.sessions[authority.sessionID]
	if s == nil || s.ActivationID != authority.activationID || s.Status == StatusTerminated {
		return CallerIdentity{}, errors.New("activation is no longer live")
	}
	if !s.DashboardControl {
		return CallerIdentity{}, errors.New("dashboard control is not enabled for this activation")
	}
	return CallerIdentity{
		SessionID:        authority.sessionID,
		DashboardID:      s.DashboardID,
		ActivationID:     authority.activationID,
		CardID:           authority.cardID,
		Driver:           authority.driver,
		DashboardControl: true,
	}, nil
}

