Manager.WaitCardReferences.src:
// WaitCardReferences waits without holding the manager lock until all pending
// references are released or the caller cancels its wait.
func (m *Manager) WaitCardReferences(ctx context.Context, cardID string) error {
	for {
		m.mu.Lock()
		if m.pendingCardRefs[cardID] == 0 {
			m.mu.Unlock()
			return nil
		}
		if m.cardRefsChanged == nil {
			m.cardRefsChanged = make(chan struct{})
		}
		changed := m.cardRefsChanged
		m.mu.Unlock()
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-changed:
		}
	}
}

Manager.WaitDashboardAdmissions.src:
// WaitDashboardAdmissions drains the same reservation set without holding locks.
func (m *Manager) WaitDashboardAdmissions(ctx context.Context, dashboardID string, ownedCards map[string]bool) error {
	for {
		m.mu.Lock()
		pending := false
		for cardID, entries := range m.pendingCardDetails {
			for _, reference := range entries {
				if reference.DashboardID == dashboardID || ownedCards[cardID] {
					pending = true
					break
				}
			}
			if pending {
				break
			}
		}
		if !pending {
			m.mu.Unlock()
			return nil
		}
		if m.cardRefsChanged == nil {
			m.cardRefsChanged = make(chan struct{})
		}
		changed := m.cardRefsChanged
		m.mu.Unlock()
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-changed:
		}
	}
}

Manager.WithAdmissionSnapshot.src:
// WithAdmissionSnapshot serializes short validation and durable intent writes
// with all card reservations. The callback must not call the manager or wait.
func (m *Manager) WithAdmissionSnapshot(check func(AdmissionSnapshot) error) error {
	if check == nil {
		return errors.New("admission check is required")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return ErrManagerClosed
	}
	snapshot := AdmissionSnapshot{
		Sessions:    m.listLocked(),
		CardImpacts: make(map[string]CardReferenceImpact),
		Revision:    m.cardReferenceRevision,
	}
	sort.Slice(snapshot.Sessions, func(i, j int) bool { return snapshot.Sessions[i].ID < snapshot.Sessions[j].ID })
	ids := make(map[string]bool)
	for id := range m.pendingCardRefs {
		ids[id] = true
	}
	for _, item := range m.sessions {
		ids[item.CardID] = true
		for id := range item.Conversations {
			ids[id] = true
		}
	}
	for id := range ids {
		snapshot.CardImpacts[id] = m.cardReferencesLocked(id)
	}
	return check(snapshot)
}

Manager.WithCardReferencesAndSnapshot.src:
// WithCardReferencesAndSnapshot supplies the complete session inventory under
// the admission lock for fail-closed membership validation.
func (m *Manager) WithCardReferencesAndSnapshot(cardID string, check func(CardReferenceImpact, []Snapshot) error) error {
	if check == nil {
		return errors.New("card reference check is required")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return ErrManagerClosed
	}
	return check(m.cardReferencesLocked(cardID), m.listLocked())
}

Manager.activationAuthorityLocked.src:
func (m *Manager) activationAuthorityLocked(token string) (*activationAuthority, error) {
	if m.closed {
		return nil, ErrManagerClosed
	}
	authority := m.authorities[token]
	if authority == nil || authority.revoked {
		return nil, errors.New("activation credential is stale")
	}
	return authority, nil
}

Manager.attachChecked.src:
func (m *Manager) attachChecked(id, processID string, check func([]Snapshot) error) (*AttachHandle, error) {
	if check == nil {
		return nil, errors.New("attach scope check is required")
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return nil, ErrManagerClosed
	}
	if err := check(m.listLocked()); err != nil {
		return nil, err
	}
	s, ok := m.sessions[id]
	if !ok {
		return nil, fmt.Errorf("session not found: %s", id)
	}
	if processID != "" && s.ProcessActivationID != processID {
		return nil, errors.New("session process changed before attachment")
	}
	if s.Status == StatusTerminated {
		return nil, fmt.Errorf("session terminated: %s", id)
	}
	ch := make(chan []byte, outputChanSize)
	if s.outputComplete {
		close(ch)
	} else {
		s.Subscribers[ch] = struct{}{}
	}
	subscribers := s.Subscribers
	header := s.PendingAttachHeader
	s.PendingAttachHeader = nil
	generation := s.generation
	d := s.Driver
	terminal := s.PTY
	return &AttachHandle{
		Input:      driverInputWriter{driver: s.Driver},
		PTY:        s.PTY,
		Output:     ch,
		Scrollback: bytes.Clone(s.Scrollback),
		Header:     header,
		Done:       s.Done,
		Close: func() {
			m.removeSubscriber(subscribers, ch)
		},
		WriteChecked: func(data []byte) (int, error) {
			m.mu.RLock()
			current, exists := m.sessions[id]
			active := exists && current.generation == generation && current.Status != StatusTerminated
			m.mu.RUnlock()
			if !active {
				return 0, errors.New("attachment process is no longer active")
			}
			return d.SendInputBytes(data)
		},
		ResizeChecked: func(rows, columns int) error {
			if rows <= 0 || columns <= 0 || rows > 65535 || columns > 65535 {
				return errors.New("invalid terminal size")
			}
			m.mu.RLock()
			defer m.mu.RUnlock()
			current, exists := m.sessions[id]
			if !exists || current.generation != generation || current.Status == StatusTerminated || terminal == nil {
				return errors.New("attachment process is no longer active")
			}
			return pty.Setsize(terminal, &pty.Winsize{Rows: uint16(rows), Cols: uint16(columns)})
		},
	}, nil
}

Manager.beginMessageSubmission.src:
//nolint:gocyclo,cyclop // Both authorization paths revalidate their lifecycle reservations at the write boundary.
func (m *Manager) beginMessageSubmission(admission *MessageAdmission, token, recipientID, activationID string) (driver.AgentDriver, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if admission == nil || admission.manager != m || admission.invalidated || admission.released ||
		!admission.published || admission.started ||
		admission.token != token || admission.recipientID != recipientID || admission.recipientActivationID != activationID {
		return nil, false
	}
	sender, recipient := admission.sender, admission.recipient
	if admission.reportReplyID != "" {
		if !m.reportAdmissionValidLocked(admission) || recipient == nil ||
			m.closed || m.sessions[recipientID] != recipient || !m.deliveryAvailableLocked(recipient) || recipient.ActivationID != activationID {
			return nil, false
		}
		admission.started = true
		return recipient.Driver, recipient.Driver != nil
	}
	if m.closed || sender == nil || recipient == nil || sender.stopping || sender.deleting || recipient.stopping ||
		recipient.deleting || sender.Status == StatusTerminated || recipient.Status == StatusTerminated ||
		m.sessions[sender.ID] != sender || m.sessions[recipientID] != recipient || !m.deliveryAvailableLocked(recipient) ||
		sender.ActivationID != admission.senderActivationID || recipient.ActivationID != activationID || !sender.DashboardControl {
		return nil, false
	}
	authority := m.authorities[token]
	if authority != admission.authority || authority == nil || authority.revoked || !authority.published {
		return nil, false
	}
	admission.started = true
	return recipient.Driver, recipient.Driver != nil
}

Manager.bindPendingWorkspace.sig:
func (m *Manager) bindPendingWorkspace(
	ctx context.Context,
	cardID, sessionID, workspace string,
	useTmp bool,
	check func([]Snapshot) error,
) error

Manager.bindPendingWorkspace.src:
// bindPendingWorkspace records the exact path before a scoped new launch can
// create it. The availability check shares the deletion admission lock.
func (m *Manager) bindPendingWorkspace(
	ctx context.Context,
	cardID, sessionID, workspace string,
	useTmp bool,
	check func([]Snapshot) error,
) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return ErrManagerClosed
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := check(m.listLocked()); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	for reservation, pending := range m.pendingCardDetails[cardID] {
		if pending.SessionID != sessionID {
			continue
		}
		if useTmp {
			root, err := filepath.Abs(filepath.Join(m.tmpRoot(), sessionID))
			if err != nil {
				return err
			}
			pending.TemporaryRoot = root
			pending.WorkingDir = filepath.Join(root, filepath.Base(workspace))
		}
		m.pendingCardDetails[cardID][reservation] = pending
		m.cardReferenceRevision++
		m.notifyCardReferencesLocked()
		return nil
	}
	return errors.New("pending card activation reservation not found")
}

Manager.cancelPendingMessageAdmissionsLo.src:
// cancelPendingMessageAdmissionsLocked invalidates reservations that have not
// reached PTY submission, so lifecycle workers never wait for queued work.
func (m *Manager) cancelPendingMessageAdmissionsLocked(session *Session) {
	for admission := range m.messageAdmissions {
		if admission.started || admission.publishing || (admission.sender != session && admission.recipient != session) {
			continue
		}
		admission.invalidated = true
		m.releaseMessageAdmissionLocked(admission)
	}
}

Manager.cancelStartupLocked.src:
func (m *Manager) cancelStartupLocked(s *Session) {
	if s.startupCancel != nil {
		close(s.startupCancel)
		s.startupCancel = nil
	}
	s.starting = false
}

Manager.cardReferencesLocked.src:
func (m *Manager) cardReferencesLocked(cardID string) CardReferenceImpact {
	impact := CardReferenceImpact{PendingByDashboard: maps.Clone(m.pendingCardRefsByDashboard[cardID]), Revision: m.cardReferenceRevision}
	for _, pending := range m.pendingCardDetails[cardID] {
		impact.Pending = append(impact.Pending, pending)
	}
	sort.Slice(impact.Pending, func(i, j int) bool {
		if impact.Pending[i].DashboardID == impact.Pending[j].DashboardID {
			return impact.Pending[i].SessionID < impact.Pending[j].SessionID
		}
		return impact.Pending[i].DashboardID < impact.Pending[j].DashboardID
	})
	for _, current := range m.sessions {
		_, binding := current.Conversations[cardID]
		if current.CardID == cardID || binding {
			impact.Sessions = append(impact.Sessions, CardSessionReference{
				SessionID: current.ID, DashboardID: current.DashboardID, Current: current.CardID == cardID, Binding: binding,
			})
		}
	}
	sort.Slice(impact.Sessions, func(i, j int) bool { return impact.Sessions[i].SessionID < impact.Sessions[j].SessionID })
	return impact
}

Manager.cleanupNewTemporaryWorkspace.src:
func (m *Manager) cleanupNewTemporaryWorkspace(sid string, card config.IDCard, isNew bool, cause error) error {
	if !isNew || !card.UseTmpWorkspace {
		return cause
	}
	return errors.Join(cause, os.RemoveAll(filepath.Join(m.tmpRoot(), sid)))
}

Manager.closeSubscribersLocked.src:
func (m *Manager) closeSubscribersLocked(sessionID string) {
	s, ok := m.sessions[sessionID]
	if !ok {
		return
	}
	for ch := range s.Subscribers {
		close(ch)
		delete(s.Subscribers, ch)
	}
}

Manager.copyWorkspace.src:
func (m *Manager) copyWorkspace(ctx context.Context, source, destination string) error {
	if m.workspaceCopier != nil {
		if err := m.workspaceCopier(ctx, source, destination); err != nil {
			return fmt.Errorf("copy workspace: %w", err)
		}
		return nil
	}
	cmd := exec.CommandContext(ctx, "cp", "-r", source, destination)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("copy workspace: %s: %w", string(output), err)
	}
	return nil
}

Manager.deliveryAvailableLocked.src:
func (m *Manager) deliveryAvailableLocked(s *Session) bool {
	if m.closed || s == nil || s.starting || s.activating || s.stopping || s.deleting || s.Status == StatusTerminated || s.Driver == nil ||
		s.Done == nil ||
		s.ActivationID == "" ||
		!s.KankuroMCPEnabled {
		return false
	}
	authority := m.authorities[s.ActivationToken]
	if authority == nil || authority.revoked || !authority.published || authority.sessionID != s.ID ||
		authority.activationID != s.ActivationID {
		return false
	}
	select {
	case <-s.Done:
		return false
	default:
		return true
	}
}

Manager.killDetailed.src:
//nolint:gocognit,nestif,funlen // Stop serialization, prompt drain, and durable teardown are one lifecycle transition.
func (m *Manager) killDetailed(id string, duringShutdown bool, check func([]Snapshot) error) (StopResult, error) {
	m.mu.Lock()
	if m.closed && !duringShutdown {
		m.mu.Unlock()
		return StopResult{}, ErrManagerClosed
	}
	if check != nil {
		if err := check(m.listLocked()); err != nil {
			m.mu.Unlock()
			return StopResult{}, err
		}
	}
	s, ok := m.sessions[id]
	var d driver.AgentDriver
	var gen uint64
	var submissionsDone chan struct{}
	var wasStarting bool
	var startupDeadline time.Time
	if ok {
		if s.activating || s.stopping || s.deleting {
			m.mu.Unlock()
			return StopResult{}, fmt.Errorf("%w: %s", ErrLifecycleConflict, id)
		}
		if s.Status == StatusTerminated {
			if s.activeSubmissions > 0 {
				done := s.submissionsDone
				m.mu.Unlock()
				<-done
				return m.killDetailed(id, duringShutdown, check)
			}
			persistErr := m.persistSessionLockedErr(s)
			m.mu.Unlock()
			return StopResult{ProcessTerminated: true, SessionRecordPersisted: persistErr == nil}, persistErr
		}
		s.stopping = true
		wasStarting, startupDeadline = s.starting, s.startupDeadline
		m.cancelStartupLocked(s)
		m.cancelPendingMessageAdmissionsLocked(s)
		if s.activeSubmissions > 0 {
			submissionsDone = s.submissionsDone
		}
		m.stops.Add(1)
		d, gen = s.Driver, s.generation
	}
	m.mu.Unlock()
	if !ok {
		return StopResult{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	defer m.stops.Done()
	if submissionsDone != nil {
		<-submissionsDone
	}

	// Called with no lock held on purpose: it can block on process teardown,
	// and watch needs m.mu in the meantime.
	var killErr error
	if d != nil {
		killErr = d.Kill()
	}
	processTerminated := d == nil || d.GetStatus() == StatusTerminated

	m.mu.Lock()
	defer m.mu.Unlock()
	// Only mark terminated if this is still the same activation of the same
	// session. The lock was released above, so a Remove in that window must
	// not have its deleted record re-created by our persist, and a Relaunch
	// must not have its new, running activation marked dead.
	if cur, still := m.sessions[id]; !still || cur != s || s.generation != gen {
		return StopResult{ProcessTerminated: processTerminated}, killErr
	}
	s.stopping = false
	if !processTerminated {
		if wasStarting && !m.closed {
			m.startStartupLocked(s, startupDeadline)
		}
		return StopResult{}, errors.Join(killErr, errors.New("session process remains active"))
	}
	s.Status = StatusTerminated
	s.Pinged = false
	if s.Registration == RegistrationPending {
		s.Registration = RegistrationUnconfirmed
	}
	m.revokeSessionActivationLocked(s)
	persistErr := m.persistSessionLockedErr(s)
	if m.messages != nil {
		m.messages.Wake()
	}
	return StopResult{ProcessTerminated: true, SessionRecordPersisted: persistErr == nil}, errors.Join(killErr, persistErr)
}

Manager.launchWithIDContext.src:
//nolint:nonamedreturns // The named result retains publication evidence alongside deferred cleanup errors.
func (m *Manager) launchWithIDContext(
	ctx context.Context,
	sid, dashboardID string,
	card config.IDCard,
	skills []config.Skill,
	personas []config.Persona,
	mcps []config.MCPServer,
	publicationCheck func([]Snapshot) error,
	name ...*string,
) (result ActivationResult) {
	result.SessionID = sid
	if _, err := uuid.Parse(sid); err != nil {
		result.Err = fmt.Errorf("invalid preallocated session ID: %w", err)
		return result
	}
	// The closed check and the Add share one critical section, the same
	// ordering argument as startWatchLocked: Shutdown sets closed under m.mu
	// before it Waits, so no Add can race a Wait that started at zero.
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		result.Err = ErrManagerClosed
		return result
	}
	if _, exists := m.sessions[sid]; exists {
		m.mu.Unlock()
		result.Err = fmt.Errorf("session already exists: %s", sid)
		return result
	}
	if _, exists := m.launching[sid]; exists {
		m.mu.Unlock()
		result.Err = fmt.Errorf("session launch already reserved: %s", sid)
		return result
	}
	m.launching[sid] = struct{}{}
	m.activations.Add(1)
	m.mu.Unlock()
	defer func() {
		m.mu.Lock()
		delete(m.launching, sid)
		m.mu.Unlock()
		m.activations.Done()
	}()
	return m.startSession(ctx, sid, dashboardID, card, skills, personas, mcps, true, "", "", nil, "", publicationCheck, name)
}

Manager.listLocked.src:
func (m *Manager) listLocked() []Snapshot {
	out := make([]Snapshot, 0, len(m.sessions))
	for _, s := range m.sessions {
		out = append(out, m.snapshotLocked(s))
	}
	return out
}

