	if m.cardRefsChanged != nil {
		close(m.cardRefsChanged)
	}
	m.cardRefsChanged = make(chan struct{})
}

Manager.persistSessionLocked.src:
// persistSessionLocked logs background persistence failures through the injected logger.
// This keeps diagnostics off stderr while the TUI owns the terminal.
func (m *Manager) persistSessionLocked(s *Session) {
	if err := m.persistSessionLockedErr(s); err != nil {
		m.logger.Warn("session persist failed", "session_id", s.ID, "error", err)
	}
}

Manager.persistSessionLockedErr.src:
// persistSessionLockedErr writes s to disk and returns any error. Callers
// must hold m.mu.
func (m *Manager) persistSessionLockedErr(s *Session) error {
	sessionsDir := filepath.Join(m.configDir, "sessions")
	if err := saveSession(sessionsDir, s.data()); err != nil {
		return err
	}
	if s.Registration == RegistrationRegistered {
		s.RegistrationPersistence = RegistrationSaved
		s.RegistrationErr = ""
	}
	return nil
}

Manager.prepareActivationMCPConfig.src:
func (m *Manager) prepareActivationMCPConfig(
	sessionID string,
	dashboardID string,
	card config.IDCard,
	d driver.AgentDriver,
	mcps []config.MCPServer,
	expectedID string,
	workingDir string,
	preserveDeployed bool,
) (string, error) {
	resolvedMCPs := append([]config.MCPServer(nil), mcps...)
	hasKankuro := false
	for i := range resolvedMCPs {
		if resolvedMCPs[i].ID != config.BuiltinMCPKankuro {
			continue
		}
		hasKankuro = true
	}
	token := ""
	activationID := ""
	if hasKankuro {
		var err error
		token, err = newActivationToken()
		if err != nil {
			return "", err
		}
		activationID = uuid.NewString()
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return "", ErrManagerClosed
	}
	if existing := m.sessions[sessionID]; existing != nil {
		dashboardID = existing.DashboardID
	}
	if hasKankuro {
		if m.mcpEndpoint == "" {
			return "", errors.New("kankuro MCP endpoint is not configured")
		}
		for i := range resolvedMCPs {
			if resolvedMCPs[i].ID != config.BuiltinMCPKankuro {
				continue
			}
			resolvedMCPs[i].URL = m.mcpEndpoint
			headers := make(map[string]string, len(resolvedMCPs[i].Headers)+1)
			maps.Copy(headers, resolvedMCPs[i].Headers)
			headers["Authorization"] = "Bearer " + token
			resolvedMCPs[i].Headers = headers
		}
	}
	if err := syncActivationMCPConfig(d, resolvedMCPs, workingDir, preserveDeployed); err != nil {
		return "", fmt.Errorf("select MCPs: %w", err)
	}

	if hasKankuro {
		m.authorities[token] = &activationAuthority{
			sessionID:    sessionID,
			dashboardID:  dashboardID,
			activationID: activationID,
			cardID:       card.ID,
			driver:       card.Driver,
			expectedID:   expectedID,
			configPath:   driver.MCPConfigPath(workingDir),
		}
	}
	return token, nil
}

Manager.prepareNewSessionFiles.sig:
func (m *Manager) prepareNewSessionFiles(
	ctx context.Context,
	d driver.AgentDriver, card config.IDCard, skills []config.Skill,
	personas []config.Persona, mcps []config.MCPServer, workingDir string,
) (bool, func() error, error)

Manager.prepareNewSessionFiles.src:
func (m *Manager) prepareNewSessionFiles(
	ctx context.Context,
	d driver.AgentDriver, card config.IDCard, skills []config.Skill,
	personas []config.Persona, mcps []config.MCPServer, workingDir string,
) (bool, func() error, error) {
	if err := m.prepareSubWorkspaces(ctx, card, workingDir); err != nil {
		return false, nil, err
	}
	instructionPath := filepath.Join(workingDir, d.GetInstructionFileName())
	previousFile, err := snapshotInstructionFile(instructionPath)
	if err != nil {
		return false, nil, err
	}
	rollback := func() error { return previousFile.restore(instructionPath) }
	mode := driver.InstructionPreserveWhenEmpty
	if card.UseTmpWorkspace {
		mode = driver.InstructionAppend
	}
	_, managed, err := m.syncDriverFiles(d, card, skills, personas, mcps, workingDir, card.UseTmpWorkspace, mode)
	if err != nil {
		return false, nil, errors.Join(err, rollback())
	}
	return managed, rollback, nil
}

Manager.prepareSubWorkspaces.src:
// prepareSubWorkspaces serializes manifest decisions and copy publication for a working directory.
func (m *Manager) prepareSubWorkspaces(ctx context.Context, card config.IDCard, workingDir string) error {
	if len(card.SubWorkspaceIDs) == 0 {
		return nil
	}
	select {
	case m.subWorkspaceGate <- struct{}{}:
		defer func() { <-m.subWorkspaceGate }()
	case <-ctx.Done():
		return ctx.Err()
	}

	canonicalDir, canonicalErr := canonicalDirectory(workingDir)
	if canonicalErr != nil {
		return fmt.Errorf("resolve session workspace: %w", canonicalErr)
	}
	sources, resolveErr := resolveSubWorkspaceSources(m.repo, card.SubWorkspaceIDs, canonicalDir)
	if resolveErr != nil {
		return resolveErr
	}
	manifestPath := filepath.Join(canonicalDir, ".kankuro", "sub-workspaces.json")
	manifest, manifestErr := loadSubWorkspaceManifest(manifestPath)
	if manifestErr != nil {
		return manifestErr
	}
	tmpDir := filepath.Join(canonicalDir, "tmp")
	if prepareErr := prepareSubWorkspaceDirectory(tmpDir); prepareErr != nil {
		return prepareErr
	}

	tx := &subWorkspaceTransaction{}
	updated := copySubWorkspaceManifest(manifest, len(sources))
	for _, source := range sources {
		shouldCopy, ownershipErr := shouldCopySubWorkspace(source, tmpDir, manifest)
		if ownershipErr != nil {
			return tx.rollback(ownershipErr)
		}
		if !shouldCopy {
			continue
		}
		if copyErr := copyAndPublishSubWorkspace(ctx, source, tmpDir, tx); copyErr != nil {
			return tx.rollback(copyErr)
		}
		updated.Copies[source.name] = subWorkspaceCopy{WorkspaceID: source.id, SourcePath: source.path}
	}
	if persistErr := persistSubWorkspaceManifest(manifestPath, updated); persistErr != nil {
		return tx.rollback(persistErr)
	}
	return nil
}

Manager.prepareWorkspace.src:
func (m *Manager) prepareWorkspace(
	ctx context.Context,
	sid string,
	card config.IDCard,
	wd string,
	isNew bool,
) (string, error) {
	if !card.UseTmpWorkspace {
		return wd, nil
	}

	sessionRoot := filepath.Join(m.tmpRoot(), sid)
	targetDir := filepath.Join(sessionRoot, filepath.Base(wd))

	if isNew {
		if err := os.MkdirAll(sessionRoot, 0o700); err != nil {
			return "", fmt.Errorf("create tmp session dir: %w", err)
		}
		if err := m.copyWorkspace(ctx, wd, targetDir); err != nil {
			return "", err
		}
		return targetDir, nil
	}
	if _, err := os.Stat(targetDir); err != nil {
		return "", fmt.Errorf("tmp workspace missing: %w", err)
	}
	return targetDir, nil
}

Manager.publishActivationLocked.src:
func (m *Manager) publishActivationLocked(token string, s *Session) {
	if token == "" {
		s.Registration = RegistrationUnavailable
		s.RegistrationPersistence = RegistrationNotAttempted
		s.RegistrationErr = ""
		s.ActivationID = ""
		s.ActivationToken = ""
		s.ExpectedConversationID = ""
		return
	}
	authority := m.authorities[token]
	if authority == nil || authority.revoked {
		s.Registration = RegistrationFailed
		return
	}
	authority.published = true
	s.ActivationID = authority.activationID
	s.ActivationToken = token
	s.ExpectedConversationID = authority.expectedID
	s.Registration = RegistrationPending
	s.RegistrationPersistence = RegistrationNotAttempted
	s.RegistrationAt = time.Now().UTC()
	if authority.failure != "" {
		s.Registration = RegistrationFailed
		s.RegistrationErr = authority.failure
	}
	if authority.staged != nil {
		addConversationBinding(s, authority.cardID, *authority.staged)
		m.cardReferenceRevision++
		s.ExpectedConversationID = authority.staged.ID
		s.Registration = RegistrationRegistered
		s.RegistrationPersistence = RegistrationNotAttempted
		if authority.failure != "" {
			s.RegistrationErr = authority.failure
		}
	}
}

Manager.recordRegistrationFailure.src:
func (m *Manager) recordRegistrationFailure(token, message string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return
	}
	authority := m.authorities[token]
	if authority == nil || authority.revoked || authority.acceptedID != "" {
		return
	}
	authority.failure = message
	if authority.published {
		if s := m.sessions[authority.sessionID]; s != nil && s.ActivationID == authority.activationID {
			s.Registration = RegistrationFailed
			s.RegistrationErr = message
		}
	}
}

Manager.registerConversationLocked.src:
func (m *Manager) registerConversationLocked(authority *activationAuthority, binding ConversationBinding) (RegistrationResult, error) {
	if authority.acceptedID != "" && authority.acceptedID != binding.ID {
		m.setRegistrationFailureLocked(authority, "activation rejected a conflicting conversation identity")
		return RegistrationResult{}, errors.New("activation already reported a different conversation")
	}
	authority.acceptedID = binding.ID
	authority.failure = ""
	if !authority.published {
		authority.staged = &binding
		return RegistrationResult{
			DashboardID: authority.dashboardID,
			Status:      "pending_activation",
			Persistence: RegistrationNotAttempted,
		}, nil
	}
	s := m.sessions[authority.sessionID]
	if s == nil || s.ActivationID != authority.activationID || s.Status == StatusTerminated {
		return RegistrationResult{}, errors.New("activation is no longer live")
	}
	addConversationBinding(s, authority.cardID, binding)
	m.cardReferenceRevision++
	s.ExpectedConversationID = binding.ID
	s.Registration = RegistrationRegistered
	s.RegistrationPersistence = RegistrationNotAttempted
	s.RegistrationErr = ""
	if err := m.persistSessionLockedErr(s); err != nil {
		s.RegistrationPersistence = RegistrationUnsaved
		s.RegistrationErr = conversationPersistenceWarning
		// A live activation with unsaved metadata is a successful registration outcome.
		//nolint:nilerr // The transport returns durability in the structured result.
		return RegistrationResult{
			DashboardID: s.DashboardID,
			Status:      RegistrationRegistered,
			Persistence: RegistrationUnsaved,
			Warning:     s.RegistrationErr,
		}, nil
	}
	return RegistrationResult{DashboardID: s.DashboardID, Status: RegistrationRegistered, Persistence: RegistrationSaved}, nil
}

Manager.relaunchWithChoiceContext.src:
//nolint:nonamedreturns // The named result retains publication evidence alongside deferred cleanup errors.
func (m *Manager) relaunchWithChoiceContext(
	ctx context.Context,
	id string,
	card config.IDCard,
	choice ConversationChoice,
	publicationCheck func([]Snapshot) error,
) (result ActivationResult) {
	result.SessionID = id
	snap, conversationID, err := m.reserveForActivation(id, card.ID, card.Driver, "session is already running", choice)
	if err != nil {
		result.Err = err
		return result
	}
	defer m.activations.Done()
	card.UseTmpWorkspace = snap.UseTmpWorkspace
	card.DashboardControl = snap.DashboardControl
	var mcps []config.MCPServer
	if snap.KankuroMCPEnabled {
		mcps = config.BuiltinMCPs()
	}
	result = m.startSession(
		ctx,
		id,
		"",
		card,
		nil,
		nil,
		mcps,
		false,
		snap.WorkingDir,
		snap.OriginalDir,
		snap.InstructionOwnership,
		conversationID,
		publicationCheck,
		nil,
	)
	// Release every unpublished reservation, including uncertain teardown.
	if result.Effect != ActivationPublished {
		m.releaseActivation(id)
	}
	return result
}

Manager.releaseActivation.src:
// releaseActivation clears the reservation taken by reserveForActivation after
// an activation that did not happen.
func (m *Manager) releaseActivation(id string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if s, ok := m.sessions[id]; ok {
		s.activating = false
		s.Registration = RegistrationFailed
		s.RegistrationErr = "activation failed before conversation registration"
	}
}

Manager.releaseMessageAdmissionLocked.src:
func (m *Manager) releaseMessageAdmissionLocked(admission *MessageAdmission) {
	if admission.released {
		return
	}
	admission.released = true
	delete(m.messageAdmissions, admission)
	if admission.cancel != nil {
		admission.cancel()
	}
	for _, current := range []*Session{admission.sender, admission.recipient} {
		if current == nil || current.activeSubmissions == 0 {
			continue
		}
		current.activeSubmissions--
		if current.activeSubmissions == 0 {
			close(current.submissionsDone)
			current.submissionsDone = nil
		}
	}
}

Manager.removeDetailedChecked.src:
//nolint:funlen,gocognit // Reservation, retryable cleanup, and deletion form one transaction.
func (m *Manager) removeDetailedChecked(id string, check func([]Snapshot) error) (RemovalResult, error) {
	m.mu.Lock()
	if check != nil {
		if m.closed {
			m.mu.Unlock()
			return RemovalResult{}, ErrManagerClosed
		}
		if err := check(m.listLocked()); err != nil {
			m.mu.Unlock()
			return RemovalResult{}, err
		}
	}
	s, ok := m.sessions[id]
	if !ok {
		m.mu.Unlock()
		return RemovalResult{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	if s.Status != StatusTerminated {
		m.mu.Unlock()
		return RemovalResult{}, fmt.Errorf("%w: session still running or waiting", ErrLifecycleConflict)
	}
	// A relaunch/switch in its unlocked phase is still Terminated; removing
	// now would delete the tmp workspace it is syncing into.
	if s.activating {
		m.mu.Unlock()
		return RemovalResult{}, fmt.Errorf("%w: session is activating", ErrLifecycleConflict)
	}
	if s.stopping || s.deleting {
		m.mu.Unlock()
		return RemovalResult{}, fmt.Errorf("%w: %s", ErrLifecycleConflict, id)
	}
	if s.activeSubmissions > 0 {
		m.mu.Unlock()
		return RemovalResult{}, fmt.Errorf("%w: message submission is in progress", ErrLifecycleConflict)
	}
	s.deleting = true
	m.cancelPendingMessageAdmissionsLocked(s)
	m.revokeSessionActivationLocked(s)
	// The output tracker owns closure for an activation so it can publish its
	// remaining queued output even if the session row is removed first.
	if s.Output == nil {
		m.closeSubscribersLocked(id)
	}
	tmp := s.UseTmpWorkspace
	workingDir := s.WorkingDir
	m.mu.Unlock()

	var temporaryRoot string
	if tmp {
		var pathErr error
		temporaryRoot, pathErr = savedTemporaryRoot(id, workingDir)
		if pathErr != nil {
			m.mu.Lock()
			s.deleting = false
			m.mu.Unlock()
			return RemovalResult{}, pathErr
		}
		if trustErr := driver.RemoveWorkspaceTrust(context.Background(), workingDir); trustErr != nil {
			m.mu.Lock()
			s.deleting = false
			m.mu.Unlock()
			return RemovalResult{}, fmt.Errorf(
				"%w: cleanup may be incomplete; session retained: fix the CLI configuration and retry deletion: %w",
				ErrTrustCleanup,
				trustErr,
			)
		}
	}

	sessionsDir := filepath.Join(m.configDir, "sessions")
	deleteErr := deleteSession(sessionsDir, id)
	// A file that is already gone is not a failure: the caller asked for it
	// not to exist, and it doesn't. Surfacing this as an error (as Plan 2
	// originally did) produced a red banner for a delete that did exactly
	// what was asked - the same shape as os.ErrProcessDone in Kill.
	if errors.Is(deleteErr, os.ErrNotExist) {
		deleteErr = nil
	}

	var rmErr error
	if tmp {
		rmErr = os.RemoveAll(temporaryRoot)
	}

	// Always drop the in-memory session so the UI does not wedge on a row it
	// cannot delete, even if the on-disk cleanup below failed.
	m.mu.Lock()
	if m.sessions[id] == s {
		delete(m.sessions, id)
		m.cardReferenceRevision++
	}
	m.mu.Unlock()
	if m.messages != nil {
		m.messages.Wake()
	}

	var errs []error
	if deleteErr != nil {
		errs = append(errs, fmt.Errorf("delete session file: %w", deleteErr))
	}
	if rmErr != nil {
		errs = append(errs, fmt.Errorf("remove tmp workspace: %w", rmErr))
	}
	if len(errs) == 0 && m.messages != nil {
		if messageErr := m.messages.DeleteRecipient(id); messageErr != nil {
			errs = append(errs, fmt.Errorf("delete recipient message history: %w", messageErr))
		}
	}
	return RemovalResult{InMemoryRemoved: true, SessionRecordDeleted: deleteErr == nil,
		TemporaryWorkspaceRemoved: tmp && rmErr == nil}, errors.Join(errs...)
}

Manager.removeSubscriber.src:
func (m *Manager) removeSubscriber(subscribers map[chan []byte]struct{}, ch chan []byte) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, okSub := subscribers[ch]; okSub {
		delete(subscribers, ch)
		close(ch)
	}
}

Manager.reportAdmissionValidLocked.src:
func (m *Manager) reportAdmissionValidLocked(admission *MessageAdmission) bool {
	if admission.recipient == nil {
		return false
	}
	report, found := m.messages.notification(admission.reportMessageID, admission.reportReplyID)
	if !found || report.Message.SenderSessionID != admission.recipientID ||
		report.Message.SenderActivationID != admission.recipientActivationID ||
		admission.recipient.ActivationID != admission.recipientActivationID ||
		admission.recipient.DashboardID != report.Message.DashboardID || m.dashboardDeletionWorkers[report.Message.DashboardID] {
		return false
	}
	available, err := m.reportDashboardAvailableLocked(report.Message.DashboardID)
	return err == nil && available
}

Manager.reportDashboardAvailableLocked.src:
func (m *Manager) reportDashboardAvailableLocked(dashboardID string) (bool, error) {
	repo, ok := m.repo.(interface {
		ListDashboardDeletions() ([]config.DashboardDeletion, error)
		ListDashboards() ([]config.Dashboard, error)
	})
	if !ok {
		return false, errors.New("dashboard inventory unavailable")
	}
	deletions, err := repo.ListDashboardDeletions()
	if err != nil {
		return false, err
	}
	for _, deletion := range deletions {
		if deletion.DashboardID == dashboardID {
			return false, nil
		}
	}
	dashboards, err := repo.ListDashboards()
	if err != nil {
		return false, err
	}
	for _, dashboard := range dashboards {
		if dashboard.ID == dashboardID {
			return true, nil
		}
	}
	return false, nil
}

Manager.reserveCardReference.sig:
func (m *Manager) reserveCardReference(
	cardID, dashboardID, sessionID string,
	cancel context.CancelFunc,
	check func() (bool, error),
) (func(), error)

Manager.reserveCardReference.src:
//nolint:gocognit // Keep reservation and cancellation checks in the same critical section.
func (m *Manager) reserveCardReference(
	cardID, dashboardID, sessionID string,
	cancel context.CancelFunc,
	check func() (bool, error),
) (func(), error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return nil, ErrManagerClosed
	}

	cardExists, err := check()
	if err != nil {
		return nil, fmt.Errorf("check card before activation: %w", err)
	}
	if !cardExists {
		return nil, fmt.Errorf("card not found: %s", cardID)
	}
	if m.pendingCardRefs == nil {
		m.pendingCardRefs = make(map[string]int)
	}
	if m.pendingCardRefsByDashboard == nil {
		m.pendingCardRefsByDashboard = make(map[string]map[string]int)
	}
	m.pendingCardRefs[cardID]++
	m.cardReferenceRevision++
	if m.pendingCardRefsByDashboard[cardID] == nil {
		m.pendingCardRefsByDashboard[cardID] = make(map[string]int)
	}
	m.pendingCardRefsByDashboard[cardID][dashboardID]++
	reservation := &cardReservation{}
	if m.pendingCardDetails == nil {
		m.pendingCardDetails = make(map[string]map[*cardReservation]CardPendingReference)
	}
	if m.pendingCardDetails[cardID] == nil {
		m.pendingCardDetails[cardID] = make(map[*cardReservation]CardPendingReference)
	}
	m.pendingCardDetails[cardID][reservation] = CardPendingReference{
		DashboardID: dashboardID,
		SessionID:   sessionID,
		Cancellable: cancel != nil,
	}
	if cancel != nil {
		if m.pendingCardCancels == nil {
			m.pendingCardCancels = make(map[string]map[*cardReservation]context.CancelFunc)
		}
		if m.pendingCardCancels[cardID] == nil {
			m.pendingCardCancels[cardID] = make(map[*cardReservation]context.CancelFunc)
		}
		m.pendingCardCancels[cardID][reservation] = cancel
	}
	m.notifyCardReferencesLocked()

	var once sync.Once
	return func() {
		once.Do(func() {
			m.mu.Lock()
			defer m.mu.Unlock()
			m.cardReferenceRevision++
			delete(m.pendingCardDetails[cardID], reservation)
			if len(m.pendingCardDetails[cardID]) == 0 {
				delete(m.pendingCardDetails, cardID)
			}
			if cancel != nil {
				delete(m.pendingCardCancels[cardID], reservation)
				if len(m.pendingCardCancels[cardID]) == 0 {
					delete(m.pendingCardCancels, cardID)
				}
			}
			m.notifyCardReferencesLocked()
			byDashboard := m.pendingCardRefsByDashboard[cardID]
			if byDashboard[dashboardID] <= 1 {
				delete(byDashboard, dashboardID)
			} else {
				byDashboard[dashboardID]--
			}
			if len(byDashboard) == 0 {
				delete(m.pendingCardRefsByDashboard, cardID)
			}
			if m.pendingCardRefs[cardID] <= 1 {
				delete(m.pendingCardRefs, cardID)
				return
			}
			m.pendingCardRefs[cardID]--
		})
	}, nil
}

Manager.reserveForActivation.sig:
func (m *Manager) reserveForActivation(
	id, cardID, driverName, notTerminatedMsg string,
	choice ConversationChoice,
) (activationSnapshot, string, error)

Manager.reserveForActivation.src:
// reserveForActivation checks, under m.mu, that the session can be
// (re)activated and marks it as activating. It takes the lock itself; the
// caller must call releaseActivation on every failure path (success clears
// the mark in activateSessionLocked).
//
// On success it has also registered the activation with m.activations (in the
// same critical section as the !closed check), and the caller must call
// m.activations.Done() when the activation is over, after any
// releaseActivation, so Shutdown does not return while it is still working.
func (m *Manager) reserveForActivation(
	id, cardID, driverName, notTerminatedMsg string,
	choice ConversationChoice,
) (activationSnapshot, string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return activationSnapshot{}, "", ErrManagerClosed
	}
	s, ok := m.sessions[id]
	if !ok {
		return activationSnapshot{}, "", fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	if s.Status != StatusTerminated {
		return activationSnapshot{}, "", fmt.Errorf("%w: %s", ErrLifecycleConflict, notTerminatedMsg)
	}
	if s.activating {
		return activationSnapshot{}, "", fmt.Errorf("%w: session is already being started", ErrLifecycleConflict)
	}
	if s.stopping || s.deleting {
		return activationSnapshot{}, "", fmt.Errorf("%w: another lifecycle operation is in progress", ErrLifecycleConflict)
	}
	if s.activeSubmissions > 0 {
		return activationSnapshot{}, "", fmt.Errorf("%w: message submission is in progress", ErrLifecycleConflict)
	}
	conversationID, err := validateConversationChoice(s, cardID, driverName, choice)
	if err != nil {
		return activationSnapshot{}, "", err
	}
	m.revokeSessionActivationLocked(s)
	s.Registration = RegistrationUnavailable
	s.RegistrationPersistence = RegistrationNotAttempted
	s.RegistrationErr = ""
	s.ExpectedConversationID = ""
	s.activating = true
	m.activations.Add(1)
	return activationSnapshot{
		WorkingDir: s.WorkingDir, OriginalDir: s.OriginalDir,
		UseTmpWorkspace: s.UseTmpWorkspace, InstructionOwnership: cloneInstructionOwnership(s.InstructionOwnership),
		KankuroMCPEnabled: s.KankuroMCPEnabled,
		DashboardControl:  s.DashboardControl,
	}, conversationID, nil
}

Manager.resolveWorkspacePath.src:
// resolveWorkspacePath returns the override when given, else the path of the
// card's registered workspace.
func (m *Manager) resolveWorkspacePath(card config.IDCard, override string) (string, error) {
	if override != "" {
		return override, nil
	}
	workspaces, err := m.repo.ListWorkspaces()
	if err != nil {
		return "", fmt.Errorf("list workspaces: %w", err)
	}
	for _, w := range workspaces {
		if w.ID == card.WorkspaceID && w.Path != "" {
			return w.Path, nil
		}
	}
	return "", fmt.Errorf("workspace not found: %s", card.WorkspaceID)
}

Manager.revokeActivation.src:
func (m *Manager) revokeActivation(token string) {
	if token == "" {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	m.revokeAuthorityLocked(token)
}

Manager.revokeAuthorityLocked.src:
func (m *Manager) revokeAuthorityLocked(token string) {
	if token == "" {
		return
	}
	authority := m.authorities[token]
	if authority == nil {
		return
	}
	authority.revoked = true
	delete(m.authorities, token)
	if err := driver.RemoveKankuroMCPIfAuthorizationMatches(authority.configPath, token); err != nil {
		m.logger.Warn("workspace MCP config cleanup failed", "session_id", authority.sessionID,
			"warning", "revoked Kankuro MCP entry could not be safely removed")
	}
}

Manager.revokeSessionActivationLocked.src:
func (m *Manager) revokeSessionActivationLocked(s *Session) {
	m.revokeAuthorityLocked(s.ActivationToken)
	s.ActivationToken = ""
	if m.messages != nil {
		m.messages.Wake()
	}
}

Manager.setNameDetailedChecked.src:
func (m *Manager) setNameDetailedChecked(id, name, processID string, check func([]Snapshot) error) (RenameResult, error) {
	if check == nil {
		return RenameResult{}, errors.New("rename scope check is required")
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return RenameResult{}, ErrManagerClosed
	}
	if err := check(m.listLocked()); err != nil {
		return RenameResult{}, err
	}
	s, ok := m.sessions[id]
	if !ok {
		return RenameResult{}, fmt.Errorf("session not found: %s", id)
	}
	if processID != "" && s.ProcessActivationID != processID {
		return RenameResult{}, errors.New("session process changed before rename")
	}
	if s.deleting || s.stopping || s.activating {
		return RenameResult{}, fmt.Errorf("%w: rename is not allowed during a lifecycle operation", ErrLifecycleConflict)
	}
	s.Name = name
	err := m.persistSessionLockedErr(s)
	return RenameResult{Applied: true, Persisted: err == nil}, err
}

Manager.setRegistrationFailureLocked.src:
func (m *Manager) setRegistrationFailureLocked(authority *activationAuthority, message string) {
	authority.failure = message
	if !authority.published {
		return
	}
	s := m.sessions[authority.sessionID]
	if s == nil || s.ActivationID != authority.activationID {
		return
	}
	s.RegistrationErr = message
	if authority.acceptedID == "" {
		s.Registration = RegistrationFailed
	}
}

Manager.snapshotLocked.src:
func (m *Manager) snapshotLocked(s *Session) Snapshot {
	snap := s.snapshot()
	live := s.Driver != nil && s.Done != nil && s.Status != StatusTerminated
	if live {
		select {
		case <-s.Done:
			live = false
		default:
		}
	}
	snap.ProcessStarted = live
	snap.Phase = "terminated"
	if live {
		snap.Phase = "active"
		if s.starting {
			snap.Phase = "starting"
		}
	}
	snap.MessageDeliveryAvailable = m.deliveryAvailableLocked(s)
	return snap
}

Manager.startSessionCore.src:
//nolint:funlen,gocognit,gocyclo,cyclop // Workspace preparation, sync, spawn, publication, and persistence form one owned activation path.
//nolint:funlen,gocognit,gocyclo,cyclop // Workspace preparation, sync, spawn, publication, and persistence form one owned activation path.
func (m *Manager) startSessionCore(
	ctx context.Context,
	sid string,
	dashboardID string,
	card config.IDCard,
	skills []config.Skill,
	personas []config.Persona,
	mcps []config.MCPServer,
	isNew bool,
	workspaceOverride string,
	originalOverride string,
	previousInstructionOwnership map[string]bool,
	conversationID string,
	publicationCheck func([]Snapshot) error,
	name []*string,
	evidence *ActivationResult,
) (returnErr error) {
	if evidence == nil {
		evidence = &ActivationResult{}
	}
	var wd, finalWD string
	//nolint:nestif // Resolve and reserve the workspace before any launch effects.
	if isNew {
		var err error
		wd, err = m.resolveWorkspacePath(card, workspaceOverride)
		if err != nil {
			return err
		}
		if err = m.bindPendingWorkspace(ctx, card.ID, sid, wd, card.UseTmpWorkspace, publicationCheck); err != nil {
			return err
		}
		var errPrep error
		finalWD, errPrep = m.prepareWorkspace(ctx, sid, card, wd, true)
		if errPrep != nil {
			return m.cleanupNewTemporaryWorkspace(sid, card, true, errPrep)
		}
	} else {
		wd, finalWD = originalOverride, workspaceOverride
		if err := validateSessionWorkspace(finalWD); err != nil {
			return err
		}
	}
	d := m.drivers.Get(card.Driver)
	instructionFile := d.GetInstructionFileName()
	instructionsManaged := previousInstructionOwnership[instructionFile]
	committedInstructions := false
	var deployedSubWorkspaces []SubWorkspaceDescriptor
	subWorkspaceMetadataAvailable := false
	if isNew {
		var rollback func() error
		var prepareErr error
		instructionsManaged, rollback, prepareErr = m.prepareNewSessionFiles(ctx, d, card, skills, personas, mcps, finalWD)
		if prepareErr != nil {
			return m.cleanupNewTemporaryWorkspace(sid, card, true, prepareErr)
		}
		deployedSubWorkspaces, subWorkspaceMetadataAvailable = preparedSubWorkspaceDescriptors(finalWD)
		defer func() {
			if !committedInstructions && evidence.Effect != ActivationUncertain {
				returnErr = errors.Join(returnErr, rollback())
			}
		}()
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, ctxErr)
	}

	token, tokenErr := m.prepareActivationMCPConfig(sid, dashboardID, card, d, mcps, conversationID, finalWD, !isNew)
	if tokenErr != nil {
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, tokenErr)
	}
	published := false
	defer func() {
		if !published {
			m.revokeActivation(token)
		}
	}()
	if ctxErr := ctx.Err(); ctxErr != nil {
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, ctxErr)
	}
	if err := d.PrepareWorkspace(ctx, finalWD); err != nil {
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, err)
	}
	if isNew && card.UseTmpWorkspace {
		defer func() {
			if !committedInstructions && evidence.Effect != ActivationUncertain {
				if trustErr := driver.RemoveWorkspaceTrust(context.Background(), finalWD); trustErr != nil {
					returnErr = errors.Join(returnErr, &TemporaryTrustCleanupError{WorkingDir: finalWD, Err: trustErr})
				}
			}
		}()
	}
	args := append(d.SetModel(card.Model), d.SetSession(conversationID)...)
	if ctxErr := ctx.Err(); ctxErr != nil {
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, ctxErr)
	}
	h, errSpawn := d.Spawn(driver.AgentConfig{
		Driver:            card.Driver,
		Model:             card.Model,
		Args:              args,
		WorkingDir:        finalWD,
		SystemInstruction: card.SystemInstruction,
		Env:               activationEnv(card.Env),
	})
	if errSpawn != nil {
		if h != nil {
			cause := teardownActivation(d, h, evidence, sid, finalWD, errSpawn)
			if evidence.Effect == ActivationUncertain {
				return cause
			}
			return m.cleanupNewTemporaryWorkspace(sid, card, isNew, cause)
		}
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, errSpawn)
	}
	cleanupSpawn := func(cause error) error {
		cause = teardownActivation(d, h, evidence, sid, finalWD, cause)
		if evidence.Effect == ActivationUncertain {
			return cause
		}
		return m.cleanupNewTemporaryWorkspace(sid, card, isNew, cause)
	}

	deadline := m.startupClock.Now().Add(m.startupDelay)

	now := time.Now().UTC()
	pid := 0
	if h.Cmd != nil && h.Cmd.Process != nil {
		pid = h.Cmd.Process.Pid
	}

	m.mu.Lock()
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.mu.Unlock()
		return cleanupSpawn(ctxErr)
	}
	if m.closed {
		// Shutdown started during the unlocked spawn; see SwitchAgent. A new
		// session has no record, so nothing would ever point at its tmp copy.
		m.mu.Unlock()
		return cleanupSpawn(ErrManagerClosed)
	}
	if checkErr := publicationCheck(m.listLocked()); checkErr != nil {
		m.mu.Unlock()
		return cleanupSpawn(checkErr)
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.mu.Unlock()
		return cleanupSpawn(ctxErr)
	}
	select {
	case <-h.Done:
		m.mu.Unlock()
		return cleanupSpawn(errors.New("agent process exited during startup"))
	default:
	}
	defer m.mu.Unlock()

	s, exists := m.sessions[sid]
	if !exists {
		s = &Session{
			ID:          sid,
			DashboardID: dashboardID,
			Subscribers: make(map[chan []byte]struct{}),
		}
		s.Name = card.Name
		if len(name) > 0 && name[0] != nil {
			s.Name = strings.TrimSpace(*name[0])
			if s.Name == "" {
				s.Name = sid
			}
		}
		m.sessions[sid] = s
	}

	m.activateSessionLocked(s, card, d, h, pid, now)
	s.InstructionOwnership = updateInstructionOwnership(previousInstructionOwnership, instructionFile, instructionsManaged)
	s.InstructionsManaged = instructionsManaged
	s.KankuroMCPEnabled = token != ""
	s.DashboardControl = card.DashboardControl && token != ""
	if isNew {
		s.SubWorkspaces = deployedSubWorkspaces
		s.SubWorkspaceMetadataAvailable = subWorkspaceMetadataAvailable
	}
	m.publishActivationLocked(token, s)
	m.startStartupLocked(s, deadline)
	if token == "" {
		s.ExpectedConversationID = conversationID
	}
	published = true
	committedInstructions = true
	s.WorkingDir = finalWD
	s.OriginalDir = wd
	s.UseTmpWorkspace = card.UseTmpWorkspace
	if isNew {
		s.Scrollback = nil
		s.PendingAttachHeader = nil
	} else {
		// Show the relaunch marker only to the next attacher (not stored in
		// scrollback so it doesn't replay on every subsequent reattach).
		s.PendingAttachHeader = fmt.Appendf(nil, "\r\n--- Relaunched at %s ---\r\n\r\n",
			now.Format(time.RFC3339))
	}
	gen := s.generation

	go m.trackOutput(sid, gen, h.Output, s.Subscribers)
	m.startWatchLocked(sid, gen, d)
	*evidence = ActivationResult{
		Effect:              ActivationPublished,
		SessionID:           sid,
		ProcessActivationID: s.ProcessActivationID,
		PID:                 pid,
		WorkingDir:          finalWD,
		Spawned:             true,
	}

	// A persist failure here must not unwind the spawn: the agent process is
	// already running. Surface the error so the caller can report it, but
	// leave the in-memory session as-is. Wrapped in ErrPersistFailed so
	// callers can tell "did not start" apart from "started, but its record
	// did not save" and still offer the normal attach flow.
	if persistErr := m.persistSessionLockedErr(s); persistErr != nil {
		if s.Registration == RegistrationRegistered {
			s.RegistrationPersistence = RegistrationUnsaved
			s.RegistrationErr = conversationPersistenceWarning
		}
		return fmt.Errorf("%w: %w", ErrPersistFailed, persistErr)
	}
	return nil
}

Manager.startStartupLocked.src:
func (m *Manager) startStartupLocked(s *Session, deadline time.Time) {
	m.cancelStartupLocked(s)
	if m.startupDelay <= 0 {
		return
	}
	s.starting = true
	s.startupDeadline = deadline
	cancel := make(chan struct{})
	s.startupCancel = cancel
	generation, activation, done := s.generation, s.ActivationID, s.Done
	m.startupTimers.Go(func() {
		delay := max(deadline.Sub(m.startupClock.Now()), 0)
		timer := m.startupClock.NewTimer(delay)
		defer timer.Stop()
		select {
		case <-cancel:
			return
		case <-m.shutdownStart:
			return
		case <-done:
			return
		case <-timer.C():
		}
		m.mu.Lock()
		defer m.mu.Unlock()
		if !m.closed && m.sessions[s.ID] == s && s.generation == generation && s.ActivationID == activation && s.startupCancel == cancel &&
			!s.stopping &&
			!s.deleting &&
			!s.activating &&
			s.Driver != nil {
			select {
			case <-done:
				return
			default:
			}
			s.starting = false
			s.startupCancel = nil
		}
	})
}

Manager.startWatchLocked.src:
// startWatchLocked runs watch for one activation, tracked by m.watchers. It
// must be called with m.mu held, after checking !m.closed: the WaitGroup's Add
// happens under m.mu after that check, and Shutdown sets closed under m.mu
// before it calls Wait, so no Add can race a Wait that started at zero.
func (m *Manager) startWatchLocked(id string, gen uint64, d driver.AgentDriver) {
	done := m.sessions[id].Done
	m.watchers.Go(func() { m.watch(id, gen, d, done) })
}

Manager.switchAgentWithChoiceContext.src:
//nolint:nonamedreturns // The named result retains publication evidence alongside deferred cleanup errors.
func (m *Manager) switchAgentWithChoiceContext(
	ctx context.Context,
	id string,
	card config.IDCard,
	skills []config.Skill,
	personas []config.Persona,
	mcps []config.MCPServer,
	choice ConversationChoice,
	publicationCheck func([]Snapshot) error,
) (result ActivationResult) {
	result.SessionID = id
	result.Err = m.switchAgentWithChoiceCore(ctx, id, card, skills, personas, mcps, choice, publicationCheck, &result)
	return result
}

Manager.switchAgentWithChoiceCore.src:
//nolint:gocognit,funlen,gocyclo,cyclop // Reservation, rollback, spawn publication, and persistence form one activation transaction.
//nolint:gocognit,funlen,gocyclo,cyclop // Reservation, rollback, spawn publication, and persistence form one activation transaction.
func (m *Manager) switchAgentWithChoiceCore(
	ctx context.Context,
	id string,
	card config.IDCard,
	skills []config.Skill,
	personas []config.Persona,
	mcps []config.MCPServer,
	choice ConversationChoice,
	publicationCheck func([]Snapshot) error,
	evidence *ActivationResult,
) (returnErr error) {
	if evidence == nil {
		evidence = &ActivationResult{}
	}
	snap, conversationID, err := m.reserveForActivation(
		id,
		card.ID,
		card.Driver,
		"session must be terminated before switching agents",
		choice,
	)
	if err != nil {
		return err
	}
	defer m.activations.Done() // registered first, so it runs after releaseActivation below
	activated := false
	defer func() {
		if !activated {
			m.releaseActivation(id)
		}
	}()

	finalWD := snap.WorkingDir
	if workspaceErr := validateSessionWorkspace(finalWD); workspaceErr != nil {
		return workspaceErr
	}
	if prepareErr := m.prepareSubWorkspaces(ctx, card, finalWD); prepareErr != nil {
		return prepareErr
	}
	subWorkspaces, subWorkspaceMetadataAvailable := preparedSubWorkspaceDescriptors(finalWD)

	// Clear tmp directories if using tmp workspace
	clearTmp := snap.UseTmpWorkspace
	// Replace content owned by the previous card. If it had no managed
	// instructions, an empty destination must preserve workspace-authored rules.
	d := m.drivers.Get(card.Driver)
	instructionFile := d.GetInstructionFileName()
	instructionMode := driver.InstructionReplace
	if !snap.InstructionOwnership[instructionFile] {
		instructionMode = driver.InstructionPreserveWhenEmpty
	}
	previousFile, previousFileErr := snapshotInstructionFile(filepath.Join(finalWD, instructionFile))
	if previousFileErr != nil {
		return previousFileErr
	}
	defer func() {
		if !activated && evidence.Effect != ActivationUncertain {
			returnErr = errors.Join(returnErr, previousFile.restore(filepath.Join(finalWD, instructionFile)))
		}
	}()
	if ctxErr := ctx.Err(); ctxErr != nil {
		return ctxErr
	}
	d, instructionsManaged, err := m.syncDriverFiles(d, card, skills, personas, mcps, finalWD, clearTmp, instructionMode)
	if err != nil {
		return err
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		return ctxErr
	}

	token, tokenErr := m.prepareActivationMCPConfig(id, "", card, d, mcps, conversationID, finalWD, false)
	if tokenErr != nil {
		return tokenErr
	}
	published := false
	defer func() {
		if !published {
			m.revokeActivation(token)
		}
	}()
	if ctxErr := ctx.Err(); ctxErr != nil {
		return ctxErr
	}
	if prepareErr := d.PrepareWorkspace(ctx, finalWD); prepareErr != nil {
		return prepareErr
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		return ctxErr
	}
	args := append(d.SetModel(card.Model), d.SetSession(conversationID)...)
	h, errSpawn := d.Spawn(driver.AgentConfig{
		Driver:            card.Driver,
		Model:             card.Model,
		Args:              args,
		WorkingDir:        finalWD,
		SystemInstruction: card.SystemInstruction,
		Env:               activationEnv(card.Env),
	})
	if errSpawn != nil {
		if h != nil {
			return teardownActivation(d, h, evidence, id, finalWD, errSpawn)
		}
		return errSpawn
	}

	deadline := m.startupClock.Now().Add(m.startupDelay)

	now := time.Now().UTC()
	pid := 0
	if h.Cmd != nil && h.Cmd.Process != nil {
		pid = h.Cmd.Process.Pid
	}

	m.mu.Lock()
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, ctxErr)
	}
	if m.closed {
		// Shutdown started during the unlocked spawn. The process is already
		// running and no watcher will ever own it: kill it here, outside the
		// lock (Kill can block on teardown). The deferred releaseActivation
		// runs after this return.
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, ErrManagerClosed)
	}
	s, ok := m.sessions[id]
	if !ok {
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, fmt.Errorf("%w: %s", ErrSessionNotFound, id))
	}
	if checkErr := publicationCheck(m.listLocked()); checkErr != nil {
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, checkErr)
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, ctxErr)
	}
	select {
	case <-h.Done:
		m.mu.Unlock()
		return teardownActivation(d, h, evidence, id, finalWD, errors.New("agent process exited during startup"))
	default:
	}
	defer m.mu.Unlock()

	m.activateSessionLocked(s, card, d, h, pid, now)
	s.InstructionOwnership = updateInstructionOwnership(snap.InstructionOwnership, instructionFile, instructionsManaged)
	s.InstructionsManaged = instructionsManaged
	s.KankuroMCPEnabled = token != ""
	s.DashboardControl = card.DashboardControl && token != ""
	s.SubWorkspaces = subWorkspaces
	s.SubWorkspaceMetadataAvailable = subWorkspaceMetadataAvailable
	m.publishActivationLocked(token, s)
	m.startStartupLocked(s, deadline)
	if token == "" {
		s.ExpectedConversationID = conversationID
	}
	published = true
	activated = true
	s.PendingAttachHeader = fmt.Appendf(nil, "\r\n--- Switched agent to %s at %s ---\r\n\r\n",
		card.Name, now.Format(time.RFC3339))
	gen := s.generation

	go m.trackOutput(id, gen, h.Output, s.Subscribers)
	m.startWatchLocked(id, gen, d)
	*evidence = ActivationResult{
		Effect:              ActivationPublished,
		SessionID:           id,
		ProcessActivationID: s.ProcessActivationID,
		PID:                 pid,
		WorkingDir:          finalWD,
		Spawned:             true,
	}

	// A persist failure here must not unwind the spawn: the agent process is
	// already running. Surface the error so the caller can report it, but
	// leave the in-memory session as-is. Wrapped in ErrPersistFailed so
	// callers can tell "did not start" apart from "started, but its record
	// did not save" and still offer the normal attach flow.
	if persistErr := m.persistSessionLockedErr(s); persistErr != nil {
		if s.Registration == RegistrationRegistered {
			s.RegistrationPersistence = RegistrationUnsaved
			s.RegistrationErr = conversationPersistenceWarning
		}
		return fmt.Errorf("%w: %w", ErrPersistFailed, persistErr)
	}
	return nil
}

Manager.syncDriverFiles.src:
// syncDriverFiles clears temp directories (if needed) and syncs skill/persona/MCP files.
func (m *Manager) syncDriverFiles(
	d driver.AgentDriver,
	card config.IDCard,
	skills []config.Skill,
	personas []config.Persona,
	mcps []config.MCPServer,
	workingDir string,
	clearTmp bool,
	instructionMode driver.InstructionSyncMode,
) (driver.AgentDriver, bool, error) {
	if clearTmp {
		agentDirs := []string{".agents", ".claude"}
		if d.GetAgentFolder() != agentDirs[0] && d.GetAgentFolder() != agentDirs[1] {
			agentDirs = append(agentDirs, d.GetAgentFolder())
		}
		for _, agentDir := range agentDirs {
			// Clear existing .agents directories in tmp workspace
			skillsDir := filepath.Join(workingDir, agentDir, "skills")
			if err := os.RemoveAll(skillsDir); err != nil {
				return nil, false, fmt.Errorf("clear tmp skills dir: %w", err)
			}
			personasDir := filepath.Join(workingDir, agentDir, "agents")
			if err := os.RemoveAll(personasDir); err != nil {
				return nil, false, fmt.Errorf("clear tmp personas dir: %w", err)
			}
		}
	}

	instructionsManaged, err := d.SetAgentsMD(card, personas, mcps, workingDir, instructionMode)
	if err != nil {
		return nil, false, fmt.Errorf("set agents.md: %w", err)
	}
	if skillsErr := d.SetSkills(skills, workingDir); skillsErr != nil {
		return nil, false, fmt.Errorf("set skills: %w", skillsErr)
	}
	if personasErr := d.SetPersonas(personas, workingDir); personasErr != nil {
		return nil, false, fmt.Errorf("set personas: %w", personasErr)
	}
	return d, instructionsManaged, nil
}

Manager.tmpRoot.src:
// tmpRoot is the directory holding temporary workspace copies: KANKURO_TMP_DIR
// when set, else <config>/tmp. Creating and removing a copy must agree on it,
// so both go through here.
func (m *Manager) tmpRoot() string {
	if root := os.Getenv("KANKURO_TMP_DIR"); root != "" {
		return root
	}
	return filepath.Join(m.configDir, "tmp")
}

Manager.trackOutput.src:
func (m *Manager) trackOutput(sessionID string, gen uint64, output <-chan []byte, subscribers map[chan []byte]struct{}) {
	for chunk := range output {
		m.mu.Lock()
		s, ok := m.sessions[sessionID]
		broadcast(chunk, subscribers)
		if !ok || s.generation != gen {
			m.mu.Unlock()
			continue
		}
		now := time.Now().UTC()
		s.Scrollback = appendScrollback(s.Scrollback, chunk)
		updateSessionOutputState(s, chunk, now)
		if s.Status != StatusTerminated {
			if s.Pinged {
				s.Status = StatusWaiting
			} else {
				s.Status = StatusRunning
			}
		}
		m.mu.Unlock()
	}
	m.mu.Lock()
	if s, ok := m.sessions[sessionID]; ok && s.generation == gen && s.Output == output {
		s.outputComplete = true
	}
	for ch := range subscribers {
		close(ch)
		delete(subscribers, ch)
	}
	m.mu.Unlock()
}

Manager.validateReportedConversationLock.src:
func (m *Manager) validateReportedConversationLocked(authority *activationAuthority, conversationID string) error {
	if authority.expectedID == "" || authority.expectedID == conversationID {
		return nil
	}
	if authority.acceptedID == "" {
		m.setRegistrationFailureLocked(authority, "reported conversation did not match the requested resume")
	}
	return errors.New("reported conversation does not match the requested resume")
}

Manager.watch.src:
// watch polls one activation's driver until it terminates, its generation goes
// stale, or Shutdown closes m.stop. It is the only goroutine that writes
// session records in the background, which is why it must be stoppable.
//
//nolint:gocognit // One poll loop owns status, registration timeout, persistence, and subscriber teardown.
func (m *Manager) watch(sessionID string, gen uint64, d driver.AgentDriver, done <-chan struct{}) {
	ticker := time.NewTicker(watchInterval)
	defer ticker.Stop()
	for {
		select {
		case <-m.stop:
			return
		case <-done:
		case <-ticker.C:
		}
		status := d.GetStatus()
		select {
		case <-done:
			status = driver.StatusTerminated
		default:
		}
		m.mu.Lock()
		s, ok := m.sessions[sessionID]
		if !ok || s.generation != gen {
			m.mu.Unlock()
			return
		}
		if s.deleting || s.stopping {
			m.mu.Unlock()
			select {
			case <-done:
				return
			default:
			}
			continue
		}
		if s.Status == StatusTerminated {
			m.mu.Unlock()
			return
		}
		if status == driver.StatusTerminated {
			m.cancelStartupLocked(s)
			s.Status = StatusTerminated
			m.cancelPendingMessageAdmissionsLocked(s)
			s.Pinged = false
			if s.Registration == RegistrationPending {
				s.Registration = RegistrationUnconfirmed
			}
			m.revokeSessionActivationLocked(s)
			if exitCoder, hasExitCode := d.(interface{ ExitCode() int }); hasExitCode {
				s.ExitCode = exitCoder.ExitCode()
			}
			m.persistSessionLocked(s)
			m.mu.Unlock()
			if m.messages != nil {
				m.messages.Wake()
			}
			return
		}
		if s.Registration == RegistrationPending && time.Since(s.RegistrationAt) >= 60*time.Second {
			s.Registration = RegistrationUnconfirmed
		}
		if driver.IsPromptLike(s.LastOutput, s.LastWordAt, time.Now().UTC()) {
			s.Status = StatusWaiting
			s.Pinged = true
		} else {
			s.Status = StatusRunning
			s.Pinged = false
		}
		m.mu.Unlock()
	}
}

