// Wake interrupts bounded waiters when lifecycle or authorization state changes.
func (s *MessageStore) Wake() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.signalLocked()
	close(s.reportScopeChanged)
	s.reportScopeChanged = make(chan struct{})
