// Format implements [fmt.Formatter] for better error messages.
func (e *ideError) Format(f fmt.State, verb rune) {
	switch verb {
	case 'v':
		if f.Flag('+') {
			fmt.Fprintf(f, "%s: %s", "ideError", e.msg)
			return
		}
		fallthrough
	case 's':
		fmt.Fprint(f, e.msg)
	case 'q':
		fmt.Fprintf(f, "%q", e.msg)
	}
}

