Coordinator.cardEditorCallbacks.src:
func (c *Coordinator) cardEditorCallbacks() views.CardEditorCallbacks {
	return views.CardEditorCallbacks{
		OnSave: func(draft models.CardEditorDraft) tea.Cmd {
			if c.editorSaving || c.editorCompleted {
				return nil
			}
			draft = models.CloneCardEditorDraft(draft)
			c.editorSaving = true
			if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
				editor.SetSaving(true)
			}
			c.editorRequest++
			dashboardID, cardID, revision, generation, epoch, request, service := c.activeDashboard, c.editorCardID, c.editorRevision, c.viewGeneration, c.editorEpoch, c.editorRequest, c.editor
			return func() tea.Msg {
				var saved contracts.CardSaveResult
				var err error
				if cardID == "" {
					saved, err = service.CreateEditorCard(contracts.CreateCardInput{DashboardID: dashboardID, Values: draft.Values})
				} else {
					saved, err = service.UpdateEditorCard(
						contracts.UpdateCardInput{
							DashboardID:      dashboardID,
							CardID:           cardID,
							ExpectedRevision: revision,
							Changes:          draft.Changes,
						},
					)
				}
				return messages.CardSavedMsg{
					Result:      saved,
					Err:         err,
					DashboardID: dashboardID,
					CardID:      cardID,
					Generation:  generation,
					Epoch:       epoch,
					Request:     request,
				}
			}
		},
		OnReload: func() tea.Cmd {
			if c.editorSaving {
				return nil
			}
			c.editorEpoch++
			c.editorRequest++
			return cardEditorLoadCommand(c.editor, c.activeDashboard, c.editorCardID, c.viewGeneration, c.editorEpoch, c.editorRequest)
		},
		OnCancel: func() tea.Cmd {
			if c.editorSaving {
				return nil
			}
			dashboardID, generation, epoch, request := c.activeDashboard, c.viewGeneration, c.editorEpoch, c.editorRequest
			return func() tea.Msg {
				return messages.EditorCancelMsg{DashboardID: dashboardID, Generation: generation, Epoch: epoch, Request: request}
			}
		},

		OnOpenSources: func(sourceType string) tea.Cmd {
			var vt messages.ViewType
			switch sourceType {
			case "skills":
				vt = messages.ViewSourceManagerSkills
			case "personas":
				vt = messages.ViewSourceManagerPersonas
			default:
				return nil
			}

			return c.editorNavigationCommand(vt)
		},

		OnOpenMCPForm: func() tea.Cmd {
			return c.editorNavigationCommand(messages.ViewMCPForm)
		},

		OnOpenWorkspaces: func() tea.Cmd {
			return c.editorNavigationCommand(messages.ViewSourceManagerWorkspaces)
		},

		OnOpenPuppetSources: func() tea.Cmd {
			return c.editorNavigationCommand(messages.ViewSourceManagerPuppets)
		},
	}
}

Coordinator.centerRead.src:
func (c *Coordinator) centerRead() tea.Cmd {
	st := &c.center
	if st.ctx == nil || st.limit <= 0 {
		return nil
	}
	if st.reading {
		st.pending = true
		return nil
	}
	st.reading = true
	st.pending = false
	st.request++
	ctx, port, generation, request := st.ctx, st.port, st.generation, st.request
	req := contracts.SessionReportsRequest{Limit: st.limit}
	req.DashboardID, req.SessionID = st.dashboardID, st.sessionID
	return func() tea.Msg {
		result, err := port.ReadSessionReports(ctx, req)
		return centerReportsMsg{generation: generation, request: request, result: result, err: err}
	}
}

Coordinator.centerSchedule.src:
func (c *Coordinator) centerSchedule() tea.Cmd {
	st := &c.center
	if st.timer || st.ctx == nil || st.reading || st.working || st.setup {
		return nil
	}
	if len(st.data.Reports) > 0 && st.reportWarning == "" && st.subscriptionWarning == "" {
		return nil
	}
	st.timer = true
	st.timerRequest++
	ctx, cancel := context.WithCancel(st.ctx)
	st.timerCancel = cancel
	generation, request := st.generation, st.timerRequest
	clock := st.clock
	if clock == nil {
		clock = systemCenterClock{}
	}
	return func() tea.Msg {
		if !clock.Wait(ctx, centerRetryInterval) {
			return nil
		}
		return centerTimerMsg{generation: generation, request: request}
	}
}

Coordinator.centerSelectionBlocked.src:
func (c *Coordinator) centerSelectionBlocked(id string) bool {
	if c.centerBlockedSession == "" {
		return false
	}
	if id == c.centerBlockedSession && c.activeDashboard == c.centerBlockedDashboard {
		return true
	}
	c.centerBlockedSession, c.centerBlockedDashboard = "", ""
	return false
}

Coordinator.centerSubscribe.src:
func (c *Coordinator) centerSubscribe() tea.Cmd {
	st := &c.center
	if st.setup || st.ctx == nil {
		return nil
	}
	st.setup = true
	ctx, port, generation := st.ctx, st.port, st.generation
	scope := contracts.ScopedSessionRequest{DashboardID: st.dashboardID, SessionID: st.sessionID}
	return func() tea.Msg {
		sub, err := port.SubscribeSessionReports(ctx, scope)
		if ctx.Err() != nil && sub != nil {
			sub.Release()
			sub = nil
		}
		return centerSetupMsg{generation: generation, subscription: sub, err: err}
	}
}

Coordinator.centerWorkspace.src:
func (c *Coordinator) centerWorkspace() tea.Cmd {
	st := &c.center
	if st.ctx == nil || st.working {
		return nil
	}
	st.working = true
	st.workspaceAttempted = true
	st.workspaceDue = false
	st.workspaceRequest++
	ctx, cancel := context.WithCancel(st.ctx)
	st.workspaceCancel = cancel
	port, generation, request := st.port, st.generation, st.workspaceRequest
	scope := contracts.ScopedSessionRequest{DashboardID: st.dashboardID, SessionID: st.sessionID}
	return func() tea.Msg {
		result, err := port.ReadSessionWorkspace(ctx, scope)
		return centerWorkspaceMsg{generation: generation, request: request, result: result, err: err}
	}
}

Coordinator.clearCenter.src:
func (c *Coordinator) clearCenter() {
	st := &c.center
	st.generation++
	if st.cancel != nil {
		st.cancel()
	}
	if st.subscription != nil {
		st.subscription.Release()
	}
	if st.workspaceCancel != nil {
		st.workspaceCancel()
	}
	if st.timerCancel != nil {
		st.timerCancel()
	}
	port, clock, saved, generation := st.port, st.clock, st.saved, st.generation
	*st = centerState{port: port, clock: clock, saved: saved, generation: generation}
}

