//nolint:funlen // The callback table keeps view wiring in one place.
func (c *Coordinator) dashboardCallbacks() views.DashboardCallbacks {
	return views.DashboardCallbacks{
		OnBack: func() tea.Cmd {
			dashboardID, generation := c.activeDashboard, c.viewGeneration
			return func() tea.Msg {
				return messages.DashboardListRequestedMsg{DashboardID: dashboardID, Generation: generation}
			}
		},
		OnEditCard: func(cardID string) tea.Cmd {
			return c.requestCardEditor(cardID)
		},
		OnRenameSession: c.renameDashboardSession,

		OnLaunchCard: func(cardID string) tea.Cmd {
			c.launchRequest++
			c.launchCardID = cardID
			return dashboardCardCommand(c.reads, c.activeDashboard, cardID, c.viewGeneration, c.launchRequest, messages.DashboardCardLaunch)
		},

		OnAttach: func(sessionID string) tea.Cmd {
			return c.requestAttach(sessionID)
		},

		OnRelaunch: c.requestRelaunch,

		OnKill: func(sessionID string) (tea.Cmd, error) {
			c.mutationRequest++
			dashboardID, generation, request, service := c.activeDashboard, c.viewGeneration, c.mutationRequest, c.actions.port
			return func() tea.Msg {
				return messages.SessionStoppedMsg{
					DashboardID: dashboardID,
					Generation:  generation,
					SessionID:   sessionID,
					Request:     request,
					Result: service.StopDashboardSession(
						context.Background(),
						contracts.ScopedSessionRequest{DashboardID: dashboardID, SessionID: sessionID},
					),
				}
			}, nil
		},
		OnRemove: func(sessionID string) (tea.Cmd, error) {
			c.mutationRequest++
			dashboardID, generation, request, service := c.activeDashboard, c.viewGeneration, c.mutationRequest, c.actions.port
			return func() tea.Msg {
				return messages.SessionRemovedMsg{
					DashboardID: dashboardID,
					Generation:  generation,
					SessionID:   sessionID,
					Request:     request,
					Result: service.RemoveDashboardSession(
						context.Background(),
						contracts.ScopedSessionRequest{DashboardID: dashboardID, SessionID: sessionID},
					),
				}
			}, nil
		},

		OnDeleteCard: func(cardID string) (tea.Cmd, error) {
			c.cardDeleteRead++
			return cardDeletionPreflightCommand(
				c.deletion,
				c.activeDashboard,
				cardID,
				c.viewGeneration,
				c.cardDeleteRead,
				c.deletionVisit,
			), nil
		},
		OnConfirmCardDeletion: func(cardID, token string, foreign bool) tea.Cmd {
			return c.confirmCardDeletion(c.activeDashboard, cardID, token, c.viewGeneration, foreign)
		},
		OnRetryCardDeletion: func(cardID string) tea.Cmd {
			if c.cardDeleting {
				return nil
			}
			c.cardDeleting = true
			c.cardDeleteTarget = cardID
			c.cardDeleteAction++
			return retryCardDeletionCommand(
				c.deletion,
				c.deletionWorkers,
				c.activeDashboard,
				cardID,
				c.viewGeneration,
				c.cardDeleteAction,
				c.deletionVisit,
			)
		},

		OnOpenMCP: func() tea.Cmd {
			return c.navigationCommand(messages.ViewMCPManager)
		},

		OnOpenWorkspaces: func() tea.Cmd {
			return c.navigationCommand(messages.ViewSourceManagerWorkspaces)
		},

		OnOpenSettings: func() tea.Cmd {
			settingsView, ok := c.views[ViewType(messages.ViewSettings)].(*views.SettingsView)
			if ok {
				settingsView.SetSettings(c.settings)
			}
			return c.navigationCommand(messages.ViewSettings)
		},

		OnOpenCardEditor: func() tea.Cmd { return c.requestCardEditor("") },

		OnLaunchIDE:      c.launchIDE,
		OnLaunchTerminal: c.launchTerminal,
	}
}

Coordinator.dashboardListCallbacks.src:
func (c *Coordinator) dashboardListCallbacks() views.DashboardListCallbacks {
	service := c.deletion
	workers := c.deletionWorkers
	return views.DashboardListCallbacks{
		Open: func(dashboard contracts.DashboardSummary) tea.Cmd {
			generation := c.viewGeneration
			return func() tea.Msg {
				return messages.DashboardOpenRequestedMsg{
					DashboardID: dashboard.ID, DashboardName: dashboard.Name,
					DashboardState: dashboard.State, Generation: generation,
				}
			}
		},
		Save: func(id, name, description string) tea.Cmd {
			generation := c.viewGeneration
			return func() tea.Msg {
				var err error
				if id == "" {
					err = service.CreateHumanDashboard(name, description)
				} else {
					err = service.UpdateHumanDashboard(id, name, description)
				}
				return messages.DashboardMutationFinishedMsg{Err: err, Generation: generation}
			}
		},
		PreflightDelete: func(id string) tea.Cmd {
			c.dashboardDeleteRead++
			request, visit := c.dashboardDeleteRead, c.deletionVisit
			return func() tea.Msg {
				preflight, err := service.PrepareHumanDashboardDeletion(id)
				return messages.DashboardDeletionPreparedMsg{
					DashboardID: id, Request: request, Visit: visit,
					Token: preflight.Token,
					Summary: dashboardDeletionSummary(
						preflight,
					),
					RequiresForeignConfirmation: preflight.RequiresForeignConfirmation,
					Err:                         err,
				}
			}
		},
		ConfirmDelete: func(id, token string, foreign bool) tea.Cmd {
			if c.dashboardDeleting {
				return nil
			}
			c.dashboardDeleting = true
			c.dashboardDeleteTarget = id
			c.dashboardDeleteAction++
			request, visit := c.dashboardDeleteAction, c.deletionVisit
			generation := c.viewGeneration
			return func() tea.Msg {
				progress, err := workers.run(func(ctx context.Context) (contracts.DeletionProgress, error) {
					return service.ConfirmHumanDashboardDeletion(ctx, id, token, foreign)
				})
				return messages.DashboardMutationFinishedMsg{
					Err:        err,
					Generation: generation,
					Progress:   progress,
					Request:    request,
					Visit:      visit,
				}
			}
		},
		RetryDelete: func(id string) tea.Cmd {
			if c.dashboardDeleting {
				return nil
			}
			c.dashboardDeleting = true
			c.dashboardDeleteTarget = id
			c.dashboardDeleteAction++
			request, visit := c.dashboardDeleteAction, c.deletionVisit
			generation := c.viewGeneration
			return func() tea.Msg {
				progress, err := workers.run(func(ctx context.Context) (contracts.DeletionProgress, error) {
					return service.RetryHumanDashboardDeletion(ctx, id)
				})
				return messages.DashboardMutationFinishedMsg{
					Err:        err,
					Generation: generation,
					Progress:   progress,
					Request:    request,
					Visit:      visit,
				}
			}
		},
		InspectDelete: func(id string) tea.Cmd {
			c.dashboardDeleteRead++
			request, visit := c.dashboardDeleteRead, c.deletionVisit
			return func() tea.Msg {
				manifest, err := service.ReadHumanDashboardDeletion(id)
				return messages.DashboardDeletionStatusMsg{
					DashboardID: id,
					Request:     request,
					Visit:       visit,
					Summary:     dashboardDeletionStatus(manifest),
					Err:         err,
				}
			}
		},
	}
}

