Coordinator.guardKey.src:
// guardKey decides what a message does while the terminal is too small. It
// returns handled=true for input it consumed: quit still quits (it is the
// user's way out), every other keypress or paste is dropped.
func (c *Coordinator) guardKey(msg tea.Msg) (bool, tea.Cmd) {
	switch m := msg.(type) {
	case tea.KeyPressMsg:
		if s := m.String(); s == "q" || (s == "ctrl+c" && c.currentView != ViewDashboardList) {
			return true, tea.Quit
		}
		return true, nil
	case tea.PasteMsg:
		return true, nil
	}
	return false, nil
}

Coordinator.handleCenter.src:
//nolint:gocognit,gocyclo,cyclop,funlen // The coordinator serializes correlated state transitions here.
func (c *Coordinator) handleCenter(msg tea.Msg) (bool, tea.Cmd) {
	st := &c.center
	switch m := msg.(type) {
	case centerSetupMsg:
		if m.generation != st.generation || st.ctx == nil {
			if m.subscription != nil {
				m.subscription.Release()
			}
			return true, nil
		}
		st.setup = false
		if m.err == nil && m.subscription == nil {
			m.err = errors.New("subscription unavailable")
		}
		if m.err != nil {
			if errors.Is(m.err, contracts.ErrSessionScope) {
				c.invalidateCenterScope()
				return true, nil
			}
			st.subscriptionWarning = "Report updates unavailable: " + m.err.Error()
		} else {
			st.subscription = m.subscription
			st.subscriptionWarning = ""
		}
		c.publishCenter()
		var wait tea.Cmd
		if st.subscription != nil {
			wait = centerWait(st.generation, st.subscription)
		}
		return true, tea.Batch(wait, c.centerRead())
	case centerChangeMsg:
		if m.generation != st.generation || st.subscription != m.subscription {
			return true, nil
		}
		if m.closed {
			st.subscription.Release()
			st.subscription = nil
			if errors.Is(m.err, contracts.ErrSessionScope) {
				c.invalidateCenterScope()
				return true, nil
			}
			st.subscriptionWarning = "Report updates disconnected"
			c.publishCenter()
			return true, c.centerSchedule()
		}
		wait := centerWait(st.generation, st.subscription)
		// A failed report read enters the timed recovery cycle. Global store
		// changes are coalesced until that cycle retries the read.
		if st.reportWarning != "" {
			st.pending = true
			return true, tea.Batch(wait, c.centerSchedule())
		}
		return true, tea.Batch(wait, c.centerRead())
	case centerReportsMsg:
		if m.generation != st.generation || m.request != st.request || st.ctx == nil {
			return true, nil
		}
		st.reading = false
		if errors.Is(m.err, contracts.ErrSessionScope) {
			c.invalidateCenterScope()
			return true, nil
		}
		if m.err != nil {
			st.reportWarning = "Reports unavailable: " + m.err.Error()
			st.data.Stale = len(st.data.Reports) > 0 || (st.data.Workspace != nil && st.workspaceStale)
		} else {
			st.reportWarning = ""
			st.data.Loading = false
			st.data.Reports = append([]contracts.SessionReport(nil), m.result.Reports...)
			st.data.Omitted = m.result.Omitted
			st.data.Stale = st.data.Workspace != nil && st.workspaceStale
			if len(st.data.Reports) > 0 {
				st.data.Stale = false
				st.workspaceAttempted, st.workspaceStale = false, false
				if st.reportWarning == "" && st.subscriptionWarning == "" && st.timerCancel != nil {
					st.timerCancel()
					st.timerCancel = nil
					st.timer = false
					st.timerRequest++
				}
				c.cancelCenterWorkspace()
				st.data.Workspace = nil
				st.workspaceWarning = ""
			}
		}
		c.publishCenter()
		if st.pending && m.err == nil {
			return true, c.centerRead()
		}
		if len(st.data.Reports) == 0 && !st.working && ((!st.workspaceAttempted && st.data.Workspace == nil) || st.workspaceDue) {
			return true, c.centerWorkspace()
		}
		return true, c.centerSchedule()
	case centerWorkspaceMsg:
		if m.generation != st.generation || m.request != st.workspaceRequest || st.ctx == nil {
			return true, nil
		}
		st.working = false
		if st.workspaceCancel != nil {
			st.workspaceCancel()
			st.workspaceCancel = nil
		}
		if errors.Is(m.err, contracts.ErrSessionScope) {
			c.invalidateCenterScope()
			return true, nil
		}
		st.data.Loading = false
		if m.err != nil {
			st.workspaceWarning = joinCenterWarning("Workspace unavailable: "+m.err.Error(), strings.Join(m.result.Warnings, "; "))
			st.workspaceStale = true
			st.data.Stale = st.data.Workspace != nil
		} else {
			st.workspaceStale = false
			st.data.Workspace = &m.result
			st.workspaceWarning = ""
			st.data.Stale = false
		}
		c.publishCenter()
		return true, c.centerSchedule()
	case centerTimerMsg:
		if m.generation != st.generation || m.request != st.timerRequest || st.ctx == nil {
			return true, nil
		}
		st.timer = false
		if len(st.data.Reports) == 0 {
			st.workspaceDue = true
		}
		if st.timerCancel != nil {
			st.timerCancel()
			st.timerCancel = nil
		}
		if st.subscription == nil {
			return true, c.centerSubscribe()
		}
		return true, c.centerRead()
	}
	return false, nil
}

Coordinator.handleConfigFingerprint.src:
// handleConfigFingerprint adopts only current, scope-valid results. Unchanged
// polls carry no data or token and cannot overwrite a forced refresh.
func (c *Coordinator) handleConfigFingerprint(m configFingerprintMsg) tea.Cmd {
	if m.requestID < c.lastAppliedRefreshRequest ||
		m.dashboardID != c.activeDashboard || m.generation != c.viewGeneration ||
		m.sessionEpoch < c.sessionEpoch {
		return nil
	}
	c.lastAppliedRefreshRequest = m.requestID
	if m.data == nil {
		return nil
	}
	if m.data.DashboardID != m.dashboardID || m.data.Generation != m.generation ||
		m.data.SessionEpoch != m.sessionEpoch || c.hasStaleSessionSnapshot(*m.data) {
		return nil
	}
	c.configFingerprint = m.token
	return c.handleDataLoaded(*m.data)
}

Coordinator.handleConversationPrepared.src:
func (c *Coordinator) handleConversationPrepared(m messages.ConversationPreparedMsg) tea.Cmd {
	if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Epoch != c.conversationEpoch ||
		m.Request != c.conversationReadRequest {
		return nil
	}
	c.conversationReading = false
	if c.conversationCancel != nil {
		c.conversationCancel()
		c.conversationCancel = nil
	}
	choiceView, ok := c.views[ViewConversationChoice].(*views.ConversationChoiceView)
	if !ok {
		c.err = errors.New("conversation selection view is unavailable")
		return nil
	}
	if err := validateConversationPrepared(m); err != nil {
		c.err = err
		if !m.Initial {
			choiceView.SetContextError(err.Error())
		}
		return nil
	}

	if m.Initial &&
		((m.ReturnView == messages.ViewDashboard && c.currentView != ViewDashboard) || (m.ReturnView == messages.ViewAgentSwitch && c.currentView != ViewAgentSwitch)) {
		return nil
	}
	if m.Initial && !m.Preparation.HasSaved {
		c.lifecycleExecuting = true
		return c.actions.activate(
			c.activeDashboard,
			c.viewGeneration,
			c.lifecycleRequest,
			m.Preparation.SessionID,
			m.Preparation.CardID,
			m.ReturnView == messages.ViewDashboard,
			contracts.ConversationChoice{Kind: contracts.ConversationNew},
		)
	}
	if m.Initial {
		choiceView.SetContext(m.Preparation.SessionID, m.Preparation.CardID, m.ReturnView, m.Preparation.Options)
		return c.navigateTo(ViewConversationChoice)
	}
	choiceView.RefreshContext(m.Preparation.SessionID, m.Preparation.CardID, m.Preparation.Options)
	return nil
}

Coordinator.handleDataLoaded.src:
func (c *Coordinator) handleDataLoaded(m messages.DataLoadedMsg) tea.Cmd {
	if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
		return nil
	}
	if !c.acceptInventorySnapshot(&m) {
		return nil
	}
	c.invalidateMissingAttachment(m.DashboardID, m.SessionEpoch, m.InventoryRequestID, m.Inventory)
	if m.Err != nil {
		c.err = m.Err
		// A failed registry read is not a valid fingerprint baseline: retry
		// even if the underlying file's metadata does not change.
		c.configFingerprint = ""
	}
	c.applyDisplayChoices(m.Choices)
	if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
		editor.SetChoices(m.EditorChoices)
	}
	if c.activeDashboard == "" {
		for viewType, view := range c.views {
			if viewType == ViewDashboard || viewType == ViewAgentSwitch || viewType == ViewConversationChoice ||
				viewType == ViewSessionLauncher {
				continue
			}
			if receiver, ok := view.(messages.DataReceiver); ok {
				receiver.SetData(m)
			}
		}
		return nil
	}
	c.broadcastData(m)
	if dashboard, ok := c.views[ViewDashboard].(*views.Dashboard); ok {
		dashboard.SetInventory(m.Inventory, m.Choices)
	}
	if switchView, ok := c.views[ViewAgentSwitch].(*views.AgentSwitchView); ok && m.Inventory.Attempted && m.Inventory.Err == nil {
		switchView.SetRows(models.CardRows(m.Inventory.Value.Cards, c.displayChoices))
	}
	var conversationRefresh tea.Cmd
	if c.currentView == ViewConversationChoice {
		conversationRefresh = c.refreshConversationChoiceContext()
	}

	var sourceReload tea.Cmd
	if source, ok := c.views[c.currentView].(*views.SourceManager); ok {
		sourceReload = source.Reload()
	}
	return tea.Batch(conversationRefresh, sourceReload, c.reconcileCenter())
}

Coordinator.handleSessionMessages.src:
//nolint:gocognit,gocyclo,cyclop,funlen // Session message routing preserves scoped transitions.
func (c *Coordinator) handleSessionMessages(msg tea.Msg) (bool, tea.Cmd) {
	switch m := msg.(type) {
	case messages.DataLoadedMsg:
		return true, c.handleDataLoaded(m)

	case messages.SessionsRefreshedMsg:
		return true, c.handleSessionsRefreshed(m)

	case messages.SessionSelectedMsg:
		return true, c.reconcileCenter()

	case messages.SessionLaunchCompletedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != c.launchRequest || m.CardID == "" || m.CardID != c.launchCardID {
			if m.Result.Validate() != nil || m.Result.Effect != contracts.NoEffect {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		launcher, ok := c.views[ViewSessionLauncher].(*views.SessionLauncher)
		if ok {
			if launcher.Card().ID != m.CardID {
				return true, c.refreshDataSeeded()
			}
			launcher.SetLaunchResult(m.Result)
		}
		validationErr := m.Result.Validate()
		if validationErr != nil || m.Result.Effect != contracts.NoEffect {
			c.sessionEpoch++
		}
		if validationErr == nil && m.Result.Effect == contracts.UsableActivation {
			if dashboard, found := c.views[ViewDashboard].(*views.Dashboard); found {
				dashboard.FocusSession(m.Result.SessionID)
			}
		}
		return true, c.refreshDataSeeded()

	case messages.AgentSwitchRequestedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		switchView, ok := c.views[ViewAgentSwitch].(*views.AgentSwitchView)
		if ok {
			switchView.SetSession(m.SessionID, m.SessionName)
		}
		return true, c.navigateTo(ViewAgentSwitch)

	case messages.ConversationPreparedMsg:
		return true, c.handleConversationPrepared(m)
	case messages.SessionActivationCompletedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != c.lifecycleRequest {
			if m.Result.Validate() != nil || m.Result.Effect != contracts.NoEffect {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		c.lifecycleExecuting = false
		result := m.Result
		if err := result.Validate(); err != nil {
			c.sessionEpoch++
			c.err = err
			return true, c.refreshDataSeeded()
		}
		if result.Effect != contracts.UsableActivation || result.SessionID != m.SessionID {
			if result.Effect != contracts.NoEffect {
				c.sessionEpoch++
			}
			if result.Diagnostic != "" {
				c.err = errors.New(result.Diagnostic)
			} else {
				c.err = errors.New("activation outcome is invalid")
			}
			return true, c.refreshDataSeeded()
		}
		if result.Diagnostic != "" {
			c.err = errors.New(result.Diagnostic)
		}
		c.sessionEpoch++
		init := c.navigateTo(ViewDashboard)
		return true, tea.Batch(
			init,
			c.refreshDataSeeded(),
			c.requestAttachExpected(result.SessionID, result.ProcessActivationID, messages.AttachRequestLifecycle),
		)

	case messages.SessionAttachRequestedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		// Navigate here, not in the callback that produced this message
		// (invariant 2, see navigateTo's doc comment).
		var initCmd tea.Cmd
		if c.currentView != ViewDashboard {
			initCmd = c.navigateTo(ViewDashboard)
		}
		if m.Warning != nil {
			c.err = m.Warning
		}
		return true, tea.Batch(initCmd, c.requestAttach(m.SessionID))

	case messages.ScopedAttachReadyMsg:
		staleRequest := (m.RequestKind == messages.AttachRequestLaunch && m.Request != c.launchRequest) ||
			(m.RequestKind == messages.AttachRequestLifecycle && m.Request != c.lifecycleRequest) ||
			(m.RequestKind != "" && m.RequestKind != messages.AttachRequestLaunch && m.RequestKind != messages.AttachRequestLifecycle)
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || staleRequest ||
			(m.Sequence != 0 && !c.attachmentOwner.current(m.Sequence, m.DashboardID, m.SessionID)) {
			if m.Sequence != 0 {
				c.attachmentOwner.finish(m.Sequence)
			}
			if m.Handle != nil {
				_ = m.Handle.Close()
			}
			return true, nil
		}
		if m.Err != nil {
			if m.Sequence != 0 {
				c.attachmentOwner.finish(m.Sequence)
			}
			if m.Handle != nil {
				_ = m.Handle.Close()
			}
			c.err = m.Err
			return true, nil
		}
		if m.Handle == nil {
			if m.Sequence != 0 {
				c.attachmentOwner.finish(m.Sequence)
			}
			c.err = errors.New("attachment unavailable")
			return true, nil
		}
		return true, scopedAttachCommand(m)

	case messages.ScopedSessionNamedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != c.renameRequest || c.currentView != ViewSessionLauncher {
			if m.Result.Applied {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		launcher, ok := c.views[ViewSessionLauncher].(*views.SessionLauncher)
		if !ok || launcher.SessionID() != m.SessionID || launcher.ProcessActivationID() == "" {
			return true, nil
		}
		var renameErr error
		if m.Result.Diagnostic != "" {
			renameErr = errors.New(m.Result.Diagnostic)
		}
		if !m.Result.Applied {
			if renameErr == nil {
				renameErr = errors.New("rename did not apply")
			}
			launcher.SetNameResult(renameErr)
			return true, c.refreshDataSeeded()
		}
		launcher.SetNameResult(nil)
		if renameErr != nil {
			c.err = renameErr
		}

		c.sessionEpoch++
		if dashboard, found := c.views[ViewDashboard].(*views.Dashboard); found {
			dashboard.FocusSessionAfterRename(m.SessionID, m.Name)
		}
		return true, tea.Batch(
			c.navigateTo(ViewDashboard),
			c.requestAttachExpected(m.SessionID, launcher.ProcessActivationID(), messages.AttachRequestLaunch),
		)

	case messages.DashboardSessionRenamedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != c.renameRequest || c.currentView != ViewDashboard {
			if m.Result.Applied {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		dashboard, ok := c.views[ViewDashboard].(*views.Dashboard)
		if !ok {
			return true, nil
		}
		var renameErr error
		if m.Result.Diagnostic != "" {
			renameErr = errors.New(m.Result.Diagnostic)
		}
		var formErr error
		if !m.Result.Applied {
			if renameErr == nil {
				renameErr = errors.New("rename did not apply")
			}
			formErr = renameErr
		}
		if !dashboard.CompleteRename(m.SessionID, formErr) {
			return true, nil
		}
		if m.Result.Applied {
			c.sessionEpoch++
			if renameErr != nil {
				c.err = renameErr
			}
		}
		return true, c.refreshDataSeeded()

	case messages.WorkspaceOpenedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Request != c.workspaceRequest {
			return true, nil
		}
		if m.Result.Diagnostic != "" {
			c.err = errors.New(m.Result.Diagnostic)
		} else if !m.Result.Started {
			c.err = errors.New("workspace command did not start")
		}
		return true, nil

	case messages.SessionStoppedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != c.mutationRequest {
			if m.Result.ProcessTerminated {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		if m.Result.Diagnostic != "" {
			c.err = errors.New(m.Result.Diagnostic)
		}
		if m.Result.ProcessTerminated {
			c.sessionEpoch++
		}
		return true, c.refreshDataSeeded()
	case messages.SessionRemovedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Result.InMemoryRemoved && c.attachmentOwner != nil {
			c.attachmentOwner.invalidateSession(m.DashboardID, m.SessionID)
		}
		if m.Request != c.mutationRequest {
			if m.Result.InMemoryRemoved || m.Result.RecordDeleted || m.Result.WorkspaceRemoved {
				c.sessionEpoch++
			}
			return true, c.refreshDataSeeded()
		}
		if m.Result.Diagnostic != "" {
			c.err = errors.New(m.Result.Diagnostic)
		}
		if m.Result.InMemoryRemoved || m.Result.RecordDeleted || m.Result.WorkspaceRemoved {
			c.sessionEpoch++
		}
		return true, c.refreshDataSeeded()

	case messages.ScopedActionFinishedMsg:
		if m.Request != 0 {
			if m.Request == c.cardDeleteAction {
				c.cardDeleting = false
			}
			if m.Request != c.cardDeleteAction || m.Visit != c.deletionVisit {
				return true, nil
			}
		}
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != 0 || m.Progress.Outcome != "" {
			if !c.showCardDeletionResult(m.Progress, m.Request, m.DashboardID, m.Err) {
				return true, nil
			}
		}
		if m.Err != nil {
			c.err = m.Err
		}
		return true, c.refreshDataSeeded()

	case messages.AttachFinishedMsg:
		if m.Sequence != 0 {
			c.attachmentOwner.finish(m.Sequence)
		}
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
		}
		return true, c.refreshDataSeeded()
	}

	return false, nil
}

Coordinator.handleSessionsRefreshed.src:
// handleSessionsRefreshed applies scoped cards and sessions to their
// consumers without reloading unrelated configuration views.
func (c *Coordinator) handleSessionsRefreshed(m messages.SessionsRefreshedMsg) tea.Cmd {
	if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
		return nil
	}
	if m.SessionEpoch < c.sessionEpoch {
		return nil
	}
	if !m.Inventory.Attempted || m.InventoryRequestID < c.lastAppliedInventoryRequest {
		return nil
	}
	c.lastAppliedInventoryRequest = m.InventoryRequestID
	c.invalidateMissingAttachment(m.DashboardID, m.SessionEpoch, m.InventoryRequestID, m.Inventory)
	if c.activeDashboard == "" {
		return nil
	}
	if m.Err != nil {
		c.err = m.Err
	}
	if dashboard, ok := c.views[ViewDashboard].(*views.Dashboard); ok {
		dashboard.SetInventory(m.Inventory, m.Choices)
	}
	if switchView, ok := c.views[ViewAgentSwitch].(*views.AgentSwitchView); ok && m.Inventory.Attempted && m.Inventory.Err == nil {
		switchView.SetRows(models.CardRows(m.Inventory.Value.Cards, c.displayChoices))
	}

	var conversationRefresh tea.Cmd
	if c.currentView == ViewConversationChoice {
		conversationRefresh = c.refreshConversationChoiceContext()
	}

	var sourceReload tea.Cmd
	if source, ok := c.views[c.currentView].(*views.SourceManager); ok {
		sourceReload = source.Reload()
	}
	return tea.Batch(conversationRefresh, sourceReload, c.reconcileCenter())
}

Coordinator.handleSpecialMessages.src:
//nolint:funlen,gocognit,gocyclo,cyclop // Central message router keeps ordering-sensitive app transitions together.
func (c *Coordinator) handleSpecialMessages(msg tea.Msg) (bool, tea.Cmd) {
	switch m := msg.(type) {
	case tea.WindowSizeMsg:
		c.width = m.Width
		c.height = m.Height
		c.resizeAll()
		return true, c.reconcileCenter()

	case tickMsg:
		// Refresh scoped sessions every tick; reread configuration only when its
		// fingerprint changes.
		var listCmd tea.Cmd
		if c.currentView == ViewDashboardList {
			listCmd = c.refreshDashboardList()
		}
		return true, tea.Batch(c.refreshSessions(), c.maybeRefreshConfig(), listCmd, tick())

	case messages.DashboardListLoadedMsg:

		if m.RequestID != c.dashboardListRequest {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		if view, ok := c.views[ViewDashboardList].(*views.DashboardList); ok {
			view.SetDashboards(m.Dashboards)
		}
		return true, nil

	case messages.DashboardDeletionPreparedMsg:
		if m.Request != 0 && (m.Request != c.dashboardDeleteRead || m.Visit != c.deletionVisit || c.currentView != ViewDashboardList) {
			return true, nil
		}
		return false, nil
	case messages.DashboardDeletionStatusMsg:
		if m.Request != 0 && (m.Request != c.dashboardDeleteRead || m.Visit != c.deletionVisit || c.currentView != ViewDashboardList) {
			return true, nil
		}
		return false, nil
	case messages.DashboardMutationFinishedMsg:
		if m.Request != 0 {
			if m.Request == c.dashboardDeleteAction {
				c.dashboardDeleting = false
			}
			if m.Request != c.dashboardDeleteAction || m.Visit != c.deletionVisit || c.currentView != ViewDashboardList {
				return true, nil
			}
		}
		if m.Generation != c.viewGeneration {
			return true, nil
		}
		if m.Request != 0 || m.Progress.Outcome != "" {
			target := m.Progress.DashboardID
			if m.Request != 0 && c.dashboardDeleteTarget != "" && target != "" && target != c.dashboardDeleteTarget {
				return true, nil
			}
			if target == "" {
				target = c.dashboardDeleteTarget
			}
			m.Progress.DashboardID = target
			if list, ok := c.views[ViewDashboardList].(*views.DashboardList); ok {
				list.ShowDeletionResult(
					target,
					deletionResultLines(m.Progress, m.Err),
					m.Progress.Outcome == contracts.DeletionPendingOutcome,
				)
			}
		}
		if m.Err != nil {
			c.err = m.Err
		}
		return true, c.refreshDashboardList()

	case messages.CardDeletionPreparedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || c.currentView != ViewDashboard ||
			(m.Request != 0 && (m.Request != c.cardDeleteRead || m.Visit != c.deletionVisit)) {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		if m.RequiresForeignConfirmation {
			if dashboard, ok := c.views[ViewDashboard].(*views.Dashboard); ok {
				dashboard.ShowCardDeletionImpact(m.CardID, m.Token, m.Summary)
			}
			return true, nil
		}
		return true, c.confirmCardDeletion(m.DashboardID, m.CardID, m.Token, m.Generation, false)

	case messages.DashboardOpenRequestedMsg:
		if c.currentView != ViewDashboardList || m.Generation != c.viewGeneration || m.DashboardID == "" ||
			m.DashboardState != contracts.DashboardActive {
			return true, nil
		}
		c.activeDashboard = m.DashboardID
		c.viewGeneration++
		dashboard := c.dashboardViews[m.DashboardID]
		if dashboard == nil {
			dashboard = views.NewDashboard(c.dashboardCallbacks())
			c.dashboardViews[m.DashboardID] = dashboard
		}
		dashboard.SetDashboardName(m.DashboardName)
		dashboard.SetDashboardScope(m.DashboardID, c.viewGeneration)
		dashboard.SetSize(c.width, c.height-views.CoordinatorRows)
		c.views[ViewDashboard] = dashboard
		return true, tea.Batch(c.navigateTo(ViewDashboard), c.refreshDataSeeded())

	case messages.DashboardCardLoadedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Request != c.launchRequest ||
			c.currentView != ViewDashboard {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		if m.Card.ID != m.CardID {
			c.err = errors.New("card read target mismatch")
			return true, nil
		}
		switch m.Action {
		case messages.DashboardCardLaunch:
			return true, c.launchCard(m.Card, m.Request)
		default:
			return true, nil
		}

	case messages.DashboardListRequestedMsg:

		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		if dashboard, ok := c.views[ViewDashboard].(*views.Dashboard); ok {
			dashboard.SetDashboardScope("", c.viewGeneration+1)
		}
		c.activeDashboard = ""
		c.viewGeneration++
		return true, tea.Batch(c.navigateTo(ViewDashboardList), c.refreshDashboardList())

	case configFingerprintMsg:
		return true, c.handleConfigFingerprint(m)

	case messages.DataRefreshRequestedMsg:
		return true, c.refreshDataSeeded()

	case messages.EditorCancelMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Epoch != c.editorEpoch ||
			m.Request != c.editorRequest ||
			c.currentView != ViewCardEditor ||
			c.editorSaving {
			return true, nil
		}
		c.editorEpoch++
		return true, c.navigateTo(ViewDashboard)

	case messages.EditorNavigateMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Epoch != c.editorEpoch ||
			c.currentView != ViewCardEditor ||
			c.editorSaving ||
			c.editorCompleted {
			return true, nil
		}
		return true, c.navigateTo(convertViewType(m.View))

	case messages.ScopedNavigateMsg:
		if c.currentView == ViewCardEditor && c.editorSaving {
			return true, nil
		}
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration {
			return true, nil
		}
		return true, c.navigateTo(convertViewType(m.View))

	case messages.NavigateBackMsg:
		if c.currentView == ViewMCPForm {
			c.mcpRequest++
			return true, c.navigateTo(c.mcpReturn)
		}
		if c.currentView == ViewMCPManager {
			return true, c.navigateTo(ViewDashboard)
		}
		return true, c.navigateTo(c.prevView)

	case messages.MCPManagerEditMsg:
		if !c.matchesMCPManagerScope(m.Scope) {
			return true, nil
		}
		cmd := c.navigateTo(ViewMCPForm)
		if form, ok := c.views[ViewMCPForm].(*views.MCPForm); ok {
			form.SetLoading(true)
		}
		service, dashboard, generation, request, id := c.configuration, c.activeDashboard, c.viewGeneration, c.mcpRequest, m.MCPID
		return true, tea.Batch(cmd, func() tea.Msg {
			data, err := service.LoadMCPEditor(id)
			return messages.MCPEditorLoadedMsg{MCP: data, Err: err, DashboardID: dashboard, Generation: generation, Request: request}
		})

	case messages.MCPManagerDeleteMsg:
		manager, ok := c.views[ViewMCPManager].(*views.MCPManager)
		if !ok {
			return true, nil
		}
		if !c.matchesMCPManagerScope(m.Scope) {
			manager.DiscardDelete(m.Scope.Visit)
			return true, nil
		}
		if !manager.AdmitDelete(m.Scope.Visit) {
			return true, nil
		}
		c.mcpDeleteRequest++
		return true, deleteMCPFromManagerCommand(c.configuration, m.MCPID, c.activeDashboard, c.viewGeneration, c.mcpDeleteRequest)

	case messages.MCPManagerDeletedMsg:
		if m.Request == c.mcpDeleteRequest {
			if manager, ok := c.views[ViewMCPManager].(*views.MCPManager); ok {
				manager.DeleteFinished()
			}
			if m.Err != nil && m.DashboardID == c.activeDashboard && m.Generation == c.viewGeneration && c.currentView == ViewMCPManager {
				c.err = m.Err
			}
		}
		if m.Err == nil {
			return true, c.refreshDataSeeded()
		}
		return true, nil

	case messages.CardEditorLoadedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Epoch != c.editorEpoch ||
			m.Request != c.editorRequest ||
			m.CardID != c.editorCardID ||
			(c.currentView != ViewDashboard && c.currentView != ViewCardEditor) {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		editor, ok := c.views[ViewCardEditor].(*views.CardEditor)
		if !ok {
			return true, nil
		}
		editor.SetChoices(m.Choices)
		if err := editorChoicesError(m.Choices); err != nil {
			c.err = err
		}
		editor.LoadEditor(m.Data)
		c.editorCompleted = false
		c.editorRevision = m.Data.Revision
		return true, c.navigateTo(ViewCardEditor)

	case messages.CardSavedMsg:
		matching := m.DashboardID == c.activeDashboard && m.Generation == c.viewGeneration && m.Epoch == c.editorEpoch &&
			m.Request == c.editorRequest &&
			m.CardID == c.editorCardID
		if matching {
			c.editorSaving = false
			if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
				editor.SetSaving(false)
			}
		}
		if !matching {
			if m.Err == nil {
				return true, c.refreshDataSeeded()
			}
			return true, nil
		}
		if c.currentView != ViewCardEditor {
			if m.Err != nil {
				c.err = m.Err
				return true, nil
			}
			c.editorCompleted = true
			c.editorCardID, c.editorRevision = m.Result.CardID, m.Result.Revision
			if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
				editor.MarkSaveCompleted()
			}
			return true, c.refreshDataSeeded()
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		c.editorEpoch++
		return true, tea.Batch(c.refreshDataSeeded(), c.navigateTo(ViewDashboard))

	case messages.MCPEditorLoadedMsg:
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Request != c.mcpRequest ||
			c.currentView != ViewMCPForm {
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, c.navigateTo(c.mcpReturn)
		}
		if form, ok := c.views[ViewMCPForm].(*views.MCPForm); ok {
			form.SetMCP(m.MCP)
		}
		return true, nil

	case messages.MCPSavedMsg:
		if m.Request == c.mcpRequest {
			c.mcpSaving = false
		}
		if m.DashboardID != c.activeDashboard || m.Generation != c.viewGeneration || m.Request != c.mcpRequest ||
			c.currentView != ViewMCPForm {
			if m.Err == nil {
				return true, c.refreshDataSeeded()
			}
			return true, nil
		}
		if form, ok := c.views[ViewMCPForm].(*views.MCPForm); ok {
			form.SetSaving(false)
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		return true, tea.Batch(c.refreshDataSeeded(), c.navigateTo(c.mcpReturn))

	case messages.SettingsLoadedMsg:
		if m.Request != c.settingsRequest {
			return true, nil
		}
		c.settingsLoading = false
		if settings, ok := c.views[ViewSettings].(*views.SettingsView); ok {
			settings.ReadFinished()
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		c.settings = m.Settings
		if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
			editor.SetSettings(editorSettings(m.Settings.ShowPersonasInCardEditor, m.Settings.ShowMCPsInCardEditor))
		}
		if settings, ok := c.views[ViewSettings].(*views.SettingsView); ok {
			settings.ApplyLoadedSettings(m.Settings)
		}
		return true, nil

	case messages.SettingsSavedMsg:
		if m.Request != c.settingsSaveRequest {
			return true, nil
		}
		c.settingsSaving = false
		if m.Err == nil {
			c.settings = m.Settings
			if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
				editor.SetSettings(editorSettings(m.Settings.ShowPersonasInCardEditor, m.Settings.ShowMCPsInCardEditor))
			}
		}
		settings, ok := c.views[ViewSettings].(*views.SettingsView)
		if ok && c.currentView == ViewSettings {
			settings.SaveFinished()
		}
		current := ok && c.currentView == ViewSettings && m.DashboardID == c.activeDashboard && m.Generation == c.viewGeneration &&
			m.Visit == c.settingsVisit &&
			m.Draft == settings.DraftID()
		if !current {
			if m.Err == nil {
				return true, c.refreshDataSeeded()
			}
			return true, nil
		}
		if m.Err != nil {
			c.err = m.Err
			return true, nil
		}
		return true, tea.Batch(c.refreshDataSeeded(), c.navigateTo(ViewDashboard))

	case messages.ErrorMsg:
		c.err = m.Err
		if c.currentView == ViewConversationChoice {
			return true, c.refreshDataSeeded()
		}
		return true, nil

	case messages.MCPServerFailedMsg:
		c.err = m.Err
		return true, tea.Quit

	case messages.MCPDeletedMsg:
		if editor, ok := c.views[ViewCardEditor].(*views.CardEditor); ok {
			editor.Update(m)
		}
		return true, c.refreshDataSeeded()

	case messages.MCPDeleteRequestedMsg:
		// Disk I/O deferred to a tea.Cmd, consistent with every other
		// mutation - this used to run synchronously inside Update.
		return true, deleteMCPCommand(c.configuration, m)

	case messages.ClearErrorMsg:
		c.err = nil
		return true, nil
	}

	return c.handleSessionMessages(msg)
}

