Coordinator.invalidateSessionRequestsOnN.src:
func (c *Coordinator) invalidateSessionRequestsOnNavigation(vt ViewType) {
	if c.currentView == ViewDashboard && vt != ViewDashboard {
		c.renameRequest++
		c.workspaceRequest++
		c.mutationRequest++
		if vt != ViewSessionLauncher {
			c.launchRequest++
		}
	}
	switch {
	case c.currentView == ViewConversationChoice && vt != ViewConversationChoice:
		c.cancelConversationRead()
	case c.currentView == ViewDashboard && vt != ViewDashboard && vt != ViewConversationChoice:
		c.cancelConversationRead()
	case c.currentView == ViewAgentSwitch && vt != ViewAgentSwitch && vt != ViewConversationChoice:
		c.cancelConversationRead()
	}
	if c.currentView == ViewSessionLauncher && vt != ViewSessionLauncher {
		c.renameRequest++
		c.launchRequest++
	}
}

Coordinator.launchCard.src:
func (c *Coordinator) launchCard(card contracts.CardSummary, request uint64) tea.Cmd {
	launcher, ok := c.views[ViewSessionLauncher].(*views.SessionLauncher)
	if !ok {
		return nil
	}
	launcher.Reset()
	launcher.SetCard(card)

	// The view reset above is coordinator-goroutine work and has already
	// happened; the blocking launch is sessionActions' closure.
	launch := c.actions.launch(c.activeDashboard, c.viewGeneration, card.ID, request)

	// This runs in the checked card-loaded handler, outside a view Update.
	// Enter the launcher now so a queued generic navigation cannot reopen it
	// after the user leaves or starts another launch.
	return tea.Batch(c.navigateTo(ViewSessionLauncher), launch)
}

