attachmentOwner.begin.src:
func (o *attachmentOwner) begin(target attachmentTarget) (context.Context, uint64) {
	o.mu.Lock()
	defer o.mu.Unlock()
	o.clearLocked()
	o.sequence++
	o.target = target
	ctx, cancel := context.WithCancel(context.Background())
	if o.closed {
		cancel()
	} else {
		o.cancel = cancel
	}
	return ctx, o.sequence
}

attachmentOwner.clearLocked.src:
func (o *attachmentOwner) clearLocked() {
	if o.cancel != nil {
		o.cancel()
		o.cancel = nil
	}
	if o.resource != nil {
		_ = o.resource.Close()
		o.resource = nil
	}
	o.target = attachmentTarget{}
}

attachmentOwner.current.src:
func (o *attachmentOwner) current(sequence uint64, dashboardID, sessionID string) bool {
	o.mu.Lock()
	defer o.mu.Unlock()
	return !o.closed && sequence == o.sequence && o.cancel != nil &&
		o.target.dashboardID == dashboardID && o.target.sessionID == sessionID
}

attachmentOwner.finish.src:
func (o *attachmentOwner) finish(sequence uint64) {
	o.mu.Lock()
	defer o.mu.Unlock()
	if sequence == o.sequence {
		o.clearLocked()
	}
}

attachmentOwner.invalidateMissing.src:
// invalidateMissing only consumes an inventory newer than the one observed at
// request creation and from no earlier session epoch.
func (o *attachmentOwner) invalidateMissing(dashboardID string, epoch, request uint64, sessions []contracts.SessionSummary) {
	o.mu.Lock()
	defer o.mu.Unlock()
	if o.cancel == nil || o.target.dashboardID != dashboardID || epoch < o.target.sessionEpoch || request <= o.target.inventoryRequest {
		return
	}
	for _, item := range sessions {
		if item.ID == o.target.sessionID {
			return
		}
	}
	o.clearLocked()
	o.sequence++
}

attachmentOwner.invalidateSession.src:
func (o *attachmentOwner) invalidateSession(dashboardID, sessionID string) {
	o.mu.Lock()
	defer o.mu.Unlock()
	if o.cancel != nil && o.target.dashboardID == dashboardID && o.target.sessionID == sessionID {
		o.clearLocked()
		o.sequence++
	}
}

attachmentOwner.publish.src:
func (o *attachmentOwner) publish(sequence uint64, resource contracts.Attachment) bool {
	o.mu.Lock()
	defer o.mu.Unlock()
	if o.closed || sequence != o.sequence || o.cancel == nil {
		if resource != nil {
			_ = resource.Close()
		}
		return false
	}
	o.resource = resource
	return true
}

deletionWorkers.close.src:
func (w *deletionWorkers) close() {
	w.mu.Lock()
	w.closed = true
	for _, cancel := range w.cancels {
		cancel()
	}
	w.mu.Unlock()
	w.wg.Wait()
}

deletionWorkers.run.src:
func (w *deletionWorkers) run(fn func(context.Context) (contracts.DeletionProgress, error)) (contracts.DeletionProgress, error) {
	w.mu.Lock()
	if w.closed {
		w.mu.Unlock()
		return contracts.DeletionProgress{}, context.Canceled
	}
	ctx, cancel := context.WithTimeout(context.Background(), dashboardDeletionTimeout)
	if w.cancels == nil {
		w.cancels = make(map[context.Context]context.CancelFunc)
	}
	w.cancels[ctx] = cancel
	w.wg.Add(1)
	w.mu.Unlock()
	defer func() { cancel(); w.mu.Lock(); delete(w.cancels, ctx); w.mu.Unlock(); w.wg.Done() }()
	return fn(ctx)
}

refresher.loadGlobalConfigData.src:
// loadGlobalConfigData reads registries shared by all dashboards.
func (r refresher) loadGlobalConfigData() messages.DataLoadedMsg {
	var errs []error

	var rows []contracts.MCPRow
	if r.configuration != nil {
		var rowErr error
		rows, rowErr = r.configuration.ReadMCPRows()
		if rowErr != nil {
			errs = append(errs, rowErr)
		}
	}
	var choices contracts.CardEditorChoices
	if r.editor != nil {
		choices = r.editor.ReadCardEditorChoices()
		errs = append(errs, editorChoicesError(choices))
	}
	return messages.DataLoadedMsg{
		EditorChoices: choices,
		MCPRows:       rows,
		Err:           errors.Join(errs...),
		RegistryErr:   errors.Join(errs...),
	}
}

refresher.scopedConfigIfChanged.src:
func (r refresher) scopedConfigIfChanged(
	service dashboardInventoryReader,
	dashboardID string,
	generation uint64,
	prev contracts.RegistryChangeToken,
	requestID uint64,
	inventoryRequestID uint64,
) tea.Cmd {
	return func() tea.Msg {
		before, beforeErr := service.ReadRegistryChangeToken()
		if beforeErr == nil && prev != "" && before == prev {
			return configFingerprintMsg{
				requestID: requestID, inventoryRequestID: inventoryRequestID, dashboardID: dashboardID,
				generation: generation, sessionEpoch: r.sessionEpoch,
			}
		}
		data := r.loadGlobalConfigData()
		data.DashboardID, data.Generation, data.SessionEpoch = dashboardID, generation, r.sessionEpoch
		data.InventoryRequestID = inventoryRequestID
		data.Inventory, data.Choices, _ = readFocusedDashboard(service, dashboardID)
		choiceErr := displayChoiceError(data.Choices)
		after, afterErr := service.ReadRegistryChangeToken()
		tokenErr := errors.Join(tokenReadError("before", beforeErr), tokenReadError("after", afterErr))
		var certificationErr error
		var token contracts.RegistryChangeToken
		if beforeErr == nil && afterErr == nil && before == after && data.Err == nil &&
			data.Inventory.Err == nil && choiceErr == nil {
			token = after
		} else if beforeErr == nil && afterErr == nil && before != after {
			certificationErr = errors.New("registries changed during refresh")
		}
		data.RegistryErr = errors.Join(data.RegistryErr, choiceErr, tokenErr, certificationErr)
		data.Err = errors.Join(data.RegistryErr, data.Inventory.Err)
		return configFingerprintMsg{
			token: token, requestID: requestID, inventoryRequestID: inventoryRequestID, dashboardID: dashboardID,
			generation: generation, sessionEpoch: r.sessionEpoch, data: &data,
		}
	}
}

