	marker := strings.Repeat(" ", agentsMDMarkerWidth)
	if focused {
		marker = lipgloss.NewStyle().Foreground(styles.HighlightColor).Render("> ")
	}
	return lipgloss.JoinHorizontal(lipgloss.Top, marker, view)
}

