func parseCommaList(input string) []string {
	var result []string
	for _, p := range splitEscaped(input) {
		if s := strings.TrimSpace(p); s != "" {
			result = append(result, s)
		}
	}
	return result
}

parseKeyValueList.src:
// parseKeyValueList parses a comma-separated list of key=value pairs. It
// returns an error instead of silently dropping a pair that has no `=`, so a
// typo is surfaced rather than vanishing.
func parseKeyValueList(input string) (map[string]string, error) {
	result := make(map[string]string)
	for _, pair := range splitEscaped(input) {
		if strings.TrimSpace(pair) == "" {
			continue
		}
		k, v, ok := strings.Cut(pair, "=")
		if !ok {
			return nil, fmt.Errorf("malformed key=value pair: %q", pair)
		}
		result[strings.TrimSpace(k)] = strings.TrimSpace(v)
	}
	return result, nil
}

puppetArt.src:
// puppetArt returns a puppet's art. User puppets come from files, so their
// lines are made safe for one row each and are clipped by the caller.
func puppetArt(p models.PuppetOption) string {
	if p.Builtin {
		puppet := characters.NewPuppet(func(c *ascii.Config) { c.Set("style", p.Name) })
		w, h := puppet.Bounds()
		canvas := ascii.NewCanvas(w, h)
		puppet.Render(canvas, 0, 0)
		return canvas.String()
	}
	lines := make([]string, len(p.Lines))
	for i, l := range p.Lines {
		lines[i] = components.DisplayText(l)
	}
	return strings.Join(lines, "\n")
}

