splitEscaped.src:
// splitEscaped splits input on unescaped commas, unescaping `\,` and `\\`
// into a literal `,` and `\` in the returned tokens.
func splitEscaped(input string) []string {
	var result []string
	var cur strings.Builder
	escaped := false
	for _, r := range input {
		switch {
		case escaped:
			cur.WriteRune(r)
			escaped = false
		case r == '\\':
			escaped = true
		case r == ',':
			result = append(result, cur.String())
			cur.Reset()
		default:
			cur.WriteRune(r)
		}
	}
	result = append(result, cur.String())
	return result
}

