	v.cards = models.CloneCardRows(cards)
	for index := range v.cards {
		if v.cards[index].FilterKey == "" {
			v.cards[index].FilterKey = v.cards[index].Name + " " + v.cards[index].Driver + " " + v.cards[index].Model
		}
	}
	v.refreshItems()
	if selectedID != "" {
		for index, item := range v.list.Items() {
