	}
	details := "Selected ID: " + components.DisplayText(item.option.NativeID) + " (" + components.DisplayText(item.option.Driver) + ")"
	wrapped := ansi.Wrap(details, max(conversationChoiceMinDetailWidth, v.Width-widthPadding*4), "")
