Dashboard.Update.src:
// Update handles messages.
func (d *Dashboard) Update(msg tea.Msg) (component.Model, tea.Cmd) {
	if d.cardResultOpen {
		if key, ok := msg.(tea.KeyPressMsg); ok && (key.Code == tea.KeyEsc || key.Code == tea.KeyEnter) {
			d.cardResultOpen = false
			return d, nil
		}
		var cmd tea.Cmd
		d.cardImpactViewport, cmd = d.cardImpactViewport.Update(msg)
		return d, cmd
	}
	if d.cardImpactOpen {
		return d.updateCardImpact(msg)
	}
	if d.renameModal.IsOpen() {
		return d.updateRename(msg)
	}
	// Handle modals first
	if d.deleteModal.IsOpen() {
		return d.updateDeleteModal(msg)
	}

	// Handle key events
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		if cmd, handled := d.handleKey(keyMsg); handled {
			return d, cmd
		}
	}

	// Route to focused pane
	return d.updateFocusedPane(msg)
}

Dashboard.View.src:
// View renders the dashboard.
func (d *Dashboard) View() string {
	if d.cardResultOpen {
		content := "Deletion result\n" + d.cardImpactViewport.View() + "\nEsc: close  ↑/↓: scroll"
		modal := lipgloss.NewStyle().Border(lipgloss.RoundedBorder()).Padding(0, 1).Render(content)
		return lipgloss.Place(d.Width, d.Height, lipgloss.Center, lipgloss.Center, modal)
	}
	if d.cardImpactOpen {
		content := "Delete this card globally?\n" + d.cardImpactViewport.View() + "\nEnter: confirm  Esc: cancel  ↑/↓: scroll"
		modal := lipgloss.NewStyle().Border(lipgloss.RoundedBorder()).Padding(0, 1).Render(content)
		return lipgloss.Place(d.Width, d.Height, lipgloss.Center, lipgloss.Center, modal)
	}
	// Handle modal overlays
	if d.deleteModal.IsOpen() {
		return d.renderWithOverlay(d.deleteModal.View())
	}
	if d.renameModal.IsOpen() {
		content := d.renameInput.View()
		if d.renamePending {
			content += "\nSaving…"
		} else {
			content += "\nEnter: save  Esc: cancel"
		}
		if d.renameErr != nil {
			const errorPrefix = "Save failed: "
			errorWidth := max(0, d.renameInput.Width()-lipgloss.Width(errorPrefix))
			errorText := errorPrefix + components.TruncateTail(components.DisplayText(d.renameErr.Error()), errorWidth)
			content += "\n" + errorText
		}
		d.renameModal.SetContent(content)
		return d.renderWithOverlay(d.renameModal.View())
	}

	return d.renderBase()
}

Dashboard.applyPendingSessionFocus.src:
func (d *Dashboard) applyPendingSessionFocus() {
	if d.pendingFocusSessionID == "" {
		return
	}
	for _, sess := range d.sessionRows {
		if sess.ID != d.pendingFocusSessionID {
			continue
		}
		if d.pendingFocusWaitName && sess.Name != d.pendingFocusName {
			return
		}
		if !matchesSessionQuery(sess, d.search.SessionsQuery) {
			d.search.SessionsQuery = ""
			d.sessionList.SetSearchQuery("")
		}
		d.sessionList.SetSelectedByID(sess.ID)
		selected, ok := d.sessionList.Selected()
		if !ok || selected.ID != sess.ID {
			return
		}
		d.focusedPane = PaneSessions
		d.pendingFocusSessionID = ""
		d.pendingFocusName = ""
		d.pendingFocusWaitName = false
		d.syncCenterSelection()
		return
	}
}

