Dashboard.confirmDelete.src:
func (d *Dashboard) confirmDelete() (component.Model, tea.Cmd) {
	d.deleteModal.Close()
	pending := d.pending
	d.pending = PendingAction{}

	switch pending.Code {
	case "delete-session":
		if d.callbacks.OnRemove != nil {
			cmd, err := d.callbacks.OnRemove(pending.SessionID)
			if err != nil {
				return d, func() tea.Msg { return messages.ErrorMsg{Err: err} }
			}
			d.syncCenterSelection()
			return d, cmd
		}
	case "delete-card":
		if d.callbacks.OnDeleteCard != nil {
			cmd, err := d.callbacks.OnDeleteCard(pending.CardID)
			if err != nil {
				return d, func() tea.Msg { return messages.ErrorMsg{Err: err} }
			}
			return d, cmd
		}
	}
	return d, nil
}

Dashboard.footerText.src:
// footerText picks the richest key legend that fits width. It gives up, in
// order: the navigation group, the rest of the global group (q=Quit stays),
// the focused pane's group - and as a last resort clips the line.
func (d *Dashboard) footerText(width int) string {
	pane := footerCards
	navigation := footerNav
	if d.dashboardID != "" {
		navigation = "[Nav] Tab Esc=Dashboards"
	}
	if card, ok := d.cardList.Selected(); d.focusedPane == PaneCards && ok && card.Retry.Enabled {
		pane = "[Card] r=Retry deletion"
	}
	if d.focusedPane == PaneSessions {
		pane = footerSessions
	}
	candidates := [][]string{
		{navigation, pane, footerGlobal},
		{navigation, pane, footerGlobalMinimal},
	}
	if d.dashboardID == "" {
		candidates = append(candidates, []string{pane, footerGlobal}, []string{pane, footerGlobalMinimal})
	}
	if d.focusedPane == PaneSessions {
		candidates = append(candidates,
			[]string{navigation, "[Session] Enter=Attach/Relaunch e=Rename o=IDE t=Terminal", footerGlobalMinimal},
			[]string{navigation, "[Session] Enter=Attach e=Rename t=Terminal", footerGlobalMinimal},
		)
		if d.dashboardID != "" {
			candidates = append(candidates,
				[]string{"Esc=Dashboards", "[Session] Enter=Attach e=Rename", footerGlobalMinimal},
				[]string{"Esc=Dashboards", "[Session] Enter=Attach t=Terminal", footerGlobalMinimal},
			)
		}
		candidates = append(candidates, []string{footerSessionsCompact, footerGlobalMinimal})
	}
	candidates = append(candidates, []string{navigation, footerGlobalMinimal}, []string{pane, footerGlobalMinimal})
	candidates = append(candidates, []string{footerGlobalMinimal})
	if width <= 0 { // not sized yet: nothing to fit
		return strings.Join(candidates[0], footerGroupGap)
	}
	for _, groups := range candidates {
		if text := strings.Join(groups, footerGroupGap); lipgloss.Width(text) <= width {
			return text
		}
	}
	return components.TruncateHead(footerGlobalMinimal, width)
}

Dashboard.handleAttach.src:
// handleAttach attaches to selected session.
func (d *Dashboard) handleAttach() (tea.Cmd, bool) {
	if d.focusedPane != PaneSessions {
		return nil, false
	}

	sess, ok := d.sessionList.Selected()
	if !ok {
		return nil, true
	}
	if !sess.Attach.Enabled {
		return availabilityFeedback(sess.Attach), true
	}

	if d.callbacks.OnAttach != nil {
		return d.callbacks.OnAttach(sess.ID), true
	}

	return nil, true
}

Dashboard.handleDelete.src:
// handleDelete shows delete confirmation.
func (d *Dashboard) handleDelete() (tea.Cmd, bool) {
	if d.focusedPane == PaneSessions {
		return d.handleDeleteSession()
	}

	if d.focusedPane == PaneCards {
		return d.handleDeleteCard()
	}

	return nil, false
}

Dashboard.handleDeleteCard.src:
func (d *Dashboard) handleDeleteCard() (tea.Cmd, bool) {
	card, ok := d.cardList.Selected()
	if !ok {
		return nil, false
	}
	if !card.Delete.Enabled {
		if card.Retry.Enabled && d.callbacks.OnRetryCardDeletion != nil {
			return d.callbacks.OnRetryCardDeletion(card.ID), true
		}
		return availabilityFeedback(card.Delete), true
	}

	d.pending = PendingAction{
		Code:   "delete-card",
		CardID: card.ID,
	}
	if card.Shared {
		d.deleteModal.SetContent("Delete this shared card globally?")
	} else {
		d.deleteModal.SetContent("Delete this ID card?")
	}
	d.deleteModal.SetLegend("Enter/y: Confirm • Esc/n: Cancel")
	d.deleteModal.Open()
	return nil, true
}

Dashboard.handleDeleteSession.src:
func (d *Dashboard) handleDeleteSession() (tea.Cmd, bool) {
	sess, ok := d.sessionList.Selected()
	if !ok {
		return nil, false
	}

	if !sess.Remove.Enabled {
		return availabilityFeedback(sess.Remove), true
	}

	if sess.TemporaryWorkspace {
		d.pending = PendingAction{
			Code:      "delete-session",
			SessionID: sess.ID,
		}
		d.deleteModal.SetContent("Delete session and its temporary workspace?")
		d.deleteModal.SetLegend("Enter/y: Confirm • Esc/n: Cancel")
		d.deleteModal.Open()
		return nil, true
	}

	if d.callbacks.OnRemove == nil {
		return nil, true
	}

	cmd, err := d.callbacks.OnRemove(sess.ID)
	if err != nil {
		return func() tea.Msg {
			return messages.ErrorMsg{Err: err}
		}, true
	}
	return cmd, true
}

Dashboard.handleEdit.src:
func (d *Dashboard) handleEdit() (tea.Cmd, bool) {
	//nolint:nestif // Card deletion has separate ownership and confirmation paths.
	if d.focusedPane == PaneCards {
		if card, ok := d.cardList.Selected(); ok {
			if !card.Edit.Enabled && !card.Inspect.Enabled {
				return nil, true
			}
			if d.callbacks.OnEditCard != nil {
				return d.callbacks.OnEditCard(card.ID), true
			}
		}
	}
	if d.focusedPane == PaneSessions {
		if sess, ok := d.sessionList.Selected(); ok && sess.Rename.Enabled {
			d.renameSessionID = sess.ID
			d.renameInput.SetValue(sess.Name)
			d.renameInput.Focus()
			d.renamePending = false
			d.renameErr = nil
			d.renameModal.Open()
		}
	}
	return nil, true
}

Dashboard.handleEnter.src:
// handleEnter processes enter key based on focused pane.
func (d *Dashboard) handleEnter() (tea.Cmd, bool) {
	if d.focusedPane == PaneSessions {
		return d.handleSessionEnter()
	}

	if card, ok := d.cardList.Selected(); ok {
		if !card.Launch.Enabled {
			return availabilityFeedback(card.Launch), true
		}
		if d.callbacks.OnLaunchCard != nil {
			return d.callbacks.OnLaunchCard(card.ID), true
		}
	}
	return nil, true
}

Dashboard.handleKey.src:
// handleKey processes global dashboard key events.
func (d *Dashboard) handleKey(keyMsg tea.KeyPressMsg) (tea.Cmd, bool) {
	// Handle search input
	if handled := d.handleSearch(keyMsg); handled {
		return nil, true
	}

	if keyMsg.String() == "ctrl+c" {
		return tea.Quit, true
	}

	switch keyMsg.Code {
	case tea.KeyEsc:
		if d.callbacks.OnBack != nil {
			return d.callbacks.OnBack(), true
		}
		return nil, true
	case tea.KeyTab:
		d.togglePane()
		return nil, true
	case tea.KeyEnter:
		return d.handleEnter()
	case tea.KeyBackspace, tea.KeyDelete:
		return d.handleDelete()
	}

	if keyMsg.String() == keyShiftTab || keyMsg.Code == tea.KeyLeft || keyMsg.Code == tea.KeyRight {
		d.togglePane()
		return nil, true
	}

	if len(keyMsg.Text) > 0 {
		switch keyMsg.String() {
		case "q":
			return tea.Quit, true
		case "n":
			return d.handleNewCard()
		case "e":
			return d.handleEdit()
		case "m":
			return d.handleOpenMCP()
		case "w":
			return d.handleOpenWorkspaces()
		case "c":
			return d.handleOpenSettings()
		case "o":
			return d.handleLaunchSession(d.callbacks.OnLaunchIDE, sessionIDEAvailability)
		case "t":
			return d.handleLaunchSession(d.callbacks.OnLaunchTerminal, sessionTerminalAvailability)
		case "a":
			return d.handleAttach()
		case "x":
			return d.handleKill()
		case "s":
			return d.handleSwitch()
		case "r":
			if card, ok := d.cardList.Selected(); d.focusedPane == PaneCards && ok && card.Retry.Enabled &&
				d.callbacks.OnRetryCardDeletion != nil {
				return d.callbacks.OnRetryCardDeletion(card.ID), true
			}
		}
	}

	return nil, false
}

Dashboard.handleKill.src:
// handleKill kills the selected session.
func (d *Dashboard) handleKill() (tea.Cmd, bool) {
	if d.focusedPane != PaneSessions {
		return nil, false
	}

	sess, ok := d.sessionList.Selected()
	if !ok {
		return nil, true
	}

	if !sess.Stop.Enabled {
		return availabilityFeedback(sess.Stop), true
	}

	if d.callbacks.OnKill == nil {
		return nil, true
	}

	cmd, err := d.callbacks.OnKill(sess.ID)
	if err != nil {
		return func() tea.Msg {
			return messages.ErrorMsg{Err: err}
		}, true
	}
	return cmd, true
}

