Dashboard.syncCenterSelection.src:
func (d *Dashboard) syncCenterSelection() {
	// If there are no sessions at all, clear center.
	if len(d.sessionRows) == 0 {
		d.center.Clear()
		return
	}

	// Check if current center session still exists
	currentStillExists := false
	var currentSession *models.SessionRow
	if d.center.SessionID() != "" {
		for i := range d.sessionRows {
			if d.sessionRows[i].ID == d.center.SessionID() {
				currentStillExists = true
				currentSession = &d.sessionRows[i]
				break
			}
		}
	}

	// If we are NOT in sessions pane AND current center still exists, just refresh it.
	if d.focusedPane != PaneSessions && currentStillExists {
		d.center.SetSession(currentSession)
		return
	}

	// Otherwise, try to follow selection.
	selected, ok := d.sessionList.Selected()
	if !ok {
		if len(d.sessionRows) == 0 {
			d.center.Clear()
			return
		}
		currentSession = &d.sessionRows[0]
	} else {
		for index := range d.sessionRows {
			if d.sessionRows[index].ID == selected.ID {
				currentSession = &d.sessionRows[index]
				break
			}
		}
	}
	if currentSession == nil {
		d.center.Clear()
		return
	}
	d.center.SetSession(currentSession)
}

Dashboard.togglePane.src:
// togglePane switches between cards and sessions.
func (d *Dashboard) togglePane() {
	if d.focusedPane == PaneCards && len(d.sessionRows) > 0 {
		d.focusedPane = PaneSessions
	} else {
		d.focusedPane = PaneCards
	}
	d.syncCenterSelection()
}

Dashboard.updateCardImpact.src:
func (d *Dashboard) updateCardImpact(msg tea.Msg) (component.Model, tea.Cmd) {
	if key, ok := msg.(tea.KeyPressMsg); ok {
		if key.Code == tea.KeyEsc {
			d.cardImpactOpen = false
			return d, nil
		}
		if key.Code == tea.KeyEnter {
			id, token := d.cardImpactID, d.cardImpactToken
			d.cardImpactOpen = false
			if d.callbacks.OnConfirmCardDeletion != nil {
				return d, d.callbacks.OnConfirmCardDeletion(id, token, true)
			}
			return d, nil
		}
	}
	var cmd tea.Cmd
	d.cardImpactViewport, cmd = d.cardImpactViewport.Update(msg)
	return d, cmd
}

Dashboard.updateDeleteModal.src:
// updateDeleteModal handles delete confirmation modal.
func (d *Dashboard) updateDeleteModal(msg tea.Msg) (component.Model, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return d, nil
	}

	switch keyMsg.Code {
	case tea.KeyEnter:
		return d.confirmDelete()
	case tea.KeyEsc:
		d.deleteModal.Close()
		d.pending = PendingAction{}
		return d, nil
	default:
		if len(keyMsg.Text) > 0 {
			switch keyMsg.String() {
			case "y":
				return d.confirmDelete()
			case "n":
				d.deleteModal.Close()
				d.pending = PendingAction{}
				return d, nil
			}
		}
	}

	return d, nil
}

Dashboard.updateFocusedPane.src:
// updateFocusedPane routes update to focused pane.
func (d *Dashboard) updateFocusedPane(msg tea.Msg) (component.Model, tea.Cmd) {
	var cmd tea.Cmd

	if d.focusedPane == PaneSessions {
		model, c := d.sessionList.Update(msg)
		d.sessionList, _ = model.(*components.SessionList)
		cmd = c

		d.syncCenterSelection()
	} else {
		model, c := d.cardList.Update(msg)
		d.cardList, _ = model.(*components.CardList)
		cmd = c
	}

	return d, cmd
}

Dashboard.updateRename.src:
func (d *Dashboard) updateRename(msg tea.Msg) (component.Model, tea.Cmd) {
	key, isKey := msg.(tea.KeyPressMsg)
	if isKey && key.String() == keyCtrlC {
		return d, tea.Quit
	}
	if isKey && !d.renamePending {
		switch key.Code {
		case tea.KeyEsc:
			d.closeRename()
			return d, nil
		case tea.KeyEnter:
			name := strings.TrimSpace(d.renameInput.Value())
			if name == "" {
				name = d.renameSessionID
			}
			if d.callbacks.OnRenameSession != nil {
				d.renamePending = true
				return d, d.callbacks.OnRenameSession(d.renameSessionID, name)
			}
			return d, nil
		}
	}
	if d.renamePending {
		return d, nil
	}
	var cmd tea.Cmd
	d.renameInput, cmd = d.renameInput.Update(msg)
	return d, cmd
}

DashboardList.CancelDeletionInteraction.src:
// CancelDeletionInteraction discards confirmation state from a past visit.
func (v *DashboardList) CancelDeletionInteraction() {
	v.statusSummary = nil
	v.statusRetry = nil
	v.statusRetryAllowed = false
	if v.mode == dashboardListModePreparing || v.mode == dashboardListModeConfirm || v.mode == dashboardListModeForeign ||
		v.mode == dashboardListModeStatus {
		v.mode = dashboardListModeList
		v.pending = messages.DashboardDeletionPreparedMsg{}
		v.preparingStatus = false
	}
}

DashboardList.SetDashboards.src:
// SetDashboards preserves selection by immutable ID when the inventory refreshes.
func (v *DashboardList) SetDashboards(dashboards []contracts.DashboardSummary) {
	selected, _ := v.selected()
	items := make([]list.Item, 0, len(dashboards))
	selection := 0
	for index, dashboard := range dashboards {
		items = append(items, dashboardItem{dashboard: dashboard})
		if dashboard.ID == selected.ID {
			selection = index
		}
	}
	v.list.SetItems(items)
	if len(items) > 0 {
		v.list.Select(selection)
	}
}

DashboardList.SetSize.src:
func (v *DashboardList) SetSize(width, height int) {
	v.Base.SetSize(width, height)
	v.list.SetSize(max(1, width-dashboardListInset), max(1, height-dashboardListVerticalInset))
	v.viewport.SetWidth(max(1, width-dashboardListViewportInset))
	v.viewport.SetHeight(max(1, height-dashboardListVerticalInset))
	for index := range v.inputs {
		v.inputs[index].SetWidth(max(1, width-dashboardListInputInset))
	}
}

DashboardList.ShowDeletionResult.src:
// ShowDeletionResult retains the execution outcome independently of inventory reads.
func (v *DashboardList) ShowDeletionResult(id string, summary []string, allowRetry bool) {
	lines := make([]string, 0, len(summary))
	for _, line := range summary {
		lines = append(lines, components.DisplayText(line))
	}
	if v.statusSummary == nil {
		v.statusSummary = make(map[string][]string)
		v.statusRetry = make(map[string]bool)
	}
	v.statusSummary[id] = append([]string(nil), lines...)
	v.statusRetry[id] = allowRetry
	v.pending = messages.DashboardDeletionPreparedMsg{DashboardID: id}
	v.statusRetryAllowed = allowRetry
	v.viewport.SetContent(strings.Join(lines, "\n"))
	v.mode = dashboardListModeStatus
}

DashboardList.Update.src:
//nolint:gocognit,gocyclo,cyclop,funlen // All modal states are handled in this state machine.
func (v *DashboardList) Update(msg tea.Msg) (component.Model, tea.Cmd) {
	if status, ok := msg.(messages.DashboardDeletionStatusMsg); ok {
		v.handleDeletionStatus(status)
		return v, nil
	}
	if prepared, ok := msg.(messages.DashboardDeletionPreparedMsg); ok {
		if v.mode != dashboardListModePreparing || v.preparingStatus || prepared.DashboardID != v.pending.DashboardID {
			return v, nil
		}
		if prepared.Err != nil {
			v.err = prepared.Err
			v.mode = dashboardListModeList
			return v, nil
		}
		v.err = nil
		v.pending = prepared
		lines := make([]string, 0, len(prepared.Summary)+1)
		for _, line := range prepared.Summary {
			lines = append(lines, components.DisplayText(line))
		}
		v.viewport.SetContent(strings.Join(lines, "\n"))
		v.mode = dashboardListModeConfirm
		return v, nil
	}
	if v.mode == dashboardListModeForm {
		return v.updateForm(msg)
	}
	if v.mode != dashboardListModeList {
		return v.updateConfirmation(msg)
	}
	key, ok := msg.(tea.KeyPressMsg)
	if ok {
		dashboard, selected := v.selected()
		switch {
		case key.Code == tea.KeyEnter && selected && dashboard.Open.Enabled:
			if v.callbacks.Open != nil {
				return v, v.callbacks.Open(dashboard)
			}
		case key.Code == tea.KeyEnter && selected && dashboard.Inspect.Enabled:
			if v.callbacks.InspectDelete != nil {
				v.err = nil
				v.pending = messages.DashboardDeletionPreparedMsg{DashboardID: dashboard.ID}
				v.mode = dashboardListModePreparing
				v.preparingStatus = true
				return v, v.callbacks.InspectDelete(dashboard.ID)
			}
		case key.Text == "n":
			v.openForm(contracts.DashboardSummary{})
		case key.Text == "e" && selected && dashboard.Edit.Enabled:
			v.openForm(dashboard)
		case (key.Code == tea.KeyDelete || key.Code == tea.KeyBackspace) && selected && dashboard.Delete.Enabled:
			if v.callbacks.PreflightDelete != nil {
				v.err = nil
				v.pending = messages.DashboardDeletionPreparedMsg{DashboardID: dashboard.ID}
				v.mode = dashboardListModePreparing
				v.preparingStatus = false
				return v, v.callbacks.PreflightDelete(dashboard.ID)
			}
		case (key.Code == tea.KeyDelete || key.Code == tea.KeyBackspace) && selected && dashboard.Retry.Enabled:
			return v, v.retryDeletion(dashboard.ID)
		case key.Text == "q":
			return v, tea.Quit
		}
	}
	var cmd tea.Cmd
	v.list, cmd = v.list.Update(msg)
	return v, cmd
}

DashboardList.View.src:
func (v *DashboardList) View() string {
	width := max(1, v.Width)
	if v.mode == dashboardListModeForm {
		body := styles.LabelStyle.Render("Name") + "\n" + v.inputs[0].View() +
			"\n\n" + styles.LabelStyle.Render("Description") + "\n" + v.inputs[1].View()
		if v.err != nil {
			body += "\n" + styles.ErrorStyle.Render(components.DisplayText(v.err.Error()))
		}
		return v.renderPage("Dashboard details", body, "Tab: next  Enter: save  Esc: cancel")
	}
	if v.mode == dashboardListModePreparing {
		return v.renderPage("Preparing deletion impact…", "", "Esc: cancel")
	}
	if v.mode == dashboardListModeStatus {
		legend := "Esc: back  ↑/↓: scroll"
		if v.statusRetryAllowed {
			legend = "Delete: retry  " + legend
		}
		return v.renderPage("Dashboard deletion progress", v.viewport.View(), legend)
	}
	if v.mode == dashboardListModeForeign {
		return v.renderPage("Foreign sessions reference owned cards.",
			"Owned shared cards will be deleted globally; foreign sessions survive.",
			"Enter: confirm global deletion  Esc: cancel")
	}
	if v.mode == dashboardListModeConfirm {
		return v.renderPage("Delete dashboard and its owned sessions and cards?", v.viewport.View(),
			"Enter: continue  Esc: cancel  ↑/↓: scroll")
	}
	body := ""
	if v.err != nil {
		message := components.TruncateHead("Error: "+components.DisplayText(v.err.Error()), max(1, width-dashboardListInset))
		body = styles.ErrorStyle.Render(message) + "\n"
	}
	if _, selected := v.selected(); !selected {
		return v.renderPage("Dashboards", body+styles.HelpStyle.Render("No dashboards. Press n to create one."), "n: new  q: quit")
	}
	dashboard, _ := v.selected()
	detail := components.TruncateTail("ID: "+components.DisplayText(dashboard.ID), max(1, width-dashboardListInset))
	items := v.list
	if v.err != nil {
		items.SetHeight(max(1, items.Height()-1))
	}
	help := "Enter: open  n: new  e: edit  Delete: remove  q: quit"
	if dashboard.State == contracts.DashboardDeleting {
		help = "Enter: details  Delete: retry  n: new  q: quit"
	}
	return v.renderPage("Dashboards", body+items.View()+"\n"+styles.HelpStyle.Render(detail), help)
}

DashboardList.confirmDeletion.src:
func (v *DashboardList) confirmDeletion(foreign bool) (component.Model, tea.Cmd) {
	pending := v.pending
	v.mode, v.pending = dashboardListModeList, messages.DashboardDeletionPreparedMsg{}
	if v.callbacks.ConfirmDelete != nil {
		return v, v.callbacks.ConfirmDelete(pending.DashboardID, pending.Token, foreign)
	}
	return v, nil
}

DashboardList.handleDeletionStatus.src:
func (v *DashboardList) handleDeletionStatus(status messages.DashboardDeletionStatusMsg) {
	if v.mode != dashboardListModePreparing || !v.preparingStatus || status.DashboardID != v.pending.DashboardID {
		return
	}
	if status.Err != nil {
		v.err = status.Err
		if previous, exists := v.statusSummary[status.DashboardID]; exists {
			lines := append([]string{"Error: " + components.DisplayText(status.Err.Error())}, previous...)
			v.viewport.SetContent(strings.Join(lines, "\n"))
			v.statusRetryAllowed = v.statusRetry[status.DashboardID]
			v.mode = dashboardListModeStatus
			return
		}
		v.mode = dashboardListModeList
		return
	}
	v.err = nil
	lines := make([]string, 0, len(status.Summary))
	for _, line := range status.Summary {
		lines = append(lines, components.DisplayText(line))
	}
	if v.statusSummary == nil {
		v.statusSummary = make(map[string][]string)
		v.statusRetry = make(map[string]bool)
	}
	if len(lines) == 0 {
		delete(v.statusSummary, status.DashboardID)
		delete(v.statusRetry, status.DashboardID)
	} else {
		v.statusSummary[status.DashboardID] = append([]string(nil), lines...)
		v.statusRetry[status.DashboardID] = true
	}
	v.viewport.SetContent(strings.Join(lines, "\n"))
	v.statusRetryAllowed = true
	v.mode = dashboardListModeStatus
}

DashboardList.retryDeletion.src:
func (v *DashboardList) retryDeletion(id string) tea.Cmd {
	v.mode, v.pending, v.err = dashboardListModeList, messages.DashboardDeletionPreparedMsg{}, nil
	if v.callbacks.RetryDelete != nil {
		return v.callbacks.RetryDelete(id)
	}
	return nil
}

