SettingsView.syncFocus.src:
func (s *SettingsView) syncFocus() {
	if s.focus == settingsFocusIDECommand {
		s.input.Focus()
		s.terminalInput.Blur()
		return
	}
	if s.focus == settingsFocusTerminalCommand {
		s.input.Blur()
		s.terminalInput.Focus()
		return
	}
	s.input.Blur()
	s.terminalInput.Blur()
}

SettingsView.updateDisplay.src:
func (s *SettingsView) updateDisplay(msg tea.Msg) (component.Model, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return s, nil
	}

	if keyMsg.String() == keyCtrlC {
		return s, tea.Quit
	}

	switch keyMsg.Code {
	case tea.KeyEsc:
		if s.callbacks.OnBack != nil {
			return s, s.callbacks.OnBack()
		}
		return s, nil
	case tea.KeyEnter:
		if s.saving {
			return s, nil
		}
		s.startEdit()
		return s, nil
	default:
		if len(keyMsg.Text) > 0 {
			switch keyMsg.String() {
			case "e":
				if s.saving {
					return s, nil
				}
				s.startEdit()
				return s, nil
			case "p":
				if s.callbacks.OnOpenPuppetSources != nil {
					return s, s.callbacks.OnOpenPuppetSources()
				}
			}
		}
	}

	return s, nil
}

SourceManager.Reload.src:
// Reload schedules a fresh read without replacing an in-flight mutation.
func (m *SourceManager) Reload() tea.Cmd {
	if m.pending {
		return nil
	}
	return m.load()
}

SourceManager.SetSize.src:
func (m *SourceManager) SetSize(width, height int) {
	m.Base.SetSize(width, height)
	m.sourceList.SetSize(width, height)
}

SourceManager.Update.src:
func (m *SourceManager) Update(msg tea.Msg) (component.Model, tea.Cmd) {
	switch value := msg.(type) {
	case sourceLoaded:
		return m, m.handleSourceLoaded(value)
	case sourceMutated:
		return m, m.handleSourceMutated(value)
	case sourceSynced:
		return m, m.handleSourceSynced(value)
	case tea.KeyPressMsg:
		if value.Code == tea.KeyEsc && m.sourceList.Mode == components.SourceListModeList {
			return m, func() tea.Msg { return messages.NavigateBackMsg{} }
		}
		if m.pending {
			return m, nil
		}
	}
	model, cmd := m.sourceList.Update(msg)
	if list, ok := model.(*components.SourceList); ok {
		m.sourceList = list
	}
	return m, cmd
}

SourceManager.handleSourceLoaded.src:
func (m *SourceManager) handleSourceLoaded(value sourceLoaded) tea.Cmd {
	if value.kind != m.sourceType || value.visit != m.visit || value.request != m.request {
		return nil
	}
	if value.err != nil {
		return func() tea.Msg { return messages.ErrorMsg{Err: value.err} }
	}
	items := make([]components.SourceItem, 0, len(value.rows))
	for _, row := range value.rows {
		if m.sourceType == SourceTypeWorkspaces {
			items = append(items, components.WorkspaceSourceItem{Source: row})
		} else {
			items = append(items, components.PathSourceItem{Path: row.Path, Identity: row.Identity})
		}
	}
	m.sourceList.SetItems(items)
	return nil
}

SourceManager.handleSourceMutated.src:
func (m *SourceManager) handleSourceMutated(value sourceMutated) tea.Cmd {
	if value.kind != m.sourceType || value.visit != m.visit || value.request != m.request {
		return nil
	}
	m.pending = false
	result := value.result
	if result.Saved {
		m.sourceList.Mode = components.SourceListModeList
	}
	var load tea.Cmd
	if result.Saved || result.Reload {
		load = m.load()
	}
	err := result.Err
	if err == nil {
		err = result.Warning
	}
	if err != nil {
		return tea.Batch(load, func() tea.Msg { return messages.ErrorMsg{Err: err} })
	}
	return load
}

SourceManager.handleSourceSynced.src:
func (m *SourceManager) handleSourceSynced(value sourceSynced) tea.Cmd {
	if value.kind != m.sourceType || value.visit != m.visit || value.request != m.request {
		return nil
	}
	m.pending = false
	if value.result.Err != nil {
		err := value.result.Err
		return tea.Batch(m.load(), func() tea.Msg { return messages.ErrorMsg{Err: err} })
	}
	return m.load()
}

SourceManager.load.src:
func (m *SourceManager) load() tea.Cmd {
	if m.callbacks.Load == nil {
		return nil
	}
	m.request++
	load, kind, visit, request := m.callbacks.Load, m.sourceType, m.visit, m.request
	return func() tea.Msg {
		rows, err := load(contracts.SourceKind(kind))
		return sourceLoaded{kind: kind, visit: visit, request: request, rows: rows, err: err}
	}
}

SourceManager.mutate.src:
func (m *SourceManager) mutate(input contracts.SourceMutation) tea.Cmd {
	if m.callbacks.Mutate == nil {
		return nil
	}
	m.pending = true
	m.request++
	mutate, kind, visit, request := m.callbacks.Mutate, m.sourceType, m.visit, m.request
	return func() tea.Msg {
		result := mutate(context.Background(), input)
		msg := sourceMutated{kind: kind, visit: visit, request: request, result: result}
		if result.Refresh {
			return tea.Batch(func() tea.Msg { return msg }, func() tea.Msg { return messages.DataRefreshRequestedMsg{} })()
		}
		return msg
	}
}

SourceManager.sync.src:
func (m *SourceManager) sync() tea.Cmd {
	if m.pending || m.callbacks.Sync == nil {
		return nil
	}
	m.pending = true
	m.request++
	sync, kind, visit, request := m.callbacks.Sync, m.sourceType, m.visit, m.request
	return func() tea.Msg {
		result := sync(context.Background(), contracts.SourceKind(kind))
		msg := sourceSynced{kind: kind, visit: visit, request: request, result: result}
		if result.Refresh {
			return tea.Batch(func() tea.Msg { return msg }, func() tea.Msg { return messages.DataRefreshRequestedMsg{} })()
		}
		return msg
	}
}

WorkspacePickerModal.Open.src:
func (m *WorkspacePickerModal) Open() {
	m.ModalState.Open()
	// Reset transient state to ensure clean state on reopen
	m.resetTransientState()
}

WorkspacePickerModal.SelectedID.src:
func (m *WorkspacePickerModal) SelectedID() string {
	if m.selectedMissing {
		return m.selectedID
	}
	if item := m.list.SelectedItem(); item != nil {
		if wi, ok := item.(workspaceItem); ok {
			return wi.workspace.ID
		}
	}
	return m.selectedID
}

WorkspacePickerModal.SelectedIDs.src:
func (m *WorkspacePickerModal) SelectedIDs() []string {
	out := make([]string, 0, len(m.checked))
	for _, ws := range m.workspaces {
		if m.checked[ws.ID] {
			out = append(out, ws.ID)
		}
	}
	for _, id := range m.selectedIDs {
		if m.checked[id] {
			found := false
			for _, ws := range m.workspaces {
				if ws.ID == id {
					found = true
					break
				}
			}
			if !found {
				out = append(out, id)
			}
		}
	}
	return out
}

WorkspacePickerModal.SetSelectedID.src:
func (m *WorkspacePickerModal) SetSelectedID(id string) {
	m.multiple = false
	m.selectedID = id
	m.restoreSingleSelection()
}

WorkspacePickerModal.SetSelectedIDs.src:
func (m *WorkspacePickerModal) SetSelectedIDs(ids []string) {
	m.multiple = true
	m.selectedIDs = append([]string(nil), ids...)
	m.checked = make(map[string]bool)
	m.selectedWorkspaceInfo = make(map[string]models.WorkspaceOption)
	for _, id := range ids {
		m.checked[id] = true
		for _, workspace := range m.workspaces {
			if workspace.ID == id {
				m.rememberWorkspace(workspace)
				break
			}
		}
	}
	m.refreshItems()
}

WorkspacePickerModal.SetSize.src:
func (m *WorkspacePickerModal) SetSize(width, height int) {
	m.Base.SetSize(width, height)

	// Never larger than the space given, or Place cannot centre it and the
	// editor's view stops being the size of its box.
	m.modalWidth = min(width, max(40, width*2/3)) //nolint:mnd // responsive sizing
	m.modalHeight = height

	m.applyListSize()
}

WorkspacePickerModal.SetWorkspaces.src:
func (m *WorkspacePickerModal) SetWorkspaces(workspaces []models.WorkspaceOption) {
	// Preserve the current highlighted option, including changes made by search.
	// SelectedID retains a previously unresolved identity when no option is active.
	if !m.multiple {
		m.selectedID = m.SelectedID()
	}
	for _, workspace := range m.workspaces {
		if m.checked[workspace.ID] {
			m.rememberWorkspace(workspace)
		}
	}
	m.workspaces = slices.Clone(workspaces)
	m.refreshItems()
	if !m.multiple {
		m.restoreSingleSelection()
	}
}

WorkspacePickerModal.Update.src:
//nolint:gocognit,nestif // modal key handling preserves distinct confirm/cancel/search behavior.
func (m *WorkspacePickerModal) Update(msg tea.Msg) (component.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch keyMsg.Code {
		case tea.KeyUp, tea.KeyDown:
			// Record the destination after the list processes the navigation key.
		case tea.KeyEnter:
			if m.multiple {
				m.Confirm()
				m.selectedIDs = m.SelectedIDs()
				m.resetTransientState()
				return m, nil
			}
			m.Confirm()
			// Save the currently selected workspace before resetting state
			m.selectedID = m.SelectedID()
			// Reset transient state before closing to prepare for next open
			m.resetTransientState()
			return m, nil
		case tea.KeyEsc:
			if m.searchQuery != "" {
				m.searchQuery = ""
				m.refreshSearch()
				return m, nil
			}
			m.Cancel()
			// Reset transient state before closing to prepare for next open
			m.resetTransientState()
			return m, nil
		case tea.KeyBackspace:
			if len(m.searchQuery) > 0 {
				m.searchQuery = m.searchQuery[:len(m.searchQuery)-1]
				m.refreshSearch()
			}
			return m, nil
		case tea.KeySpace:
			if m.multiple {
				if item := m.list.SelectedItem(); item != nil {
					wi, itemOK := item.(workspaceItem)
					if !itemOK {
						return m, nil
					}
					m.toggleChecked(wi.workspace.ID)
					m.refreshItems()
				}
				return m, nil
			}
			if keyMsg.Text != "" {
				m.searchQuery += keyMsg.Text
				m.refreshSearch()
			}
			return m, nil
		default:
			if len(keyMsg.Text) > 0 {
				m.searchQuery += keyMsg.Text
				m.refreshSearch()
				return m, nil
			}
		}
	}

	var cmd tea.Cmd
	m.list, cmd = m.list.Update(msg)
	m.rememberSingleNavigation(msg)
	return m, cmd
}

WorkspacePickerModal.View.src:
func (m *WorkspacePickerModal) View() string {
	boxStyle := lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("#8E44AD")).
		Padding(heightPadding, widthPadding).
		Width(m.modalWidth).
		Height(m.modalHeight)
	pickerHelpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	help := "Enter=select • Esc=back • Type to search"
	if m.multiple {
		help = "Space=toggle • Enter=confirm • Esc=back • Type to search"
	}
	if m.searchQuery != "" {
		if m.multiple {
			help = "Space=toggle • Enter=confirm • Esc=clear search • Type to search"
		} else {
			help = "Enter=select • Esc=clear search • Type to search"
		}
	}

	// The search row is always there, blank until a query is typed, so the
	// legend's row does not depend on whether a search is active.
	searchRow := ""
	if m.searchQuery != "" {
		searchRow = lipgloss.NewStyle().
			Foreground(lipgloss.Color("#ADF")).
			Render("Search: " + components.TruncateTail(
				components.DisplayText(m.searchQuery),
				max(0, m.modalWidth-pickerBoxChrome-len("Search: ")),
			))
	}

	// Nothing here is positioned against its neighbours' content. The list is
	// padded to the width it was given (bubbles pads only to its widest line,
	// which changes from page to page) and everything is joined left-aligned,
	// so the legend is left-aligned with the list and sits at a fixed place.
	return boxStyle.Render(
		lipgloss.JoinVertical(lipgloss.Left,
			lipgloss.NewStyle().Width(m.listWidth).Render(m.list.View()),
			"",
			searchRow,
			"",
			"",
			pickerHelpStyle.Render(help),
		),
	)
}

WorkspacePickerModal.applyListSize.src:
// applyListSize sizes the list to fit within the box and leaves room for the
// search row and the legend. listWidth is the width View gives the list's block.
func (m *WorkspacePickerModal) applyListSize() {
	m.listWidth = max(1, m.modalWidth-widthPadding*2-workspacePickerListWidthPadding)
	listHeight := max(1, m.modalHeight-heightPadding*2-workspacePickerListHeightPadding)
	m.list.SetSize(m.listWidth, listHeight)
}

WorkspacePickerModal.filterWorkspaces.src:
func (m *WorkspacePickerModal) filterWorkspaces() []models.WorkspaceOption {
	workspaces := make([]models.WorkspaceOption, 0, len(m.workspaces)+len(m.checked))
	registered := make(map[string]bool, len(m.workspaces))
	for _, ws := range m.workspaces {
		registered[ws.ID] = true
		if m.multiple && ws.ID == m.excludedID && !m.checked[ws.ID] {
			continue
		}
		workspaces = append(workspaces, ws)
	}
	if m.multiple {
		for _, id := range m.selectedIDs {
			if registered[id] || !m.checked[id] {
				continue
			}
			workspace := m.selectedWorkspaceInfo[id]
			name := "[missing] " + id
			path := "Not in workspace registry"
			if workspace.Name != "" {
				name = "[missing] " + workspace.Name + " (" + id + ")"
				path = workspace.Path
			}
			workspaces = append(workspaces, models.WorkspaceOption{ID: id, Name: name, Path: path})
		}
	}
	return components.Filter(workspaces, m.searchQuery, func(ws models.WorkspaceOption) string {
		return ws.Name + " " + ws.Path
	})
}

WorkspacePickerModal.normalizeSelection.src:
// normalizeSelection ensures the selected index is valid for the current filtered list.
func (m *WorkspacePickerModal) normalizeSelection() {
	items := m.list.Items()
	if len(items) == 0 {
		return
	}

	currentIndex := m.list.Index()
	if currentIndex < 0 || currentIndex >= len(items) {
		m.list.Select(0)
	}
}

WorkspacePickerModal.rebuildList.src:
// rebuildList recreates the list.Model to ensure clean state.
func (m *WorkspacePickerModal) rebuildList() {
	delegate := list.NewDefaultDelegate()
	delegate.SetHeight(workspacePickerDelegateHeight)

	workspaces := m.filterWorkspaces()
	items := make([]list.Item, len(workspaces))
	for i, ws := range workspaces {
		items[i] = workspaceItem{workspace: ws, checked: m.multiple && m.checked[ws.ID], multiple: m.multiple}
	}

	l := list.New(items, delegate, 40, 30) //nolint:mnd // responsive sizing
	l.SetShowTitle(true)
	l.Title = m.title()
	l.SetShowStatusBar(false)
	l.SetFilteringEnabled(false) // Use manual filtering

	m.list = l

	// Restore the current size to preserve terminal dimensions
	if m.modalWidth > 0 && m.modalHeight > 0 {
		m.applyListSize()
	}

	if !m.multiple {
		m.restoreSingleSelection()
	}
}

WorkspacePickerModal.refreshItems.src:
func (m *WorkspacePickerModal) refreshItems() {
	filtered := m.filterWorkspaces()
	items := make([]list.Item, len(filtered))
	for i, ws := range filtered {
		items[i] = workspaceItem{workspace: ws, checked: m.multiple && m.checked[ws.ID], multiple: m.multiple}
	}
	m.list.SetItems(items)
	// Normalize selection after refreshing items
	m.normalizeSelection()
}

WorkspacePickerModal.refreshSearch.src:
// refreshSearch records an explicit filtered choice without replacing an
// unresolved selection when the query has no results.
func (m *WorkspacePickerModal) refreshSearch() {
	m.refreshItems()
	if m.multiple {
		return
	}
	if m.searchQuery == "" {
		m.restoreSingleSelection()
		return
	}
	if item, ok := m.list.SelectedItem().(workspaceItem); ok {
		m.selectedID = item.workspace.ID
		m.selectedMissing = false
	}
}

WorkspacePickerModal.rememberSingleNavig.src:
func (m *WorkspacePickerModal) rememberSingleNavigation(msg tea.Msg) {
	key, ok := msg.(tea.KeyPressMsg)
	if !ok || m.multiple || (key.Code != tea.KeyUp && key.Code != tea.KeyDown) {
		return
	}
	item, ok := m.list.SelectedItem().(workspaceItem)
	if !ok {
		return
	}
	m.selectedID = item.workspace.ID
	m.selectedMissing = false
}

WorkspacePickerModal.rememberWorkspace.src:
func (m *WorkspacePickerModal) rememberWorkspace(workspace models.WorkspaceOption) {
	if m.selectedWorkspaceInfo == nil {
		m.selectedWorkspaceInfo = make(map[string]models.WorkspaceOption)
	}
	m.selectedWorkspaceInfo[workspace.ID] = workspace
}

WorkspacePickerModal.resetTransientState.src:
// resetTransientState clears all transient state that should not survive between openings.
func (m *WorkspacePickerModal) resetTransientState() {
	m.searchQuery = ""
	// Reset the list to clear any stale cursor/selection/paginator state
	m.rebuildList()
}

WorkspacePickerModal.restoreSingleSelect.src:
func (m *WorkspacePickerModal) restoreSingleSelection() {
	id := m.selectedID
	m.selectedMissing = false
	if id == "" {
		return
	}

	// Find the workspace in the current list items (respects filtering)
	items := m.list.Items()
	for i, item := range items {
		if wi, ok := item.(workspaceItem); ok {
			if wi.workspace.ID == id {
				m.list.Select(i)
				return
			}
		}
	}
	// Do not substitute the first option for an unresolved selection.
	m.selectedMissing = true
	if len(items) > 0 {
		m.list.Select(0)
	}
}

WorkspacePickerModal.title.src:
func (m *WorkspacePickerModal) title() string {
	if m.multiple {
		return "Select Sub Workspaces"
	}
	return "Select Workspace"
}

WorkspacePickerModal.toggleChecked.src:
func (m *WorkspacePickerModal) toggleChecked(id string) {
	if m.checked[id] {
		delete(m.checked, id)
		m.selectedIDs = removeID(m.selectedIDs, id)
		return
	}
	m.checked[id] = true
	if item := m.list.SelectedItem(); item != nil {
		if workspace, ok := item.(workspaceItem); ok {
			m.rememberWorkspace(workspace.workspace)
		}
	}
	if !slices.Contains(m.selectedIDs, id) {
		m.selectedIDs = append(m.selectedIDs, id)
	}
}

conversationChoiceItem.Description.src:
func (i conversationChoiceItem) Description() string {
	if i.new {
		return "Start fresh; saved conversations remain available"
	}
	if !i.compatible {
		return fmt.Sprintf(
			"%s | %s | %s",
			components.DisplayText(i.option.NativeID),
			components.DisplayText(i.option.Driver),
			components.DisplayText(i.option.Reason),
		)
	}
	return fmt.Sprintf("%s | %s", components.DisplayText(i.option.NativeID), components.DisplayText(i.option.Driver))
}

conversationChoiceItem.FilterValue.src:
func (i conversationChoiceItem) FilterValue() string {
	if i.new {
		return "new conversation"
	}
	return components.DisplayText(
		i.option.Name,
	) + " " + components.DisplayText(
		i.option.NativeID,
	) + " " + components.DisplayText(
		i.option.Driver,
	)
}

conversationChoiceItem.Title.src:
func (i conversationChoiceItem) Title() string {
	if i.new {
		return "New conversation"
	}
	return components.DisplayText(i.option.Name)
}

dashboardItem.Description.src:
func (i dashboardItem) Description() string {
	description := components.DisplayText(i.dashboard.Description)
	if i.dashboard.State == contracts.DashboardDeleting {
		return "Deleting — Delete to retry. " + description
	}
	return description
}

mcpManagerItem.Display.src:
func (i mcpManagerItem) Display() string {
	if i.server.Builtin {
		return i.server.Name + " (built-in, read-only)"
	}
	return i.server.Name
}

workspaceItem.Title.src:
func (i workspaceItem) Title() string {
	if !i.multiple {
		return components.DisplayText(i.workspace.Name)
	}
	mark := ""
	if i.checked {
		mark = "[x] "
	} else if i.workspace.Name != "" {
		mark = "[ ] "
	}
	return mark + components.DisplayText(i.workspace.Name)
}
